"use client";

import { createContext, useContext } from "react";
import type { ComponentType, ReactNode } from "react";
import {
  Button as AriaButton,
  Disclosure as AriaDisclosure,
  DisclosureGroup as AriaDisclosureGroup,
  DisclosurePanel as AriaDisclosurePanel,
  Heading as AriaHeading,
} from "react-aria-components";
import type { DisclosureGroupProps as AriaDisclosureGroupProps, DisclosureProps as AriaDisclosureProps } from "react-aria-components";
import { RiAddLine, RiArrowDownSLine } from "@remixicon/react";
import { cx, sortCx } from "@/lib/utils";

/**
 * Accordion — stacked sections that expand in place: FAQs, settings groups,
 * order details. Built on React Aria's DisclosureGroup and Disclosure, so
 * each header is a real button with aria-expanded, and a collapsed panel is
 * `hidden="until-found"`: find-in-page still reaches its text and opens it.
 *
 *   <Accordion defaultExpandedKeys={["billing"]}>
 *     <AccordionItem id="billing" title="How does billing work?">…</AccordionItem>
 *     <AccordionItem id="seats" title="Can I add seats later?">…</AccordionItem>
 *   </Accordion>
 *
 * Variants: `divided` (hairlines between rows), `contained` (the landing
 * FAQ's tray of cards), and `separated` (one bordered card per item).
 *
 * Motion follows the agent limits card and Tree View: the panel's height
 * eases open over 300ms on cubic-bezier(0.22, 1, 0.36, 1) while its content
 * fades in, drops 4px into place and sharpens from a 4px blur; the indicator
 * turns with it (a chevron flips, a plus turns into a close). React Aria
 * measures the panel and exposes `--disclosure-panel-height`, so this is
 * all CSS. Reduced motion switches every transition off.
 */

type IconComponent = ComponentType<{ className?: string; "aria-hidden"?: boolean | "true" | "false" }>;

export type AccordionVariant = "divided" | "contained" | "separated";

const EASE = "ease-[cubic-bezier(0.22,1,0.36,1)]";

const styles = sortCx({
  group: {
    divided: "flex flex-col divide-y divide-separator-border",
    // The landing FAQ: cards on a tray, inverted in dark mode so the cards
    // stay a step lighter than the page.
    contained: "flex flex-col gap-[3px] rounded-[26px] bg-background-secondary-default p-[3px] dark:bg-background-primary-default",
    separated: "flex flex-col gap-2",
  },
  item: {
    divided: "",
    contained: "rounded-[23px] bg-background-primary-default dark:bg-background-secondary-default",
    // Modal's ground rather than the card surface: in dark mode the inputs
    // and switch tracks a settings group holds keep an edge against it.
    separated: "rounded-2xl border border-border-button-default bg-background-full shadow-xs",
  },
  trigger: {
    divided: "rounded-lg py-4",
    contained: "rounded-[23px] px-5 py-4",
    separated: "rounded-2xl px-4 py-3.5",
  },
  content: {
    divided: "pb-4",
    contained: "px-5 pb-5",
    separated: "px-4 pb-4",
  },
});

interface AccordionContextValue {
  variant: AccordionVariant;
  indicator: "chevron" | "plus";
}

const AccordionContext = createContext<AccordionContextValue>({ variant: "divided", indicator: "chevron" });

export interface AccordionProps extends Omit<AriaDisclosureGroupProps, "className" | "children"> {
  variant?: AccordionVariant;
  /** `chevron` flips to point up; `plus` turns into a close. Default `chevron`. */
  indicator?: "chevron" | "plus";
  className?: string;
  children: ReactNode;
}

export function Accordion({ variant = "divided", indicator = "chevron", className, children, ...props }: AccordionProps) {
  return (
    <AccordionContext.Provider value={{ variant, indicator }}>
      <AriaDisclosureGroup {...props} className={cx(styles.group[variant], className)}>
        {children}
      </AriaDisclosureGroup>
    </AccordionContext.Provider>
  );
}

export interface AccordionItemProps extends Omit<AriaDisclosureProps, "className" | "children"> {
  title: ReactNode;
  /** Supporting line under the title, e.g. a summary of the settings inside. */
  description?: ReactNode;
  /** Remix Icon before the title. */
  icon?: IconComponent;
  /** Heading level of the title. Default 3. */
  headingLevel?: 2 | 3 | 4 | 5 | 6;
  className?: string;
  children: ReactNode;
}

export function AccordionItem({
  title,
  description,
  icon: Icon,
  headingLevel = 3,
  className,
  children,
  ...props
}: AccordionItemProps) {
  const { variant, indicator } = useContext(AccordionContext);
  const Indicator = indicator === "plus" ? RiAddLine : RiArrowDownSLine;

  return (
    <AriaDisclosure
      {...props}
      className={cx("group/item data-[disabled]:opacity-50", styles.item[variant], className)}
    >
      <AriaHeading level={headingLevel} className="flex">
        <AriaButton
          slot="trigger"
          className={({ isFocusVisible }) =>
            cx(
              "group/trigger flex w-full cursor-pointer items-center gap-3 text-start outline-none",
              "disabled:cursor-not-allowed",
              isFocusVisible && "ring-2 ring-border-focus-ring ring-inset",
              styles.trigger[variant],
            )
          }
        >
          {Icon ? <Icon className="size-5 shrink-0 text-foreground-icon-secondary" aria-hidden /> : null}
          <span className="flex min-w-0 flex-1 flex-col gap-0.5">
            <span className="text-headline-medium text-text-primary">{title}</span>
            {description ? <span className="text-body-regular text-text-secondary">{description}</span> : null}
          </span>
          <Indicator
            aria-hidden
            className={cx(
              "size-5 shrink-0 text-foreground-icon-tertiary transition-[rotate,color] duration-300 motion-reduce:transition-none",
              EASE,
              "group-hover/trigger:text-foreground-icon-secondary group-data-[expanded]/item:text-foreground-icon-primary",
              indicator === "plus" ? "group-data-[expanded]/item:rotate-45" : "group-data-[expanded]/item:rotate-180",
            )}
          />
        </AriaButton>
      </AriaHeading>
      <AriaDisclosurePanel
        className={cx("h-(--disclosure-panel-height) overflow-clip transition-[height] duration-300 motion-reduce:transition-none", EASE)}
      >
        <div
          className={cx(
            "text-body-regular text-text-secondary",
            "opacity-0 transition-[opacity,translate,filter] duration-300 motion-reduce:transition-none",
            "motion-safe:-translate-y-1 motion-safe:blur-[4px]",
            "group-data-[expanded]/item:translate-y-0 group-data-[expanded]/item:opacity-100 group-data-[expanded]/item:blur-[0px]",
            EASE,
            styles.content[variant],
          )}
        >
          {children}
        </div>
      </AriaDisclosurePanel>
    </AriaDisclosure>
  );
}

"use client";

import type { ReactNode } from "react";
import {
  RiAddFill,
  RiBarChartBoxLine,
  RiDashboardLine,
  RiFileList3Line,
  RiFilter3Fill,
  RiGroupLine,
  RiSettings4Line,
  RiShoppingBag3Line,
} from "@remixicon/react";

import { NotificationBell } from "../app-shell/notification-bell";
import {
  DashboardSidebar,
  type DashboardNavItem,
} from "../dashboard/dashboard-sidebar";
import { OrdersChartCard } from "../dashboard/orders-chart-card";
import { RevenueChartCard } from "../dashboard/revenue-chart-card";
import { StatCards } from "../dashboard/stat-cards";
import { DataTableExample } from "../data-table/data-table";
import { Avatar } from "../../base/avatar/avatar";
import { Breadcrumb, BreadcrumbItem } from "../../base/breadcrumb/breadcrumb";
import { Button } from "../../base/buttons/button";
import { cx } from "@/lib/utils";

/** Admin console navigation — overview through settings. */
export const ADMIN_NAV: DashboardNavItem[] = [
  { key: "overview", label: "概览", icon: RiDashboardLine, href: "#" },
  { key: "users", label: "用户", icon: RiGroupLine, href: "#", badge: 24 },
  { key: "orders", label: "订单", icon: RiShoppingBag3Line, href: "#" },
  { key: "content", label: "内容", icon: RiFileList3Line, href: "#" },
  { key: "reports", label: "报表", icon: RiBarChartBoxLine, href: "#" },
  { key: "settings", label: "设置", icon: RiSettings4Line, href: "#" },
];

/**
 * JoyUI 后台管理模板：浮动侧栏 + 顶栏操作 + KPI + 图表 + 数据表。
 * 组装自现有 JoyUI 组件，可直接替换导航、文案与数据源。
 */
export function AdminDashboard({
  className,
  selected = "overview",
  headerActions,
}: {
  className?: string;
  selected?: string;
  headerActions?: ReactNode;
} = {}) {
  return (
    <div
      className={cx(
        "relative flex h-full min-h-[640px] w-full gap-4 overflow-hidden bg-background-full p-3",
        className,
      )}
    >
      <DashboardSidebar
        items={ADMIN_NAV}
        selected={selected}
        className="flex"
      />

      <main className="relative flex min-h-0 min-w-0 flex-1 justify-center overflow-x-hidden overflow-y-auto bg-background-full sm:pt-3">
        <div className="flex w-full max-w-[1300px] flex-col gap-2.5">
          <header className="flex w-full flex-col gap-2">
            <Breadcrumb>
              <BreadcrumbItem href="#">
                <Avatar size="xs" color="blue" initials="J" />
                JoyUI
              </BreadcrumbItem>
              <BreadcrumbItem href="#">
                <Avatar size="xs" color="neutral" initials="运" />
                运营空间
              </BreadcrumbItem>
              <BreadcrumbItem current icon={RiDashboardLine}>
                概览
              </BreadcrumbItem>
            </Breadcrumb>

            <div className="flex w-full flex-wrap items-end justify-between gap-2">
              <div className="flex min-w-0 items-center gap-1.5">
                <h1 className="px-1 text-title-2-medium whitespace-nowrap text-text-primary">
                  运营概览
                </h1>
              </div>
              <div className="flex flex-wrap items-center justify-end gap-2.5">
                {headerActions ?? (
                  <>
                    <NotificationBell />
                    <Button
                      variant="secondary"
                      size="medium"
                      leadingIcon={RiFilter3Fill}
                    >
                      筛选
                    </Button>
                    <Button
                      variant="primary"
                      size="medium"
                      leadingIcon={RiAddFill}
                    >
                      新建订单
                    </Button>
                  </>
                )}
              </div>
            </div>
          </header>

          <div className="flex w-full flex-col gap-4 pb-4">
            <StatCards variant="footer" />
            <div className="grid gap-4 xl:grid-cols-2">
              <RevenueChartCard />
              <OrdersChartCard />
            </div>
            <section className="overflow-hidden rounded-2xl border border-separator-border bg-background-secondary-default">
              <div className="border-b border-separator-border px-4 py-3">
                <h2 className="text-title-3-medium text-text-primary">最近订单</h2>
                <p className="mt-0.5 text-body-2-regular text-text-secondary">
                  支持搜索、筛选、排序与分页的客户订单表。
                </p>
              </div>
              <div className="p-3 sm:p-4">
                <DataTableExample pageSize={5} showSizeToggle={false} />
              </div>
            </section>
          </div>
        </div>
      </main>
    </div>
  );
}

"use client";

import { useEffect, useRef, useState } from "react";
import type { CSSProperties, ReactNode } from "react";
import { motion, useReducedMotion } from "motion/react";
import { AgentThinking } from "../agent-thinking/agent-thinking";
import { cx } from "@/lib/utils";

/**
 * Agent Log — the shared machinery behind a streaming agent transcript.
 *
 * Task List and Web Search are both "a line of work drawing itself down the
 * page": rows arrive one at a time, each blurring in while a curved guide
 * strokes itself alongside them. All of that lives here so the two cannot
 * drift apart, and so tuning the motion means tuning it once.
 *
 * What is here: the reveal ticker that paces units, the blur-in transition and
 * its soft clipping edge, the shimmer for a line still in progress, and the
 * tree guide with its draw animation. What is not here: anything about what a
 * row *says*. That is each component's own business.
 */

/* --------------------------------------------------------------- motion */

export const SOFT_EASE = [0.22, 1, 0.36, 1] as const;

/**
 * Each unit blurs in as it lands: 6px of blur and a 4px lift resolving over
 * 0.42s, the same language the AI Chat thread uses for a streaming line. The
 * height runs a touch shorter on the soft curve so the row has finished making
 * space slightly before the text finishes sharpening — the container settles
 * first, then the words arrive, which is what reads as smooth rather than as a
 * jump.
 *
 * Growing a row from height 0 means `overflow-hidden` cuts a hard line through
 * the text while it emerges. `--bui-reveal-fade` softens that edge: the row is
 * masked with a gradient whose solid portion ends that many pixels short of the
 * bottom, and the reveal animates it to 0, at which point the mask is a no-op
 * and nothing pops. The fade is longer than a text line, so a row is always
 * faintest exactly where it is being clipped.
 */
const REVEAL_FADE_VAR = "--bui-reveal-fade";

// The transparent stop sits just past the box: with both stops at exactly 100%
// the gradient is degenerate and browsers soften the final pixel row, which
// shows up as breaks in the guide where one row meets the next.
const REVEAL_GRADIENT = `linear-gradient(to bottom, #000 calc(100% - var(${REVEAL_FADE_VAR}, 0px)), transparent calc(100% + 1px))`;

const REVEAL_MASK: CSSProperties = {
  WebkitMaskImage: REVEAL_GRADIENT,
  maskImage: REVEAL_GRADIENT,
};

export const UNIT_INITIAL = {
  opacity: 0,
  height: 0,
  y: 4,
  filter: "blur(6px)",
  [REVEAL_FADE_VAR]: "22px",
};

export const UNIT_ANIMATE = {
  opacity: 1,
  height: "auto",
  y: 0,
  filter: "blur(0px)",
  [REVEAL_FADE_VAR]: "0px",
};

export const UNIT_TRANSITION = {
  height: { duration: 0.38, ease: SOFT_EASE },
  opacity: { duration: 0.42, ease: SOFT_EASE },
  filter: { duration: 0.42, ease: SOFT_EASE },
  y: { duration: 0.42, ease: SOFT_EASE },
  [REVEAL_FADE_VAR]: { duration: 0.44, ease: SOFT_EASE },
};

/**
 * The soft edge only earns its keep while a unit is growing. Once the reveal
 * finishes, drop the mask entirely: no compositing layer at rest, and the guide
 * meets pixel-exactly at every row boundary.
 */
export function useRevealMask(reduce: boolean) {
  const [revealing, setRevealing] = useState(!reduce);
  return {
    style: revealing ? REVEAL_MASK : undefined,
    onAnimationComplete: () => setRevealing(false),
  };
}

/** A line the agent is still working on, with a highlight travelling across it. */
export function ShimmerText({ children }: { children: string }) {
  return (
    <span aria-label={children} className="agent-progress-loading-text">
      {children}
    </span>
  );
}

/* ---------------------------------------------------------------- ticker */

export interface RevealTickerOptions {
  /** How many units the log has in total. */
  total: number;
  /** Pauses and resumes. Toggling back resumes; change `key` to replay. */
  run?: boolean;
  stepInterval?: number;
  startDelay?: number;
  /** Drive it yourself from real events; disables the internal timer. */
  revealed?: number;
  /**
   * Per-unit pacing: given the index about to be revealed, how long to wait
   * first. Overrides `startDelay` and `stepInterval` when supplied, so a log
   * can dwell on the units that would genuinely have taken longer instead of
   * marching at a fixed tempo.
   */
  delayFor?: (index: number) => number;
  onComplete?: () => void;
}

/**
 * Paces the log, one unit per tick, and fires `onComplete` once the last one
 * lands. Timing is one interval rather than a per-unit duration: real agent
 * steps do not take equal time, and pretending otherwise is what makes a
 * progress UI feel fake — so pass `revealed` and drive it from real events as
 * soon as you have them.
 */
export function useRevealTicker({
  total,
  run = true,
  stepInterval = 850,
  startDelay = 320,
  revealed: controlled,
  delayFor,
  onComplete,
}: RevealTickerOptions): number {
  const isControlled = controlled !== undefined;
  const [ticked, setTicked] = useState(0);
  const revealed = isControlled ? Math.max(0, Math.min(controlled, total)) : ticked;

  useEffect(() => {
    if (isControlled || !run || revealed >= total) return;
    const delay = delayFor
      ? delayFor(revealed)
      : revealed === 0
        ? startDelay
        : stepInterval;
    const id = window.setTimeout(() => setTicked((n) => n + 1), delay);
    return () => window.clearTimeout(id);
  }, [isControlled, run, revealed, total, startDelay, stepInterval, delayFor]);

  // Guarded by a ref rather than an effect dependency, so an inline
  // `onComplete` closure re-running the effect cannot fire it twice.
  const firedRef = useRef(false);

  useEffect(() => {
    if (total === 0 || revealed < total) {
      firedRef.current = false;
      return;
    }
    if (firedRef.current) return;
    firedRef.current = true;
    onComplete?.();
  }, [revealed, total, onComplete]);

  return revealed;
}

/* ----------------------------------------------------------- tree guide */

/* Branch geometry. The elbow sits a fixed distance from the row's top rather
 * than at 50%, so a row whose label wraps still branches at its first line
 * instead of drifting to the middle of the block. 14px is half of the 20px line
 * plus the row's 4px top padding. */
const BRANCH_Y = 14;
const BRANCH_RADIUS = 6;
const BRANCH_WIDTH = 12;

/** Down the trunk, round the corner, out to the label. */
const BRANCH_PATH = `M0.5 0 V${BRANCH_Y - BRANCH_RADIUS} Q0.5 ${BRANCH_Y} ${0.5 + BRANCH_RADIUS} ${BRANCH_Y} H11.5`;

/**
 * The guide draws as one pen, which means the pieces run in sequence rather
 * than together.
 *
 * When a row arrives, the line still has to cover the row above it: that row
 * was the last one a moment ago, so its trunk stopped at its own corner. Its
 * tail draws first, down through the space the new row just opened; only then
 * does the new row's branch start, picking the stroke up exactly where the tail
 * left it. Run both at once — which is what happens if they share a delay — and
 * you get two disconnected fragments per row, which reads as a column of
 * separate cells instead of a single line.
 *
 * Timings are lengths divided by one pen speed, ~160px/s, so the stroke never
 * changes pace as it hands off. `linear` matters here: an eased draw would slow
 * at every junction and give the handoff away.
 *
 * The chain is sized against how fast the label *reads*, not against its
 * nominal duration. The blur-in runs 0.42s but on a steeply front-loaded curve,
 * so the words have settled by roughly 0.2s; sizing the guide to the full 0.42s
 * left it visibly trailing text that was already done. The 42px of line
 * therefore draws in 0.26s, starting on the same frame as the row.
 */
const TAIL_TRANSITION = { duration: 0.12, ease: "linear" as const, delay: 0 };

/** A branch waits for the tail above it; the first in a list has none to wait
 *  for and starts with the row. */
const branchTransition = (first: boolean) => ({
  duration: 0.14,
  ease: "linear" as const,
  delay: first ? 0 : 0.12,
});

/**
 * Curved tree guide, matching the docs sidebar and the AI Chat repository
 * submenus, drawn per row rather than as one measured SVG for the whole list.
 * These rows have variable height and animate their height as they arrive; a
 * row that owns its own elbow stays correct through all of that with no
 * measurement.
 *
 * Two pieces, because a single stroke cannot fork. The branch is an SVG path
 * animating `pathLength`, which is the part you watch being drawn. The trunk
 * below it is a 1px bar scaling from its top edge, which extends downward on
 * the same curve and meets the next row's branch. The last row omits it, so the
 * guide finishes on the corner instead of hanging past it.
 */
export function RowConnector({
  first,
  last,
  reduce,
}: {
  first: boolean;
  last: boolean;
  reduce: boolean;
}) {
  return (
    <span
      aria-hidden
      className="pointer-events-none absolute inset-y-0 start-0 w-3 text-foreground-icon-quaternary"
    >
      <svg
        width={BRANCH_WIDTH}
        height={BRANCH_Y + 1}
        viewBox={`0 0 ${BRANCH_WIDTH} ${BRANCH_Y + 1}`}
        fill="none"
        className="absolute top-0 start-0 rtl:-scale-x-100"
      >
        <motion.path
          d={BRANCH_PATH}
          stroke="currentColor"
          strokeWidth="1"
          initial={reduce ? false : { pathLength: 0 }}
          animate={{ pathLength: 1 }}
          transition={branchTransition(first)}
        />
      </svg>
      {!last && (
        <motion.span
          className="absolute start-0 w-px origin-top bg-current"
          style={{ top: BRANCH_Y - BRANCH_RADIUS, bottom: 0 }}
          initial={reduce ? false : { scaleY: 0 }}
          animate={{ scaleY: 1 }}
          transition={TAIL_TRANSITION}
        />
      )}
    </span>
  );
}

/**
 * Drops from a parent row's glyph into a nested list's trunk.
 *
 * A second level of the tree indents to `ml-2`, which puts its trunk under the
 * centre of the parent's 16px glyph — correct horizontally, but the trunk still
 * begins at the top of the nested row, which is below the parent's line. Left
 * alone it starts in mid-air. This fills that gap.
 *
 * It draws on the tail's timing, and the nested list's first branch is passed
 * `first={false}` so it waits for exactly this, the same handoff every other
 * junction in the guide uses. Render it inside a `relative` wrapper sitting
 * directly above the nested list, and give it the same `offset` as that list's
 * left margin so the two are one line.
 */
export function GuideBridge({
  height,
  offset = 8,
  reduce,
}: {
  height: number;
  /** Distance from the wrapper's left edge to the nested trunk. */
  offset?: number;
  reduce: boolean;
}) {
  return (
    <motion.span
      aria-hidden
      className="pointer-events-none absolute w-px origin-top bg-current text-foreground-icon-quaternary"
      style={{ top: -height, height, insetInlineStart: offset }}
      initial={reduce ? false : { scaleY: 0 }}
      animate={{ scaleY: 1 }}
      transition={TAIL_TRANSITION}
    />
  );
}

/**
 * The tail indicator, while the log is still running.
 *
 * Deliberately off the guide: no branch, no trunk. The tree records what the
 * agent *did*, and this is the one line that has not happened yet — hanging it
 * off the same line would file it alongside the findings. Sitting loose at the
 * bottom, on the rows' own left edge, it reads as the log still going rather
 * than as another result.
 */
export function WorkingRow({
  label,
  reduce,
  className,
}: {
  label: string;
  reduce: boolean;
  className?: string;
}) {
  const mask = useRevealMask(reduce);
  return (
    <motion.div
      initial={reduce ? false : UNIT_INITIAL}
      animate={UNIT_ANIMATE}
      transition={UNIT_TRANSITION}
      {...mask}
      className={cx("overflow-hidden", className)}
    >
      <div className="py-1">
        <AgentThinking variant="stars" label={label} />
      </div>
    </motion.div>
  );
}

/** Reads `prefers-reduced-motion` once for a whole log. */
export function useLogMotion() {
  return useReducedMotion() ?? false;
}

/**
 * One row of a log: the blur-in, the clipping edge that keeps it from being cut
 * as it grows, and the length of guide that belongs to it.
 */
export function LogRow({
  first,
  last,
  reduce,
  className,
  children,
}: {
  first: boolean;
  last: boolean;
  reduce: boolean;
  className?: string;
  children: ReactNode;
}) {
  const mask = useRevealMask(reduce);
  return (
    <motion.li
      initial={reduce ? false : UNIT_INITIAL}
      animate={UNIT_ANIMATE}
      transition={UNIT_TRANSITION}
      {...mask}
      className={cx("relative overflow-hidden ps-4", className)}
    >
      <RowConnector first={first} last={last} reduce={reduce} />
      {children}
    </motion.li>
  );
}

"use client";

import { useTemplateCopy } from "../../foundations/template-copy/template-copy";

import { useEffect, useState } from "react";
import type { CSSProperties } from "react";
import { cx } from "@/lib/utils";

/**
 * Agent Thinking — the agent "thinking" state that sits above a chat composer
 * while a response is being worked on.
 *
 * Four curated variants:
 * - `wave`     dot grid with a diagonal wavefront gliding top-left → bottom-right
 * - `spin`     dot grid with a bright head orbiting the grid clockwise
 * - `stars`    sparkles twinkling in and out with a stagger
 * - `infinity` a comet trail sweeping a figure-eight
 *
 * Every variant pairs the indicator with a shimmering label and an elapsed
 * timer that starts when the loader mounts. Shimmer and CSS animations fall
 * back to static rendering under `prefers-reduced-motion` (see globals.css).
 */

export type AgentThinkingVariant = "wave" | "spin" | "stars" | "infinity";
export type AgentThinkingTone = "subtle" | "default" | "primary" | "accent";

export interface AgentThinkingProps {
  variant?: AgentThinkingVariant;
  /** Status label, e.g. "Thinking" or "Searching the docs". */
  label?: string;
