    description: "Enter the code we sent to finish signing in.",
    cta: "Verify and continue",
    switchLead: "Code not arriving?",
    switchAction: "Send a new one",
  },
} as const;

export function AuthCard({
  mode = "signin",
  email,
  codeLength = 6,
  onComplete,
  onResend,
  layout = "stacked",
  providers = ["google", "apple", "github"],
  title,
  description,
  media,
  logo,
  centered = false,
  confirmPassword = false,
  footnote,
  onSubmit,
  onProvider,
  switchHref = "#",
  headingLevel = 1,
  children,
  className,
}: AuthCardProps) {
  const localize = useTemplateCopy();
  const TitleHeading = `h${headingLevel}` as const;
  const [remember, setRemember] = useState(true);
  const [code, setCode] = useState("");
  const copy = COPY[mode];
  const signup = mode === "signup";
  const verify = mode === "verify";

  const submit = (event: FormEvent<HTMLFormElement>) => {
    event.preventDefault();
    onSubmit?.(new FormData(event.currentTarget));
  };

  const social = (
    <div
      className={cx(
        layout === "stacked" && "flex flex-col gap-2.5",
        // Wraps rather than scrolls: six providers on a narrow card should
        // fall to a second row, not clip.
        layout === "inline" && "flex flex-wrap justify-center gap-2",
        // Equal columns that share the full width, so three providers read as
        // one row of controls rather than three loose squares.
        layout === "grid" && "grid grid-flow-col auto-cols-fr gap-2.5",
      )}
    >
      {providers.map((provider) => (
        <SocialButton
          key={provider}
          brand={provider}
          appearance="white"
          iconOnly={layout !== "stacked"}
          fullWidth={layout === "stacked"}
          // `iconOnly` fixes a square width; the grid needs it to stretch,
          // and `className` is last into `cx` so it wins.
          className={layout === "grid" ? "w-full" : undefined}
          aria-label={layout !== "stacked" ? `Continue with ${SOCIAL_PROVIDERS[provider].label}` : undefined}
          onClick={() => onProvider?.(provider)}
        >
          {`Continue with ${SOCIAL_PROVIDERS[provider].label}`}
        </SocialButton>
      ))}
    </div>
  );

  // The code step centres itself and carries a mark by default: it is a
  // single-purpose screen, and the icon is what says at a glance which one.
  // Left-aligned like the other two modes: a centred column with a hairline
  // was the reference's shape, and this one should read as the same family
  // as the sign-in card it follows, not as a different screen.
  const centerContent = centered;
  const mark =
    logo ??
    (verify ? (
      <RiMailCheckLine className="size-8 text-foreground-icon-primary" aria-hidden />
    ) : null);

  const body = (
    <>
      {mark ? (
        <div className={cx("mb-5 flex", centerContent ? "justify-center" : "justify-start")}>
          {mark}
        </div>
      ) : null}

      {(title != null || description != null || !children) && (
        <div className={cx("flex flex-col gap-1.5", centerContent && "text-center")}>
          {(title != null || !children) && (
            <TitleHeading className="text-title-2-medium text-text-primary">
              {title ?? copy.title}
            </TitleHeading>
          )}
          {(description != null || !children) && (
            <p className="text-body-regular text-text-secondary">
              {description ??
                (verify && email ? (
                  <>
                    Enter the code we sent to{" "}
                    <span className="text-body-medium text-text-primary">{email}</span>{" "}
                    to finish signing in.
                  </>
                ) : (
                  copy.description
                ))}
            </p>
          )}
        </div>
      )}

      {children ? (
        <div className="mt-6 flex flex-col gap-4">{children}</div>
      ) : (
        <>
          <form onSubmit={submit} className="mt-6 flex flex-col gap-4">
            {verify ? (
              <div className="flex flex-col gap-1.5">
                <span className="text-body-medium text-text-secondary">
                  Verification code
                </span>
                <InputOtp
                  value={code}
                  onChange={setCode}
                  onComplete={onComplete}
                  length={codeLength}
                  groupEvery={codeLength % 2 === 0 ? codeLength / 2 : undefined}
                  aria-label="Verification code"
                  className="justify-start"
                />
              </div>
            ) : null}

            {signup && !confirmPassword ? (
              <Input name="name" label="Full name" placeholder="Ada Lovelace" isRequired />
            ) : null}

            {verify ? null : (
            <Input
              name="email"
              type="email"
              label="Email"
              placeholder="you@company.com"
              autoComplete="email"
              hint={signup ? "We use this to contact you, and never share it." : undefined}
              isRequired
            />
            )}

            {verify ? null : signup && confirmPassword ? (
              // Stacked, full width: a password field pair is easier to fill at
              // full width than in two half-width columns, and it keeps the whole
              // form on one rhythm.
              <>
                <Input
                  name="password"
                  type="password"
                  label="Password"
                  placeholder="At least 8 characters"
                  autoComplete="new-password"
                  isRequired
                />
                <Input
                  name="confirmPassword"
                  type="password"
                  label="Confirm password"
                  placeholder="Repeat your password"
                  autoComplete="new-password"
                  isRequired
                />
              </>
            ) : (
              <Input
                name="password"
                type="password"
                label="Password"
                placeholder={signup ? "At least 8 characters" : "Enter your password"}
                autoComplete={signup ? "new-password" : "current-password"}
                isRequired
              />
            )}

            {signup || verify ? null : (
              <div className="flex items-center justify-between">
                <Checkbox size="sm" isSelected={remember} onChange={setRemember}>
                  Remember me
                </Checkbox>
                <LinkButton href="#">Forgot password?</LinkButton>
              </div>
            )}

            <Button type="submit" className="w-full">
              {copy.cta}
            </Button>

            {/* The split layout carries its terms line under the card instead,
                through `footnote`, so it does not crowd the CTA. */}
            {signup && !footnote ? (
              <p className="text-caption-1-regular text-text-tertiary">
                By creating an account you agree to our Terms of Service and Privacy Policy.
              </p>
            ) : null}
          </form>

          {/* Providers always follow the form, in every layout: the email fields
              are the path this card is built around, and a bank of provider
              buttons above them buries the thing people came to fill in. The
              code step shows none — the visitor has already picked a method. */}
          {!verify && providers.length > 0 ? (
            <>
              <div className="my-5">
                <Divider>or continue with</Divider>
              </div>
              {social}
            </>
          ) : null}

          {/* Resend is an action, not a destination, so on the code step the
              footer is a button. `LinkButton` renders one when given no href. */}
          {verify ? (
            <p className="mt-6 text-center text-body-regular text-text-secondary">
              {copy.switchLead}{" "}
              <LinkButton onClick={onResend}>{copy.switchAction}</LinkButton>
            </p>
          ) : (
            <p className="mt-6 text-center text-body-regular text-text-secondary">
              {copy.switchLead} <LinkButton href={switchHref}>{copy.switchAction}</LinkButton>
            </p>
          )}
        </>
      )}
    </>
  );

  const card = media ? (
    <div
      className={cx(
        "grid w-full max-w-[880px] overflow-hidden rounded-3xl border border-border-button-default bg-background-primary-default shadow-xs md:grid-cols-2 dark:bg-background-secondary-default",
        className,
      )}
    >
      <div className="flex flex-col p-6 sm:p-8">{body}</div>
      {/* Hidden rather than stacked below `md`: a tall image above the fields
          pushes the form off a phone screen for no gain. */}
      <div className="relative hidden bg-background-secondary-default md:block">{media}</div>
    </div>
  ) : (
    <div
      className={cx(
        "flex w-full max-w-[400px] flex-col rounded-3xl border border-border-button-default bg-background-primary-default p-6 shadow-xs sm:p-8 dark:bg-background-secondary-default",
        className,
      )}
    >
      {body}
    </div>
  );

  if (!footnote) return localize(card);

  return localize(
    <div className="flex w-full flex-col items-center gap-4">
      {card}
      <p className="max-w-[520px] text-center text-caption-1-regular text-text-tertiary">
        {footnote}
      </p>
    </div>
  );
}

"use client";

import { useEffect, useState } from "react";
import { useDirection } from "../../foundations/direction/direction";
import { cx } from "@/lib/utils";

/**
 * Auto-advancing artwork for the auth card's `media` slot.
 *
 * The transition is a four-beat cycle rather than a plain slide. The image
 * fills the panel edge to edge; when its turn is up it shrinks and rounds off
 * into a card, holds there long enough to read as a deliberate pause, and only
 * then travels left. The next image rides in beside it already card-sized, and
 * grows back out to fill the panel once it has landed. Shrinking first is what
 * makes the movement legible: a full-bleed image sliding under a hard edge
 * reads as a cut, while a card that detaches, moves, and settles reads as one
 * object being replaced by another.
 *
 * The travel happens in depth, not flat across the panel. The panel holds a
 * perspective, and the cards leave and arrive pushed back along Z and turned
 * on their vertical axis, so the outgoing one banks away to the left while the
 * next swings in from the right and squares up as it lands. Both are angled
 * away from the middle, as though they sit on a drum turning past the viewer,
 * which is what gives the movement a front and a back instead of a left and a
 * right.
 *
 * Every slide is placed by where it sits relative to the current one, so the
 * set travels in one direction forever and the wrap back to the first image is
 * just another step left. The cost of that arrangement is that the slide
 * leaving the frame has to jump from the left side to the back of the queue on
 * the right, so transitions are enabled only for the slides actually moving in
 * a given beat; everything else is repositioned with them switched off.
 *
 * Plain `<img>` rather than `next/image`: this file installs into other
 * people's projects, and it should not decide their image pipeline for them.
 * The first slide is eager and the rest lazy, so the card paints immediately
 * without pulling four files at once.
 *
 * It advances on its own and offers no controls. The artwork beside a sign-in
 * form is atmosphere, not content — a visitor is there to get in, and giving
 * them arrows to click is inviting them away from the thing they came to do.
 * Honouring `prefers-reduced-motion` means holding on the first slide.
 */

const REDUCED_MOTION_QUERY = "(prefers-reduced-motion: reduce)";

/** Card state: shrunk to a rounded tile, and the size it rides in at. */
const CARD_SCALE = 0.82;
const ENTER_SCALE = 0.8;
const CARD_RADIUS = 24;

/** How deep the drum is, and how far the cards turn on it. */
const PERSPECTIVE = 850;
const DEPTH = 220;
const TILT = 48;

const SHRINK_MS = 450;
/** The deliberate pause once it has become a card, before it moves. */
const HOLD_MS = 200;
const SLIDE_MS = 700;
const GROW_MS = 500;

/**
 * `idle`   at rest, full bleed
 * `shrink` pulling back into a card, then holding
 * `slide`  travelling left while the next one rides in
 * `enter`  the frame where the new slide takes over, before it grows
 */
type Phase = "idle" | "shrink" | "slide" | "enter";

const NEXT_PHASE: Record<Phase, Phase> = {
  idle: "shrink",
  shrink: "slide",
  slide: "enter",
  enter: "idle",
};

export interface AuthMediaSlide {
  src: string;
  /** Decorative by default: the artwork carries no information the form needs. */
  alt?: string;
}

export function AuthMediaCarousel({
  slides,
  interval = 3200,
  className,
}: {
  slides: AuthMediaSlide[];
  /** Milliseconds a slide rests at full bleed, before the transition begins. */
  interval?: number;
  className?: string;
}) {
  const [index, setIndex] = useState(0);
  const [phase, setPhase] = useState<Phase>("idle");
  const inlineSign = useDirection() === "rtl" ? -1 : 1;
  const count = slides.length;

  useEffect(() => {
    if (count < 2) return;
    if (window.matchMedia(REDUCED_MOTION_QUERY).matches) return;

    // `enter` is only a re-labelling: the outgoing slide is dropped and the
    // incoming one takes position 0 at the size it was already drawn at, so it
    // needs a frame to paint before the grow can transition from it.
    const delay = {
      idle: interval,
      shrink: SHRINK_MS + HOLD_MS,
      slide: SLIDE_MS,
      enter: 20,
    }[phase];

    const timer = window.setTimeout(() => {
      if (phase === "slide") setIndex((current) => (current + 1) % count);
      setPhase(NEXT_PHASE[phase]);
    }, delay);

    return () => window.clearTimeout(timer);
  }, [phase, count, interval]);

  return (
    <div
      style={{ perspective: `${PERSPECTIVE}px` }}
      className={cx("absolute inset-0 overflow-hidden", className)}
    >
      {slides.map((slide, slideIndex) => {
        // 0 is the slide in play, 1 is next in the queue, and everything else
        // waits off to the right until its turn comes round.
        const position = (slideIndex - index + count) % count;
        const current = position === 0;
        const upNext = position === 1;

        // Where this slide sits on the drum. `arrived` is square to the
        // viewer but still card-sized: growing is the beat after.
        const transform = current
          ? phase === "slide"
            ? `translateX(${-100 * inlineSign}%) translateZ(${-DEPTH}px) rotateY(${-TILT * inlineSign}deg) scale(${CARD_SCALE})`
            : phase === "shrink"
              ? `scale(${CARD_SCALE})`
              : phase === "enter"
                ? `scale(${ENTER_SCALE})`
                : "scale(1)"
          : upNext && phase === "slide"
            ? `scale(${ENTER_SCALE})`
            : `translateX(${100 * inlineSign}%) translateZ(${-DEPTH}px) rotateY(${TILT * inlineSign}deg) scale(${ENTER_SCALE})`;

        // Only the slides in motion this beat may transition. The rest are
        // being repositioned, and a transition would streak them across.
        const moving = current || (upNext && phase === "slide");

        return (
          // Deliberate: this file installs into other projects and should not
          // require next/image. Swap it for your own loader if you have one.
          // eslint-disable-next-line @next/next/no-img-element
          <img
            key={slide.src}
            src={slide.src}
            alt={slide.alt ?? ""}
            aria-hidden={slide.alt ? undefined : true}
            loading={slideIndex === 0 ? "eager" : "lazy"}
            style={{
              transform,
              borderRadius: current && phase === "idle" ? 0 : CARD_RADIUS,
              transitionDuration:
                phase === "slide" ? `${SLIDE_MS}ms` : phase === "shrink" ? `${SHRINK_MS}ms` : `${GROW_MS}ms`,
            }}
            className={cx(
              "absolute inset-0 size-full object-cover",
              moving && phase !== "enter"
                ? "transition-[transform,border-radius] ease-in-out"
                : "transition-none",
            )}
          />
        );
      })}

      {slides.length > 1 ? (
        <div className="absolute inset-x-0 bottom-4 flex justify-center gap-1.5">
          {slides.map((slide, slideIndex) => (
            <span
              key={slide.src}
              aria-hidden
              className={cx(
                "h-1.5 rounded-full bg-white transition-all duration-500 ease-out",
                slideIndex === index ? "w-5 opacity-90" : "w-1.5 opacity-45",
              )}
            />
          ))}
        </div>
      ) : null}
    </div>
  );
}

