/**
 * Figma source: Board UI → Avatar (styles Avatar/1…Avatar/26; used throughout
 * dashboard 1, node 3731:2932).
 *
 * Sizes used in the designs (px):
 *   xs = 20   breadcrumb workspace marks     (initials 10/15 semibold)
 *   sm = 24   table rows                     (initials 12/16 semibold)
 *   md = 32   sidebar workspace / team card  (initials 16/22 semibold)
 *   lg = 36   people cards                   (initials 18/24 semibold)
 *
 * Renders a photo when `src` is given, otherwise centered initials on a
 * tinted disc. Initial tints from Figma:
 *   neutral → bg avatar/neutral/background, text text/secondary
 *   blue    → bg color/blue/300,    text color/blue/900
 *   lime    → bg color/lime/200,    text color/lime/700
 *   pink    → bg color/pink/200,    text color/pink/500
 */

type AvatarSize = "xs" | "sm" | "md" | "lg";
type AvatarColor = "neutral" | "blue" | "lime" | "pink";

export interface AvatarProps extends HTMLAttributes<HTMLSpanElement> {
  size?: AvatarSize;
  color?: AvatarColor;
  /** Photo URL. Wins over `initials`. */
  src?: string;
  alt?: string;
  /** Fallback initials, e.g. "M". */
  initials?: string;
  ref?: Ref<HTMLSpanElement>;
}

const styles = sortCx({
  base: "inline-flex shrink-0 select-none items-center justify-center overflow-hidden rounded-full text-center align-middle transition-[width,height,font-size] duration-200 ease",
  size: {
    xs: "size-5 text-[10px] leading-[15px] font-semibold",
    sm: "size-6 text-caption-1-semibold tracking-normal",
    md: "size-8 text-headline-semibold",
    lg: "size-9 text-[18px] leading-6 font-semibold",
  },
  color: {
    neutral: "bg-avatar-neutral-background text-text-secondary",
    blue: "bg-blue-300 text-blue-900",
    lime: "bg-lime-200 text-lime-700",
    pink: "bg-pink-200 text-pink-500",
  },
});

export function Avatar({
  size = "md",
  color = "neutral",
  src,
  alt,
  initials,
  className,
  ref,
  ...props
}: AvatarProps) {
  return (
    <span
      ref={ref}
      className={cx(styles.base, styles.size[size], styles.color[color], className)}
      {...props}
    >
      {src ? (
        <img
          src={src}
          alt={alt ?? ""}
          loading="lazy"
          decoding="async"
          className="size-full object-cover"
        />
      ) : (
        initials
      )}
    </span>
  );
}

import type { HTMLAttributes, ReactElement, ReactNode, Ref } from "react";
import { Children, cloneElement, isValidElement } from "react";
import type { AvatarProps } from "../avatar/avatar";
import { cx, sortCx } from "@/lib/utils";

/**
 * Stacked avatars for teammates / assignees — ringed like notification
 * badges on JoyUI sidebar surfaces.
 *
 *   <AvatarGroup max={3}>
 *     <Avatar initials="A" />
 *     <Avatar initials="B" />
 *     <Avatar initials="C" />
 *     <Avatar initials="D" />
 *   </AvatarGroup>
 */

export type AvatarGroupSize = NonNullable<AvatarProps["size"]>;

export interface AvatarGroupProps extends HTMLAttributes<HTMLDivElement> {
  children?: ReactNode;
  /** How many faces to show before +N. Default 3. */
  max?: number;
  size?: AvatarGroupSize;
  ref?: Ref<HTMLDivElement>;
}

const ring = sortCx({
  base: "relative inline-flex items-center",
  size: {
    xs: "-space-x-1.5",
    sm: "-space-x-2",
    md: "-space-x-2.5",
    lg: "-space-x-3",
  },
});

const face = sortCx({
  base: "relative ring-2 ring-background-primary-default",
});

const overflow = sortCx({
  // Soft chip on tertiary — matches Chip `soft` / avatar neutral fallback.
  base: "relative z-10 inline-flex shrink-0 items-center justify-center rounded-full bg-background-tertiary-default text-text-secondary ring-2 ring-background-primary-default",
  size: {
    xs: "size-5 text-[9px] font-semibold leading-none",
    sm: "size-6 text-caption-1-semibold",
    md: "size-8 text-caption-1-semibold",
    lg: "size-9 text-headline-semibold",
  },
});

export function AvatarGroup({
  children,
  max = 3,
  size = "md",
  className,
  ref,
  ...props
}: AvatarGroupProps) {
  const items = Children.toArray(children).filter(isValidElement) as ReactElement<AvatarProps>[];
  const visible = items.slice(0, Math.max(0, max));
  const rest = Math.max(0, items.length - visible.length);

  return (
    <div
      ref={ref}
      role="group"
      className={cx(ring.base, ring.size[size], className)}
      {...props}
    >
      {visible.map((child, i) =>
        cloneElement(child, {
          size: child.props.size ?? size,
          className: cx(face.base, child.props.className),
          style: { zIndex: visible.length - i, ...child.props.style },
        }),
      )}
      {rest > 0 ? (
        <span className={cx(overflow.base, overflow.size[size])} style={{ zIndex: 0 }}>
          +{rest}
        </span>
      ) : null}
    </div>
  );
}

