/**
 * 1D barcode rendered to SVG via `jsbarcode` (JoyUI dependency).
 * Defaults to CODE128 — good for tickets, SKUs, and tracking numbers.
 */

export type BarcodeFormat =
  | "CODE128"
  | "CODE128A"
  | "CODE128B"
  | "CODE128C"
  | "EAN13"
  | "EAN8"
  | "EAN5"
  | "EAN2"
  | "UPC"
  | "CODE39"
  | "ITF14"
  | "MSI"
  | "pharmacode"
  | "codabar";

export interface BarcodeProps extends Omit<HTMLAttributes<HTMLDivElement>, "children"> {
  value: string;
  format?: BarcodeFormat;
  /** Bar height in px. */
  height?: number;
  /** Module width in px. */
  width?: number;
  displayValue?: boolean;
  /** Bar colour. */
  lineColor?: string;
  background?: string;
  fontSize?: number;
  /** Accessible name. */
  "aria-label"?: string;
  ref?: Ref<HTMLDivElement>;
}

export function Barcode({
  value,
  format = "CODE128",
  height = 64,
  width = 2,
  displayValue = true,
  lineColor = "currentColor",
  background = "transparent",
  fontSize = 14,
  "aria-label": ariaLabel,
  className,
  ref,
  ...props
}: BarcodeProps) {
  const svgRef = useRef<SVGSVGElement>(null);
  const reactId = useId();
  const label = ariaLabel ?? (value ? `Barcode ${value}` : "Empty barcode");

  useEffect(() => {
    const svg = svgRef.current;
    if (!svg) return;
    // Clear previous drawing when value/format changes.
    while (svg.firstChild) svg.removeChild(svg.firstChild);
    if (!value) return;
    try {
      JsBarcode(svg, value, {
        format,
        height,
        width,
        displayValue,
        lineColor,
        background,
        fontSize,
        margin: 8,
        xmlDocument: document,
      });
    } catch {
      // Invalid value for the chosen format — leave SVG empty.
    }
  }, [background, displayValue, fontSize, format, height, lineColor, value, width]);

  return (
    <div
      ref={ref}
      role="img"
      aria-label={label}
      className={cx(
        "inline-flex max-w-full overflow-x-auto rounded-xl border border-border-secondary-default",
        "bg-background-primary-default p-3 text-text-primary",
        className,
      )}
      {...props}
    >
      <svg ref={svgRef} id={reactId} aria-hidden className="max-w-full" />
    </div>
  );
}

"use client";

import type { CSSProperties, HTMLAttributes, ReactNode, Ref } from "react";
import { cx } from "@/lib/utils";

/**
 * Soft light that rides the border of a card — landing / AI showcase energy
 * without leaving JoyUI tokens. Wrap any surface; the beam is decorative
 * (`aria-hidden`) and respects reduced motion.
 *
 *   <BorderBeam className="rounded-2xl">
 *     <Card className="relative z-10">…</Card>
 *   </BorderBeam>
 */

export interface BorderBeamProps extends HTMLAttributes<HTMLDivElement> {
  children?: ReactNode;
  /** Border thickness in px. */
  borderWidth?: number;
  /** Full lap duration in seconds. */
  duration?: number;
  /** Delay before the first lap (seconds). */
  delay?: number;
  /** Beam colour; defaults to accent. */
  color?: string;
  /** Soft trailing colour; defaults to a lighter accent mix. */
  colorFrom?: string;
  ref?: Ref<HTMLDivElement>;
}

export function BorderBeam({
  children,
  className,
  borderWidth = 1.5,
  duration = 8,
  delay = 0,
  color,
  colorFrom,
  style,
  ref,
  ...props
}: BorderBeamProps) {
  const vars = {
    "--bui-border-beam-width": `${borderWidth}px`,
    "--bui-border-beam-duration": `${duration}s`,
    "--bui-border-beam-delay": `${delay}s`,
    "--bui-border-beam-color": color ?? "var(--color-accent-500)",
    "--bui-border-beam-from": colorFrom ?? "var(--color-accent-300)",
    ...style,
  } as CSSProperties;

  return (
    <div
      ref={ref}
      className={cx(
        // Default to Card radius when the wrapper isn't given one.
        "bui-border-beam relative isolate overflow-hidden rounded-2xl",
        className,
      )}
      style={vars}
      {...props}
    >
      {children}
      <span
        aria-hidden
        className="bui-border-beam-glow pointer-events-none absolute inset-0 rounded-[inherit]"
      />
    </div>
  );
}

