"use client";

import {
  Children,
  cloneElement,
  isValidElement,
  useCallback,
  useEffect,
  useRef,
  useState,
  type FocusEvent,
  type HTMLAttributes,
  type ReactNode,
  type Ref,
} from "react";
import { RiArrowLeftSLine, RiArrowRightSLine } from "@remixicon/react";
import { IconButton } from "../buttons/icon-button";
import { useDirection } from "../../foundations/direction/direction";
import { inlineScrollOffset, scrollOffsetForItem } from "@/lib/scroll-direction";
import { cx } from "@/lib/utils";

/**
 * Gallery carousel: a horizontal run of cards you slide through.
 *
 * Built on native scrolling with CSS scroll-snap rather than a transformed
 * track. That is the whole design decision, and it buys a lot: touch swipe,
 * trackpad gestures, momentum, and keyboard scrolling all work without a line
 * of JavaScript, and the browser handles sub-pixel positioning better than a
 * translate ever does. JS is only here to answer which card is showing, whether
 * either end has been reached, and (optionally) autoplay / loop.
 *
 * Positions are read from each item's viewport bounds instead of being computed
 * from a card width, so items of different widths, responsive widths, or a
 * changed gap all keep working without the maths going stale.
 *
 * Follows the APG carousel pattern for naming: the region is a labelled group
 * that announces itself as a carousel, each item announces its position, and
 * the controls are real buttons that disable at the ends (unless `loop`).
 */

export interface CarouselProps
  extends Omit<HTMLAttributes<HTMLDivElement>, "children" | "onScroll"> {
  children: ReactNode;
  /** Names the carousel for assistive tech. */
  "aria-label": string;
  /** Prev/next buttons above the track. */
  showArrows?: boolean;
  /** Position indicator below the track. */
  showDots?: boolean;
  /** Where a card comes to rest when it snaps. */
  align?: "start" | "center";
  /** Gap between cards, in px. */
  gap?: number;
  /** Auto-advance slides. */
  autoplay?: boolean;
  /** Autoplay interval (ms). Default 4200. */
  interval?: number;
  /** Wrap from last → first (and reverse). Enables continuous autoplay. */
  loop?: boolean;
  /** Pause autoplay while hovered / focused. Default true. */
  pauseOnHover?: boolean;
  ref?: Ref<HTMLDivElement>;
}

export interface CarouselItemProps extends HTMLAttributes<HTMLDivElement> {
  children: ReactNode;
  ref?: Ref<HTMLDivElement>;
}

/**
 * One card, filling the track so exactly one is in view per slide. Width lives
 * here rather than on the track, so `className` can override it for a gallery
 * that shows a peek of the next card.
 */
export function CarouselItem({ children, className, ref, ...props }: CarouselItemProps) {
  return (
    <div
      ref={ref}
      role="group"
      aria-roledescription="slide"
      className={cx("w-full shrink-0 snap-start", className)}
      {...props}
    >
      {children}
    </div>
  );
}

export function Carousel({
  children,
  showArrows = true,
  showDots = true,
  align = "start",
  gap = 16,
  autoplay = false,
  interval = 4200,
  loop = false,
  pauseOnHover = true,
  className,
  ref,
  ...props
}: CarouselProps) {
  const trackRef = useRef<HTMLDivElement>(null);
  const direction = useDirection();
  const [active, setActive] = useState(0);
  const [atStart, setAtStart] = useState(true);
  const [atEnd, setAtEnd] = useState(false);
  const [paused, setPaused] = useState(false);
  const [progress, setProgress] = useState(0);
  const activeRef = useRef(0);
  const pausedRef = useRef(false);

  const count = Children.toArray(children).filter(isValidElement).length;

  const items = useCallback(
    () => Array.from(trackRef.current?.children ?? []) as HTMLElement[],
    [],
  );

  const measure = useCallback(() => {
    const track = trackRef.current;
    if (!track) return;

    // 1px of slack: scrollLeft is fractional on hi-DPI displays, so an exact
    // comparison leaves the end arrow enabled on a fully scrolled track.
    const offset = inlineScrollOffset(track.scrollLeft, direction);
    const start = offset <= 1;
    const end = offset >= track.scrollWidth - track.clientWidth - 1;
    setAtStart(start);
    setAtEnd(end);

    const all = items();
    if (all.length === 0) return;

    // At the far end the last cards share the viewport, so the final card can
    // never reach the start edge and "nearest" would settle on the one before
    // it — leaving the last dot permanently unlit and making a click on it
    // look broken. The ends are therefore pinned rather than measured.
    if (end) {
      activeRef.current = all.length - 1;
      setActive(all.length - 1);
      return;
    }
    if (start) {
      activeRef.current = 0;
      setActive(0);
      return;
    }

    let nearest = 0;
    let shortest = Number.POSITIVE_INFINITY;
    all.forEach((item, index) => {
      const distance = Math.abs(
        scrollOffsetForItem(
          track.getBoundingClientRect(),
          item.getBoundingClientRect(),
          0,
          direction,
          align,
        ),
      );
      if (distance < shortest) {
        shortest = distance;
        nearest = index;
      }
    });
    activeRef.current = nearest;
    setActive(nearest);
  }, [items, direction, align]);

  useEffect(() => {
    const track = trackRef.current;
    if (!track) return;

    // ResizeObserver fires once on observe, which is what takes the first
    // measurement — no synchronous setState in the effect body.
    const observer = new ResizeObserver(measure);
    observer.observe(track);
    track.addEventListener("scroll", measure, { passive: true });
    return () => {
      observer.disconnect();
      track.removeEventListener("scroll", measure);
    };
  }, [measure]);

  const scrollToIndex = useCallback(
    (index: number) => {
      const track = trackRef.current;
      if (!track || count === 0) return;
      let next = index;
      if (loop) {
        next = ((index % count) + count) % count;
      } else {
        next = Math.max(0, Math.min(index, count - 1));
      }
      const target = items()[next];
      if (!target) return;
      const reduce = window.matchMedia("(prefers-reduced-motion: reduce)").matches;
      const left = scrollOffsetForItem(
        track.getBoundingClientRect(),
        target.getBoundingClientRect(),
        track.scrollLeft,
        direction,
        align,
      );
      track.scrollTo({ left, behavior: reduce ? "auto" : "smooth" });
      setProgress(0);
    },
    [align, count, direction, items, loop],
  );

  useEffect(() => {
    pausedRef.current = paused;
  }, [paused]);

  useEffect(() => {
    if (!autoplay || count < 2) return;
    const reduce =
      typeof window !== "undefined" &&
      window.matchMedia("(prefers-reduced-motion: reduce)").matches;
    if (reduce) return;

    let raf = 0;
    let started = performance.now();
    let elapsedAtPause = 0;
    const tick = (now: number) => {
      if (pausedRef.current) {
        elapsedAtPause = now - started;
        raf = requestAnimationFrame(tick);
        return;
      }
      if (elapsedAtPause > 0) {
        started = now - elapsedAtPause;
        elapsedAtPause = 0;
      }
      const t = Math.min(1, (now - started) / interval);
      setProgress(t);
      if (t >= 1) {
        const next = activeRef.current + 1;
        if (loop || next < count) {
          scrollToIndex(next);
        }
        started = now;
        setProgress(0);
      }
      raf = requestAnimationFrame(tick);
    };
    raf = requestAnimationFrame(tick);
    return () => cancelAnimationFrame(raf);
  }, [autoplay, count, interval, loop, scrollToIndex]);

  // Reset progress when the active slide changes from user interaction.
  useEffect(() => {
    setProgress(0);
  }, [active]);

  const hoverHandlers =
    autoplay && pauseOnHover
      ? {
          onMouseEnter: () => setPaused(true),
          onMouseLeave: () => setPaused(false),
          onFocusCapture: () => setPaused(true),
          onBlurCapture: (event: FocusEvent<HTMLDivElement>) => {
            if (!event.currentTarget.contains(event.relatedTarget as Node | null)) {
              setPaused(false);
            }
          },
        }
      : {};

  return (
    <div
      ref={ref}
      role="group"
      dir={direction}
      aria-roledescription="carousel"
      className={cx("flex w-full flex-col gap-4", className)}
      {...hoverHandlers}
      {...props}
    >
      {showArrows && count > 0 ? (
        <div className="flex items-center justify-end gap-2">
          <IconButton
            icon={RiArrowLeftSLine}
            size="small"
            aria-label="Previous slide"
            disabled={!loop && atStart}
            onClick={() => scrollToIndex(active - 1)}
          />
          <IconButton
            icon={RiArrowRightSLine}
            size="small"
            aria-label="Next slide"
            disabled={!loop && atEnd}
            onClick={() => scrollToIndex(active + 1)}
          />
        </div>
      ) : null}

      {/* `tabIndex` makes the track focusable so it can be scrolled with the
          arrow keys, which is the browser's own behaviour once it has focus.
          The scrollbar is hidden inline rather than through a global class, so
          the component stays self-contained. */}
      <div
        ref={trackRef}
        tabIndex={0}
        className={cx(
          "relative flex w-full overflow-x-auto overscroll-x-contain outline-none",
          "snap-x snap-mandatory [scrollbar-width:none] [&::-webkit-scrollbar]:hidden",
          "focus-visible:ring-2 focus-visible:ring-border-focus-ring focus-visible:ring-offset-2",
          align === "center" && "[&>*]:snap-center",
        )}
        style={{ gap }}
      >
        {/* The position label is applied here so callers never have to
            hand-number their own slides. */}
        {Children.map(children, (child, index) =>
          isValidElement<CarouselItemProps>(child)
            ? cloneElement(child, { "aria-label": `${index + 1} of ${count}` })
            : child,
        )}
      </div>

      {showDots && count > 1 ? (
        <div className="flex items-center justify-center gap-1.5">
          {Array.from({ length: count }, (_, index) => (
            <button
              key={index}
              type="button"
              aria-label={`Go to slide ${index + 1}`}
              aria-current={index === active}
              onClick={() => scrollToIndex(index)}
              className={cx(
                "relative h-1.5 cursor-pointer overflow-hidden rounded-full transition-all duration-200 ease-out",
                index === active
                  ? autoplay
                    ? "w-6 bg-background-tertiary-default"
                    : "w-4 bg-text-primary"
                  : "w-1.5 bg-background-tertiary-default hover:bg-border-button-active",
              )}
            >
              {autoplay && index === active ? (
                <span
                  aria-hidden
                  className="absolute inset-y-0 start-0 rounded-full bg-text-primary"
                  style={{ width: `${progress * 100}%` }}
                />
              ) : null}
            </button>
          ))}
        </div>
      ) : null}
    </div>
  );
}

