import {
  ColorArea as AriaColorArea,
  ColorField as AriaColorField,
  ColorPicker as AriaColorPicker,
  ColorSlider as AriaColorSlider,
  ColorSwatch as AriaColorSwatch,
  ColorSwatchPicker as AriaColorSwatchPicker,
  ColorSwatchPickerItem as AriaColorSwatchPickerItem,
  ColorThumb as AriaColorThumb,
  Input as AriaInput,
  SliderTrack as AriaSliderTrack,
} from "react-aria-components";
import type { ColorPickerProps as AriaColorPickerProps } from "react-aria-components";
import { Popover, PopoverTrigger } from "../popover/popover";
import type { PopoverProps } from "../popover/popover";
import { useTemplateCopy } from "../../foundations/template-copy/template-copy";
import { cx } from "@/lib/utils";

/**
 * Color picker — choose a colour by eye or by hex: a brand colour, a label,
 * a chart series.
 *
 *   <ColorPicker value={color} onChange={setColor} />
 *   <ColorWell aria-label="Brand color" value={color} onChange={setColor} />
 *
 * Promoted from the theme customizer's picker, with its look: a
 * saturation and brightness field and a hue rail, both with the slider's
 * white embossed thumb, and a hex row on the input's tertiary surface.
 * `showAlpha` adds an opacity rail over a checkerboard, and `swatches` adds
 * a row of presets. `ColorWell` is a round swatch that opens the same
 * editor in a popover.
 *
 * Built on React Aria's color components, so the colour is kept in HSB
 * while you drag (its hue survives a trip through grey), each control is
 * reachable by keyboard (arrows nudge, Shift or Page keys take bigger
 * steps), and the hex field takes any CSS colour and commits on Enter or
 * blur. Values are hex strings or React Aria `Color` objects.
 */

/** The slider's white embossed thumb, filled with the colour under it. */
const THUMB = [
  "size-4 rounded-full border border-white shadow-[0_2px_4px_rgb(0_0_0/0.18),inset_0_0_0_1px_rgb(0_0_0/0.06)]",
  "transition-[scale] duration-150 ease-out data-[dragging]:scale-110",
  "data-[focus-visible]:ring-2 data-[focus-visible]:ring-border-focus-ring data-[focus-visible]:ring-offset-2",
].join(" ");

/** The inset hairline that keeps light colours from melting into the page. */
const HAIRLINE = "pointer-events-none absolute inset-0 shadow-[inset_0_0_0_1px_rgb(0_0_0/0.06)]";

const CHECKERBOARD =
  "bg-[repeating-conic-gradient(#e6e6e6_0%_25%,#ffffff_0%_50%)] bg-[length:8px_8px] dark:bg-[repeating-conic-gradient(#3a3a3a_0%_25%,#262626_0%_50%)]";

interface EditorProps {
  showAlpha?: boolean;
  swatches?: string[];
  className?: string;
}

/** The controls, bound to the nearest React Aria ColorPicker. */
function Editor({ showAlpha = false, swatches, className }: EditorProps) {
  const localize = useTemplateCopy();

  return (
    <div className={cx("flex w-[228px] max-w-full flex-col gap-2.5", className)}>
      <AriaColorArea
        colorSpace="hsb"
        xChannel="saturation"
        yChannel="brightness"
        className="relative aspect-[3/2] w-full shrink-0 cursor-crosshair rounded-2xl"
      >
        <span aria-hidden className={cx(HAIRLINE, "rounded-2xl")} />
        <AriaColorThumb className={THUMB} />
      </AriaColorArea>

      <AriaColorSlider colorSpace="hsb" channel="hue" className="w-full">
        <AriaSliderTrack className="relative h-3 w-full cursor-pointer rounded-full">
          <span aria-hidden className={cx(HAIRLINE, "rounded-full")} />
          <AriaColorThumb className={cx(THUMB, "top-1/2")} />
        </AriaSliderTrack>
      </AriaColorSlider>

      {showAlpha ? (
        <AriaColorSlider channel="alpha" className="w-full">
          <div className={cx("relative h-3 w-full rounded-full", CHECKERBOARD)}>
            <AriaSliderTrack className="relative h-3 w-full cursor-pointer rounded-full">
              <span aria-hidden className={cx(HAIRLINE, "rounded-full")} />
              <AriaColorThumb className={cx(THUMB, "top-1/2")} />
            </AriaSliderTrack>
          </div>
        </AriaColorSlider>
      ) : null}

      <div className="flex items-center gap-2">
        <AriaColorSwatch className="relative size-8 shrink-0 rounded-full shadow-[inset_0_0_0_1px_rgb(0_0_0/0.06)]" />
        <AriaColorField aria-label={localize("Hex color")} className="min-w-0 flex-1">
          <AriaInput
            dir="ltr"
            spellCheck={false}
            onKeyDown={(event) => {
              // React Aria commits the field on blur only; Enter commits it
              // too, and focus stays in the field.
              if (event.key !== "Enter") return;
              const input = event.currentTarget;
              input.blur();
              input.focus();
            }}
            className={cx(
              "h-8 w-full min-w-0 rounded-2lg bg-background-tertiary-default px-2.5 font-mono text-[13px] text-text-primary uppercase",
              "outline-none ring-2 ring-transparent ring-inset transition-[background-color,box-shadow] duration-150 ease",
              "focus:bg-background-primary-default focus:ring-border-focus-ring",
            )}
          />
        </AriaColorField>
      </div>

      {swatches?.length ? (
        <AriaColorSwatchPicker aria-label={localize("Presets")} className="grid grid-cols-7 gap-1.5 pt-0.5">
          {swatches.map((swatch) => (
            <AriaColorSwatchPickerItem
              key={swatch}
              color={swatch}
              className={cx(
                "group/swatch relative aspect-square w-full cursor-pointer rounded-full outline-none transition-[scale] duration-150 ease-out hover:scale-110",
                "data-[focus-visible]:ring-2 data-[focus-visible]:ring-border-focus-ring data-[focus-visible]:ring-offset-2",
              )}
            >
              <AriaColorSwatch className="size-full rounded-full shadow-[inset_0_0_0_1px_rgb(0_0_0/0.08)]" />
              {/* Selected: a white ring inside a dark hairline reads on any colour. */}
              <span
                aria-hidden
                className="pointer-events-none absolute inset-0 rounded-full opacity-0 shadow-[inset_0_0_0_2px_#fff,inset_0_0_0_3px_rgb(0_0_0/0.25)] transition-opacity duration-150 group-data-[selected]/swatch:opacity-100"
              />
            </AriaColorSwatchPickerItem>
          ))}
        </AriaColorSwatchPicker>
      ) : null}
    </div>
  );
}

export interface ColorPickerProps extends Omit<AriaColorPickerProps, "children"> {
  /** Add an opacity rail. Default false. */
  showAlpha?: boolean;
  /** Preset colours, as CSS colour strings, in a row under the editor. */
  swatches?: string[];
  /** Classes on the editor, e.g. a width. Default 228px. */
  className?: string;
}

export function ColorPicker({ showAlpha, swatches, className, ...props }: ColorPickerProps) {
  return (
    <AriaColorPicker {...props}>
      <Editor showAlpha={showAlpha} swatches={swatches} className={className} />
    </AriaColorPicker>
  );
}

export interface ColorWellProps extends ColorPickerProps {
  /** Names the swatch button and its popover. Default "Color". */
  "aria-label"?: string;
  /** Where the editor opens. Default "bottom start". */
  placement?: PopoverProps["placement"];
  /** Classes on the swatch button, e.g. a size. Default 32px. */
  wellClassName?: string;
}

/** A round swatch that opens the editor in a popover. */
export function ColorWell({
  "aria-label": ariaLabel = "Color",
  placement = "bottom start",
  showAlpha,
  swatches,
  className,
  wellClassName,
  ...props
}: ColorWellProps) {
  const localize = useTemplateCopy();
  const label = localize(ariaLabel);

  return (
    <AriaColorPicker {...props}>
      <PopoverTrigger>
        <button
          type="button"
          aria-label={label}
          className={cx(
            "relative size-8 shrink-0 cursor-pointer rounded-full outline-none transition-[scale] duration-150 ease-out hover:scale-110",
            "focus-visible:ring-2 focus-visible:ring-border-focus-ring focus-visible:ring-offset-2",
            wellClassName,
          )}
        >
          <AriaColorSwatch className="size-full rounded-full shadow-[inset_0_0_0_1px_rgb(0_0_0/0.08)]" />
        </button>
        <Popover aria-label={label} placement={placement} className="w-[248px] rounded-3xl" dialogClassName="p-1">
          <Editor showAlpha={showAlpha} swatches={swatches} className={cx("w-full", className)} />
        </Popover>
      </PopoverTrigger>
    </AriaColorPicker>
  );
}

"use client";

import { useEffect, useRef, useState } from "react";
import type { ComponentType, ReactNode, Ref } from "react";
import {
  Button as AriaButton,
  ComboBox as AriaComboBox,
  Header as AriaHeader,
  ListBox as AriaListBox,
  ListBoxItem as AriaListBoxItem,
  ListBoxSection as AriaListBoxSection,
  Popover as AriaPopover,
} from "react-aria-components";
import type {
  ComboBoxProps as AriaComboBoxProps,
  ListBoxItemProps as AriaListBoxItemProps,
  ListBoxSectionProps as AriaListBoxSectionProps,
} from "react-aria-components";
import { RiCheckLine } from "@remixicon/react";
import { MENU_ITEM, MENU_ITEM_ACTIVE, MENU_ITEMS_CONTAINER, MENU_POPOVER_SURFACE } from "../dropdown/menu-styles";
import { HintText } from "../input/hint-text";
import { InputBase, type InputSize } from "../input/input";
import { Label } from "../input/label";
import { useDirection } from "../../foundations/direction/direction";
import { ChevronDownSmall } from "../../foundations/icons/chevrons";
import { ScrollFade, useScrollFade } from "../../foundations/scroll-fade/scroll-fade";
import { cx } from "@/lib/utils";

/**
 * ComboBox — a text field that filters a list as you type: pick an assignee,
 * a country, a timezone. Built on React Aria's ComboBox, so the list is a
 * real listbox with arrow-key navigation, typeahead filtering, and
 * screen-reader announcements.
 *
 *   <ComboBox label="Assignee" placeholder="Search people" defaultItems={people}>
 *     {(person) => <ComboBoxItem textValue={person.name}>…</ComboBoxItem>}
 *   </ComboBox>
 *
 * The field is Input's own InputBase (same surface, hover and focus rings,
 * invalid and disabled states), with the toggle in its trailing slot. The
 * list is Select's: the shared menu surface and motion, radius/2lg rows,
 * the hover surface on the focused row, and a check on the selected one. It
 * opens under the whole field at the field's width, rather than under the
 * bare input React Aria would anchor to, and its rows scroll under the
 * shared progressive top blur.
 */

type IconComponent = ComponentType<{ className?: string; "aria-hidden"?: boolean | "true" | "false" }>;

export interface ComboBoxProps<T extends object> extends Omit<AriaComboBoxProps<T>, "children" | "className"> {
  label?: ReactNode;
  /** Help text under the field; shown in the error colour while invalid. */
  hint?: ReactNode;
  placeholder?: string;
  leadingIcon?: IconComponent;
  /** `medium` (default, 36px) or `small` (32px), as Input. */
  size?: InputSize;
  /** Shown in the list when nothing matches. */
  emptyMessage?: ReactNode;
  className?: string;
  /** Classes on the list's popover. */
  popoverClassName?: string;
  children: ReactNode | ((item: T) => ReactNode);
  ref?: Ref<HTMLDivElement>;
}

export function ComboBox<T extends object>({
  label,
  hint,
  placeholder,
  leadingIcon,
  size,
  emptyMessage = "No results",
  className,
  popoverClassName,
  children,
  ref,
  ...props
}: ComboBoxProps<T>) {
  const direction = useDirection();
  const fieldRef = useRef<HTMLDivElement>(null);
  const fade = useScrollFade();
  const [fieldWidth, setFieldWidth] = useState<number>();

  useEffect(() => {
    const field = fieldRef.current;
    if (!field) return;
    const observer = new ResizeObserver(() => setFieldWidth(field.offsetWidth));
    observer.observe(field);
    return () => observer.disconnect();
  }, []);

  return (
    <AriaComboBox
      ref={ref}
      allowsEmptyCollection
      {...props}
      className={cx("group flex flex-col gap-1", className)}
      onOpenChange={(isOpen, trigger) => {
        // Each opening starts the list at the top, so the fade starts hidden.
        if (isOpen) fade.reset();
        props.onOpenChange?.(isOpen, trigger);
      }}
    >
      {({ isOpen, isRequired, isInvalid }) => (
        <>
          {label ? <Label isRequired={isRequired}>{label}</Label> : null}
          <InputBase
            groupRef={fieldRef}
            size={size}
            // Match Select trigger: primary fill + button border (not Input well).
            surface="outline"
            placeholder={placeholder}
            leadingIcon={leadingIcon}
            trailingAddon={
              <AriaButton
                className={({ isFocusVisible }) =>
                  cx(
                    "-m-1 flex shrink-0 cursor-pointer items-center justify-center rounded-md p-1 text-text-secondary outline-none",
                    isFocusVisible && "ring-2 ring-border-focus-ring",
                  )
                }
              >
                <ChevronDownSmall
                  className={cx("size-4 transition-transform duration-200 ease", isOpen && "rotate-180")}
                />
              </AriaButton>
            }
          />
          {hint ? <HintText isInvalid={isInvalid}>{hint}</HintText> : null}
          <AriaPopover
            triggerRef={fieldRef}
            dir={direction}
            offset={4}
            style={{ width: fieldWidth }}
            className={cx(MENU_POPOVER_SURFACE, "flex flex-col overflow-hidden p-2", popoverClassName)}
          >
            <div className="relative flex min-h-0 flex-col">
              <AriaListBox
                onScroll={fade.onScroll}
                renderEmptyState={() => (
                  <div className="px-2 py-2 text-body-medium text-text-tertiary">{emptyMessage}</div>
                )}
                className={cx(MENU_ITEMS_CONTAINER, "max-h-[240px] min-h-0 overflow-y-auto overscroll-contain")}
              >
                {children}
              </AriaListBox>
              <ScrollFade progress={fade.progress} />
            </div>
          </AriaPopover>
        </>
      )}
    </AriaComboBox>
  );
}

export interface ComboBoxItemProps extends Omit<AriaListBoxItemProps, "children"> {
  children?: ReactNode;
}

/** A row in the list. Content is free-form: an avatar and a name, a flag and a country. */
export function ComboBoxItem({ className, children, ...props }: ComboBoxItemProps) {
  return (
    <AriaListBoxItem
      {...props}
      className={(state) =>
        cx(
          MENU_ITEM,
          "text-body-medium",
          state.isFocused && MENU_ITEM_ACTIVE,
          state.isDisabled && "cursor-not-allowed text-text-disabled",
          typeof className === "function" ? className(state) : className,
        )
      }
    >
      {({ isSelected }) => (
        <>
          <span className="flex min-w-0 flex-1 items-center gap-2">{children}</span>
          {isSelected ? <RiCheckLine className="size-4 shrink-0 text-accent-500" aria-hidden /> : null}
        </>
      )}
    </AriaListBoxItem>
  );
}

export interface ComboBoxSectionProps<T extends object> extends Omit<AriaListBoxSectionProps<T>, "className" | "children"> {
  /** Muted heading above the section's rows. */
  title?: ReactNode;
  className?: string;
  /** ComboBoxItems, or a React Aria Collection for a dynamic section. */
  children: ReactNode;
}

export function ComboBoxSection<T extends object>({ title, className, children, ...props }: ComboBoxSectionProps<T>) {
  return (
    <AriaListBoxSection {...props} className={cx("flex flex-col gap-1 [&:not(:first-child)]:pt-2", className)}>
      {title ? <AriaHeader className="ps-2 pt-1 pb-0.5 text-body-medium text-text-secondary">{title}</AriaHeader> : null}
      {children}
    </AriaListBoxSection>
  );
}

"use client";

import { useEffect, useState } from "react";
import type { ComponentType, ReactNode } from "react";
import {
  Autocomplete as AriaAutocomplete,
  Dialog as AriaDialog,
  Header as AriaHeader,
  Input as AriaInput,
  Menu as AriaMenu,
  MenuItem as AriaMenuItem,
  MenuSection as AriaMenuSection,
  Modal as AriaModal,
  ModalOverlay as AriaModalOverlay,
  SearchField as AriaSearchField,
  useFilter,
} from "react-aria-components";
import type { Key, MenuItemProps as AriaMenuItemProps } from "react-aria-components";
import { RiCornerDownLeftLine, RiSearchLine } from "@remixicon/react";
import { Kbd } from "../kbd/kbd";
import { useDirection } from "../../foundations/direction/direction";
import { ScrollFade, useScrollFade } from "../../foundations/scroll-fade/scroll-fade";
import { useTemplateCopy } from "../../foundations/template-copy/template-copy";
import { cx } from "@/lib/utils";

/**
 * Command palette — a searchable list of actions and destinations, opened
 * with ⌘K / Ctrl+K: jump to a page, run a command, find a record.
 *
 *   <CommandPalette isOpen={open} onOpenChange={setOpen}>
 *     <CommandPaletteSection title="Navigation">
 *       <CommandPaletteItem id="home" icon={RiHome5Line} onAction={…}>Dashboard</CommandPaletteItem>
 *     </CommandPaletteSection>
 *   </CommandPalette>
 *
 * Promoted from the docs site's component search, with its surface and
 * motion: a black/20 scrim, a radius/3xl panel 12vh from the top that fades
 * in, lifts 10px and sharpens from a 4px blur over 200ms, a search row over
 * a scrolling list (with the shared progressive top blur), and a footer of
 * keyboard hints.
 *
 * Built on React Aria's Autocomplete and Menu in a modal dialog, so the
 * input keeps focus while arrows move a virtual highlight through the list,
 * Enter runs the highlighted command, Escape clears the query and then
 * closes, and focus returns to wherever it was. Items filter by their text
 * with a locale-aware contains match; pass `filter={null}` and filter the
 * children yourself for custom ranking. The palette's own copy (label,
 * placeholder, empty state, hints) goes through `useTemplateCopy`, so a
 * TemplateCopyProvider translates it.
 */

type IconComponent = ComponentType<{ className?: string; "aria-hidden"?: boolean | "true" | "false" }>;

export interface CommandPaletteProps {
  isOpen?: boolean;
  defaultOpen?: boolean;
  onOpenChange?: (isOpen: boolean) => void;
  /** Letter that opens and closes it with ⌘ / Ctrl. `false` turns the shortcut off. Default "k". */
  shortcut?: string | false;
  /** Accessible name of the dialog. Default "Command palette". */
  "aria-label"?: string;
  placeholder?: string;
  /** Controlled query. */
  inputValue?: string;
  onInputChange?: (value: string) => void;
  /** Match items against the query; `null` shows the children as given. Default: contains, ignoring case and accents. */
  filter?: ((textValue: string, inputValue: string) => boolean) | null;
  /** Called with the id of the item run from the keyboard or the pointer, after the palette closes. */
  onAction?: (key: Key) => void;
  /** Shown when nothing matches. */
  emptyState?: ReactNode;
  /** The hint row under the list; `false` hides it. */
  footer?: ReactNode | false;
  className?: string;
  children: ReactNode;
}

export function CommandPalette({
  isOpen: controlledOpen,
  defaultOpen = false,
  onOpenChange,
  shortcut = "k",
  "aria-label": ariaLabel = "Command palette",
  placeholder = "Type a command or search…",
  inputValue: controlledInput,
  onInputChange,
  filter,
  onAction,
  emptyState = "No results",
  footer,
  className,
  children,
}: CommandPaletteProps) {
  const direction = useDirection();
  const localize = useTemplateCopy();
  const label = localize(ariaLabel);
  const { contains } = useFilter({ sensitivity: "base" });
  const fade = useScrollFade();
  const [uncontrolledOpen, setUncontrolledOpen] = useState(defaultOpen);
  const [uncontrolledInput, setUncontrolledInput] = useState("");
  const isOpen = controlledOpen ?? uncontrolledOpen;
  const inputValue = controlledInput ?? uncontrolledInput;

  const setOpen = (next: boolean) => {
    setUncontrolledOpen(next);
    onOpenChange?.(next);
    if (next) {
      // Every opening starts fresh: an empty query and the list at its top.
      setUncontrolledInput("");
      onInputChange?.("");
      fade.reset();
    }
  };

  useEffect(() => {
    if (shortcut === false) return;
    const onKeyDown = (event: KeyboardEvent) => {
      if (!(event.metaKey || event.ctrlKey) || event.key.toLowerCase() !== shortcut.toLowerCase()) return;
      event.preventDefault();
      setOpen(!isOpen);
    };
    window.addEventListener("keydown", onKeyDown);
    return () => window.removeEventListener("keydown", onKeyDown);
  });

  return (
    <AriaModalOverlay
      isOpen={isOpen}
      onOpenChange={setOpen}
      isDismissable
      dir={direction}
      className="group/palette fixed inset-x-0 top-0 z-100 flex h-(--visual-viewport-height) items-start justify-center px-4 pt-[12vh]"
    >
      <div
        aria-hidden
        className="absolute inset-0 bg-black/20 transition-opacity duration-150 ease-out group-data-[entering]/palette:opacity-0 group-data-[exiting]/palette:opacity-0"
      />
      <AriaModal
        className={cx(
          "relative flex max-h-[min(560px,76vh)] w-full max-w-[560px] flex-col outline-none",
          "transition-[opacity,translate,scale,filter] duration-200 ease-out",
          "data-[entering]:opacity-0 data-[exiting]:opacity-0",
          "motion-safe:data-[entering]:translate-y-2.5 motion-safe:data-[entering]:scale-[0.98] motion-safe:data-[entering]:blur-[4px]",
          "motion-safe:data-[exiting]:translate-y-2 motion-safe:data-[exiting]:scale-[0.98] motion-safe:data-[exiting]:blur-[3px]",
        )}
      >
        <AriaDialog
          aria-label={label}
          className={cx(
            "flex min-h-0 flex-1 flex-col overflow-clip rounded-3xl border border-border-button-default bg-background-primary-default shadow-sidebar outline-none",
            className,
          )}
        >
          <AriaAutocomplete
            inputValue={inputValue}
            onInputChange={(value) => {
              setUncontrolledInput(value);
              onInputChange?.(value);
            }}
            filter={filter === null ? undefined : filter ?? contains}
          >
            <AriaSearchField aria-label={label} autoFocus className="flex shrink-0 items-center gap-2 border-b border-separator-border p-3">
              <RiSearchLine className="size-5 shrink-0 text-foreground-icon-secondary" aria-hidden />
              <AriaInput
                placeholder={localize(placeholder)}
                className="min-w-0 flex-1 bg-transparent text-body-medium text-text-primary outline-none placeholder:text-text-tertiary [&::-webkit-search-cancel-button]:hidden"
              />
            </AriaSearchField>
            <div className="relative flex min-h-0 flex-1 flex-col">
              <AriaMenu
                aria-label={label}
                onScroll={fade.onScroll}
                onAction={(key) => {
                  setOpen(false);
                  onAction?.(key);
                }}
                renderEmptyState={() => (
                  <div className="flex min-h-32 flex-col items-center justify-center gap-1 px-4 text-center text-body-medium text-text-tertiary">
                    {localize(emptyState)}
                  </div>
                )}
                className="flex min-h-0 flex-1 flex-col gap-0.5 overflow-y-auto overscroll-contain p-2 outline-none [scrollbar-width:thin]"
              >
                {children}
              </AriaMenu>
              <ScrollFade progress={fade.progress} />
            </div>
          </AriaAutocomplete>
          {footer === false ? null : (
            <div className="flex shrink-0 items-center justify-between border-t border-separator-border px-3 py-2 text-body-regular text-text-tertiary">
              {localize(
                footer ?? (
                  <>
                    <span>Navigate with ↑ ↓</span>
                    <span className="flex items-center gap-1.5">
                      Select
                      <Kbd aria-label="Enter">
                        <RiCornerDownLeftLine className="size-3" aria-hidden />
                      </Kbd>
                    </span>
                  </>
                ),
              )}
            </div>
          )}
        </AriaDialog>
      </AriaModal>
    </AriaModalOverlay>
  );
}

export interface CommandPaletteItemProps extends Omit<AriaMenuItemProps, "children" | "className"> {
  /** Remix Icon before the label. */
  icon?: IconComponent;
  /** Muted text at the end of the row, e.g. the section or a path. */
  description?: ReactNode;
  /** Keyboard shortcut shown at the end of the row, e.g. "⌘N". */
  shortcut?: string;
  className?: string;
  children: ReactNode;
}

export function CommandPaletteItem({ icon: Icon, description, shortcut, className, children, ...props }: CommandPaletteItemProps) {
  return (
    <AriaMenuItem
      {...props}
      textValue={props.textValue ?? (typeof children === "string" ? children : undefined)}
      className={({ isFocused }) =>
        cx(
          "flex w-full cursor-pointer items-center gap-2 rounded-xl px-3 py-2.5 text-start outline-none transition-colors duration-100 ease-out",
          isFocused && "bg-background-secondary-default",
          "data-[disabled]:cursor-not-allowed data-[disabled]:opacity-50",
          className,
        )
      }
    >
      <span className="flex min-w-0 flex-1 items-center gap-2">
        {Icon ? <Icon className="size-4 shrink-0 text-foreground-icon-secondary" aria-hidden /> : null}
        <span className="flex min-w-0 items-center gap-2 truncate text-body-medium text-text-primary">{children}</span>
      </span>
      {description ? <span className="shrink-0 text-body-regular text-text-tertiary">{description}</span> : null}
      {shortcut ? <Kbd>{shortcut}</Kbd> : null}
    </AriaMenuItem>
  );
}

export interface CommandPaletteSectionProps {
  /** Muted heading above the section's items. */
  title?: ReactNode;
  className?: string;
  children: ReactNode;
}

export function CommandPaletteSection({ title, className, children }: CommandPaletteSectionProps) {
  return (
    <AriaMenuSection className={cx("flex flex-col gap-0.5 [&:not(:first-child)]:pt-2", className)}>
      {title ? <AriaHeader className="px-3 pt-1 pb-1 text-body-2-medium text-text-tertiary">{title}</AriaHeader> : null}
      {children}
    </AriaMenuSection>
  );
}

