}

export function DashboardUserMenu({
  collapsed = false,
  suppressHover = false,
  onHoverSuppressionEnd,
  avatarClassName,
}: {
  collapsed?: boolean;
  /** Prevents expansion from creating a hover state under a stationary pointer. */
  suppressHover?: boolean;
  /** Re-arms hover after the pointer fully leaves the trigger. */
  onHoverSuppressionEnd?: () => void;
  avatarClassName?: string;
}) {
  const localize = useTemplateCopy();
  const direction = useDirection();
  const [isOpen, setIsOpen] = useState(false);
  // "right" placement assumes room to the sidebar's right (true in-flow on
  // desktop) — on mobile the sidebar can span the full viewport, so the
  // 265px panel would render off-screen. Below sm, drop into a plain
  // dropdown under the trigger instead.
  const [isMobile, setIsMobile] = useState(false);
  useEffect(() => {
    const mq = window.matchMedia("(max-width: 639px)");
    setIsMobile(mq.matches);
    const onChange = (e: MediaQueryListEvent) => setIsMobile(e.matches);
    mq.addEventListener("change", onChange);
    return () => mq.removeEventListener("change", onChange);
  }, []);

  return localize((
    <AriaDialogTrigger isOpen={isOpen} onOpenChange={setIsOpen}>
      <AriaButton
        aria-label="Mertcan Esmergul"
        onPointerLeave={() => {
          if (suppressHover) onHoverSuppressionEnd?.();
        }}
        className={cx(
          "relative flex min-w-0 cursor-pointer items-center gap-2 rounded-full outline-none",
          "focus-visible:ring-2 focus-visible:ring-border-focus-ring focus-visible:ring-offset-2",
          // Hover pill (Figma node 3829:4063): a fully-rounded 2px border/button/hover
          // outline drawn via a pseudo-element so it never shifts the layout.
          "before:pointer-events-none before:absolute before:-inset-x-1.5 before:-inset-y-[5px] before:rounded-full before:border-2 before:border-transparent before:transition-colors before:duration-150",
          !suppressHover && "hover:before:border-border-sidebar-profile-hover",
          // Collapsed, the trigger takes the rail's own 36px column and centres
          // the 32px avatar in it, instead of sizing to the avatar plus a gap
          // held open for a label that's shrunk to nothing. That gap made the
          // button 42px wide in a 36px rail, which pushed its hover pill
          // off-centre and into the rail's clip.
          //
          // The pill's insets go square too: 36×32 plus the expanded 6/5 reach
          // is a 48×42 stadium, not the circle the avatar wants. 3/5 lands it
          // on 42×42.
          collapsed && "w-9 justify-center gap-0 before:-inset-x-[3px]",
        )}
      >
        <Avatar size="md" color="neutral" initials="M" className={avatarClassName} />
        <Collapsible collapsed={collapsed}>
          <span className="flex items-center gap-0.5">
            <span className="text-body-medium whitespace-nowrap text-text-primary">Mertcan Esmergul</span>
            <ChevronUpDownSmall className="size-4 shrink-0 text-foreground-icon-tertiary" />
          </span>
        </Collapsible>
      </AriaButton>

      <AriaPopover
        placement={isMobile ? "bottom start" : direction === "rtl" ? "left top" : "right top"}
        offset={8}
        className={cx(
          "w-[265px] max-w-[calc(100vw-32px)] origin-top-left overflow-y-auto",
          "rounded-2xl border border-border-button-default bg-background-primary-default p-2.5 shadow-dropdown",
          "transition duration-150 ease-out",
          "data-[entering]:opacity-0 data-[entering]:scale-95 data-[entering]:blur-[2px]",
          "data-[exiting]:opacity-0 data-[exiting]:scale-95 data-[exiting]:blur-[2px]",
        )}
      >
        <AriaDialog aria-label="Account menu" className="flex flex-col outline-none">
          <AccountMenuContent onSelect={() => setIsOpen(false)} />
        </AriaDialog>
      </AriaPopover>
    </AriaDialogTrigger>
  ));
}

"use client";

import { useMemo, useState } from "react";

import { Chip } from "../../base/badges/chip";
import {
  SegmentedControl,
  SegmentedControlItem,
} from "../../base/segmented-control/segmented-control";
import { useCountUp } from "@/hooks/use-count-up";
import { cx } from "@/lib/utils";

/**
 * Earnings Chart Card: “至今已赚到” with custom CSS track bars.
 * Each month is a full-height gray track and a lime fill rising from the bottom.
 */

type Period = "weekly" | "monthly" | "yearly";

export type EarningsPoint = {
  label: string;
  value: number;
};

const PERIOD_META: Record<Period, { total: number; delta: number }> = {
  weekly: { total: 1680, delta: 8.2 },
  monthly: { total: 7462, delta: 14.8 },
  yearly: { total: 89440, delta: 11.3 },
};

const PERIOD_DATA: Record<Period, EarningsPoint[]> = {
  weekly: [
    { label: "1月", value: 90 },
    { label: "2月", value: 110 },
    { label: "3月", value: 100 },
    { label: "4月", value: 130 },
    { label: "5月", value: 145 },
    { label: "6月", value: 140 },
    { label: "7月", value: 160 },
    { label: "8月", value: 155 },
    { label: "9月", value: 170 },
    { label: "10月", value: 180 },
    { label: "11月", value: 165 },
    { label: "12月", value: 135 },
  ],
  monthly: [
    { label: "1月", value: 420 },
    { label: "2月", value: 480 },
    { label: "3月", value: 510 },
    { label: "4月", value: 560 },
    { label: "5月", value: 620 },
    { label: "6月", value: 590 },
    { label: "7月", value: 680 },
    { label: "8月", value: 650 },
    { label: "9月", value: 710 },
    { label: "10月", value: 760 },
    { label: "11月", value: 700 },
    { label: "12月", value: 782 },
  ],
  yearly: [
    { label: "1月", value: 5040 },
    { label: "2月", value: 5760 },
    { label: "3月", value: 6120 },
    { label: "4月", value: 6720 },
    { label: "5月", value: 7440 },
    { label: "6月", value: 7080 },
    { label: "7月", value: 8160 },
    { label: "8月", value: 7800 },
    { label: "9月", value: 8520 },
    { label: "10月", value: 9120 },
    { label: "11月", value: 8400 },
    { label: "12月", value: 9280 },
  ],
};

const Y_TICKS = [0, 0.25, 0.5, 0.75, 1];

const formatMoney = (value: number) =>
  value.toLocaleString("en-US", { minimumFractionDigits: 0, maximumFractionDigits: 0 });

function formatDelta(delta: number) {
  const rounded = Math.round(delta * 10) / 10;
  return {
    label: `${rounded > 0 ? "+" : ""}${rounded}%`,
    color: rounded > 0 ? ("lime" as const) : rounded < 0 ? ("rose" as const) : ("neutral" as const),
  };
}

export function EarningsChartCard({
  className,
  title = "至今已赚到",
}: {
  className?: string;
  /** Headline label when no month is hovered. */
  title?: string;
} = {}) {
  const [period, setPeriod] = useState<Period>("monthly");
  const [activeIndex, setActiveIndex] = useState<number | null>(null);

  const data = PERIOD_DATA[period];
  const meta = PERIOD_META[period];
  const hovering = activeIndex !== null && activeIndex < data.length;
  const point = hovering ? data[activeIndex] : null;

  const headlineValue = point ? point.value : meta.total;
  const label = point ? point.label : title;
  const delta = formatDelta(meta.delta);
  const display = useCountUp(Math.round(headlineValue));
  const yMax = useMemo(() => Math.max(...data.map((d) => d.value)) * 1.1, [data]);

  return (
    <section
      className={cx(
        "flex flex-col gap-4 rounded-2xl bg-background-secondary-default p-4",
        className,
      )}
    >
      <div className="flex w-full flex-col gap-3 sm:flex-row sm:items-start sm:justify-between">
        <div className="flex min-w-0 flex-col gap-0.5">
          <p className="w-full text-body-medium text-text-secondary">{label}</p>
          <div className="flex w-full items-center gap-2">
            <p
              key={`${period}-${activeIndex ?? "total"}`}
              className="animate-number-fade text-title-1-medium whitespace-nowrap text-text-primary tabular-nums"
            >
              ${formatMoney(display)}
            </p>
            <Chip variant="bold" color={delta.color}>
              {delta.label}
            </Chip>
          </div>
        </div>

        <SegmentedControl
          aria-label="周期"
          selectedKeys={[period]}
          onSelectionChange={(keys) => {
            const next = [...(keys as Set<string>)][0] as Period | undefined;
            if (next) {
              setPeriod(next);
              setActiveIndex(null);
            }
          }}
          className="shrink-0 self-start"
        >
          <SegmentedControlItem id="weekly">每周</SegmentedControlItem>
          <SegmentedControlItem id="monthly">每月</SegmentedControlItem>
          <SegmentedControlItem id="yearly">每年</SegmentedControlItem>
        </SegmentedControl>
      </div>

      <div className="flex h-[220px] w-full min-w-0 gap-2">
        {/* Optional Y-axis style labels */}
        <div className="flex w-8 shrink-0 flex-col justify-between pb-6 pt-1" aria-hidden>
          {[...Y_TICKS].reverse().map((tick) => (
            <span key={tick} className="text-caption-1-medium text-text-tertiary tabular-nums">
              {tick === 0
                ? "0"
                : yMax >= 1000
                  ? `${Math.round((yMax * tick) / 1000)}k`
                  : Math.round(yMax * tick)}
            </span>
          ))}
        </div>

        <div className="flex min-w-0 flex-1 flex-col">
          <div className="flex min-h-0 flex-1 items-stretch gap-1.5 sm:gap-2">
            {data.map((item, index) => {
              const heightPct = Math.max(4, (item.value / yMax) * 100);
              const active = activeIndex === index;
              return (
                <button
                  key={item.label}
                  type="button"
                  aria-label={`${item.label} $${formatMoney(item.value)}`}
                  className="group relative flex min-w-0 flex-1 cursor-pointer flex-col justify-end outline-none"
                  onMouseEnter={() => setActiveIndex(index)}
                  onMouseLeave={() => setActiveIndex(null)}
                  onFocus={() => setActiveIndex(index)}
                  onBlur={() => setActiveIndex(null)}
                >
                  <div
                    className={cx(
                      "relative flex h-full w-full max-w-6 items-end justify-center self-center overflow-hidden rounded-full bg-chart-track transition-[box-shadow,opacity] duration-150",
                      active ? "ring-1 ring-chart-2-active shadow-xs" : "opacity-90 group-hover:opacity-100",
                    )}
                  >
                    <div
                      className={cx(
                        "w-full rounded-full transition-[height,background-color] duration-300 ease-out",
                        active ? "bg-chart-2-active" : "bg-chart-2",
                      )}
                      style={{ height: `${heightPct}%` }}
                    />
                  </div>
                </button>
              );
            })}
          </div>

          <div className="mt-2 flex gap-1.5 sm:gap-2" aria-hidden>
            {data.map((item) => (
              <span
                key={item.label}
                className="min-w-0 flex-1 text-center text-caption-1-medium text-text-tertiary"
              >
                {item.label}
              </span>
            ))}
          </div>
        </div>
      </div>
    </section>
  );
}

"use client";

import { useId, useState } from "react";

import { Chip } from "../../base/badges/chip";
import { useCountUp } from "@/hooks/use-count-up";
import { cx } from "@/lib/utils";

/**
 * Funnel Chart Card: a horizontal four-stage sign-up funnel drawn as SVG
 * trapezoids with a soft glow. Conversion % pills sit on each stage; the
 * footer lists absolute counts with matching color dots.
 */

export type FunnelStage = {
  label: string;
  value: number;
  /** Share of the funnel top, 0–100. */
  percent: number;
  /** CSS color for the trapezoid fill (chart token). */
  color: string;
  /** Tailwind bg utility for the footer dot. */
  dotClass: string;
};

export const FUNNEL_STAGES: FunnelStage[] = [
  {
    label: "链接已打开",
    value: 197,
    percent: 100,
    color: "var(--color-chart-7-active)",
    dotClass: "bg-chart-7-active",
  },
  {
    label: "开始",
    value: 110,
    percent: 56,
    color: "var(--color-chart-6-active)",
    dotClass: "bg-chart-6-active",
  },
  {
    label: "已完成",
    value: 77,
    percent: 39,
    color: "var(--color-chart-5-active)",
    dotClass: "bg-chart-5-active",
  },
  {
    label: "已转换",
    value: 38,
    percent: 19,
    color: "var(--color-chart-3-active)",
    dotClass: "bg-chart-3-active",
  },
];

const VIEW_W = 400;
const VIEW_H = 140;
const PAD_Y = 8;

function stageBand(percent: number) {
  const h = ((VIEW_H - PAD_Y * 2) * percent) / 100;
  const y0 = (VIEW_H - h) / 2;
  return { y0, y1: y0 + h };
}

function stagePath(index: number, stages: FunnelStage[]) {
  const n = stages.length;
  const w = VIEW_W / n;
  const left = stageBand(stages[index].percent);
  const right = stageBand(stages[Math.min(index + 1, n - 1)].percent);
  const x0 = index * w;
  const x1 = (index + 1) * w;
  // Last stage keeps a slight inward taper so it still reads as a funnel tip.
  const tip = index === n - 1 ? stageBand(Math.max(8, stages[index].percent * 0.72)) : right;
  return `M ${x0} ${left.y0} L ${x1} ${tip.y0} L ${x1} ${tip.y1} L ${x0} ${left.y1} Z`;
}

export function FunnelChartCard({
  stages = FUNNEL_STAGES,
  title = "Sign-up funnel",
  delta = "+5.2%",
  period = "过去 7 天",
  className,
}: {
  stages?: FunnelStage[];
  title?: string;
  delta?: string;
  period?: string;
  className?: string;
} = {}) {
  const glowId = useId();
  const [activeIndex, setActiveIndex] = useState<number | null>(null);

  const total = stages[0]?.value ?? 0;
  const hovering = activeIndex !== null && activeIndex < stages.length;
  const stage = hovering ? stages[activeIndex] : null;
  const headline = stage?.value ?? total;
  const label = stage?.label ?? title;
  const display = useCountUp(headline);

  return (
    <section
      className={cx(
        "flex h-[344px] min-w-0 flex-1 flex-col gap-4 rounded-2xl bg-background-secondary-default px-4 pt-4 pb-3",
        className,
      )}
    >
      <div className="flex w-full items-start justify-between gap-3">
        <div className="flex min-w-0 flex-col gap-0.5">
          <p className="w-full text-body-medium text-text-secondary">{label}</p>
          <div className="flex w-full items-center gap-2">
            <p
              key={activeIndex ?? "total"}
              className="animate-number-fade text-title-1-medium whitespace-nowrap text-text-primary tabular-nums"
            >
              {display.toLocaleString("en-US")}
            </p>
            <Chip variant="bold" color="lime">
              {delta}
            </Chip>
          </div>
        </div>
        <Chip variant="bold" color="soft" className="shrink-0">
          {period}
        </Chip>
      </div>

      <div className="relative min-h-0 w-full flex-1">
        <svg
          viewBox={`0 0 ${VIEW_W} ${VIEW_H}`}
          className="h-full w-full"
          role="img"
          aria-label={title}
        >
          <defs>
            <filter id={glowId} x="-20%" y="-40%" width="140%" height="180%">
              <feGaussianBlur in="SourceGraphic" stdDeviation="3.5" result="blur" />
              <feMerge>
                <feMergeNode in="blur" />
                <feMergeNode in="SourceGraphic" />
              </feMerge>
            </filter>
          </defs>
          {stages.map((s, i) => {
            const dimmed = activeIndex !== null && activeIndex !== i;
            return (
              <path
                key={s.label}
                d={stagePath(i, stages)}
                fill={s.color}
                opacity={dimmed ? 0.28 : 0.92}
                filter={`url(#${glowId})`}
                className="cursor-pointer transition-opacity duration-200 ease"
                onMouseEnter={() => setActiveIndex(i)}
                onMouseLeave={() => setActiveIndex(null)}
              />
            );
          })}
        </svg>

        <div className="pointer-events-none absolute inset-0 grid grid-cols-4">
          {stages.map((s, i) => (
            <div key={s.label} className="flex items-center justify-center">
              <span
                className={cx(
                  "rounded-full bg-background-secondary-default/90 px-2 py-0.5 text-caption-1-medium text-text-primary tabular-nums shadow-card backdrop-blur-sm transition-opacity duration-200 ease",
                  activeIndex !== null && activeIndex !== i && "opacity-40",
                )}
              >
                {s.percent}%
              </span>
            </div>
          ))}
        </div>
      </div>

      <div className="grid grid-cols-4 gap-2 border-t border-separator-border pt-3">
        {stages.map((s, i) => (
          <button
            key={s.label}
            type="button"
            className={cx(
              "flex min-w-0 flex-col items-start gap-1 rounded-lg px-1 py-0.5 text-start outline-none transition-opacity duration-150 ease focus-visible:ring-2 focus-visible:ring-border-focus-ring",
              activeIndex !== null && activeIndex !== i && "opacity-40",
            )}
            onMouseEnter={() => setActiveIndex(i)}
            onMouseLeave={() => setActiveIndex(null)}
          >
            <span className="flex items-center gap-1.5">
              <span className={cx("size-2 shrink-0 rounded-full", s.dotClass)} aria-hidden />
              <span className="truncate text-caption-1-medium text-text-tertiary">{s.label}</span>
            </span>
            <span className="ps-3.5 text-body-medium text-text-primary tabular-nums">
              {s.value.toLocaleString("en-US")}
            </span>
          </button>
        ))}
      </div>
    </section>
  );
}

"use client";

import { useMemo, useState } from "react";

import { Chip } from "../../base/badges/chip";
import { useCountUp } from "@/hooks/use-count-up";
import { cx } from "@/lib/utils";

/**
 * Heatmap Chart Card: weekday × hour matrix as a pure CSS grid. Cell tint
 * blends chart-blue into the chart track so the ramp follows the theme;
 * hovering a cell rings it and swaps the headline for that cell's value.
 */

export type HeatmapRow = {
  label: string;
  values: number[];
};

export const HEATMAP_COLUMNS = ["00", "02", "04", "06", "08", "10", "12", "14", "16", "18", "20", "22"];

/** Demo active-user intensity for Mon–Sun × bi-hourly slots. */
export const HEATMAP_ROWS: HeatmapRow[] = [
  { label: "周一", values: [12, 8, 4, 6, 28, 52, 68, 74, 81, 76, 58, 34] },
  { label: "周二", values: [14, 9, 5, 7, 31, 55, 72, 78, 84, 79, 61, 36] },
  { label: "周三", values: [11, 7, 3, 8, 33, 58, 75, 82, 88, 80, 63, 38] },
  { label: "周四", values: [13, 8, 4, 9, 30, 54, 71, 77, 85, 78, 60, 35] },
  { label: "周五", values: [15, 10, 6, 10, 36, 62, 79, 86, 90, 83, 66, 42] },
  { label: "周六", values: [22, 14, 9, 12, 24, 40, 48, 52, 55, 58, 49, 31] },
  { label: "周日", values: [18, 12, 8, 10, 20, 34, 42, 46, 50, 52, 44, 28] },
];

const TIER_CLASSES = [
  "bg-chart-track",
  "bg-chart-6/25",
  "bg-chart-6/45",
  "bg-chart-6/65",
  "bg-chart-6-active/85",
  "bg-chart-6-active",
] as const;

function tierFor(value: number, max: number) {
  if (value <= 0 || max <= 0) return 0;
  const t = value / max;
  if (t < 0.15) return 1;
  if (t < 0.35) return 2;
  if (t < 0.55) return 3;
  if (t < 0.75) return 4;
  return 5;
}

export function HeatmapChartCard({
  rows = HEATMAP_ROWS,
  columns = HEATMAP_COLUMNS,
  title = "Active users",
  headline = 1892,
  delta = "+5.2%",
  period = "过去 7 天",
  className,
}: {
  rows?: HeatmapRow[];
  columns?: string[];
  title?: string;
  headline?: number;
  delta?: string;
  period?: string;
  className?: string;
} = {}) {
  const [hover, setHover] = useState<{ row: number; col: number } | null>(null);

  const max = useMemo(
    () => Math.max(1, ...rows.flatMap((row) => row.values)),
    [rows],
  );

  const cellValue =
    hover && rows[hover.row] ? (rows[hover.row].values[hover.col] ?? 0) : null;
  const label =
    hover && rows[hover.row]
      ? `${rows[hover.row].label} · ${columns[hover.col] ?? ""}:00`
      : title;
  const display = useCountUp(cellValue ?? headline);

  return (
    <section
      className={cx(
        "flex h-[344px] min-w-0 flex-1 flex-col gap-4 rounded-2xl bg-background-secondary-default px-4 pt-4 pb-3",
        className,
      )}
    >
      <div className="flex w-full items-start justify-between gap-3">
        <div className="flex min-w-0 flex-col gap-0.5">
          <p className="w-full text-body-medium text-text-secondary">{label}</p>
          <div className="flex w-full items-center gap-2">
            <p
              key={hover ? `${hover.row}-${hover.col}` : "total"}
              className="animate-number-fade text-title-1-medium whitespace-nowrap text-text-primary tabular-nums"
            >
              {display.toLocaleString("en-US")}
            </p>
            <Chip variant="bold" color="lime">
              {delta}
            </Chip>
          </div>
        </div>
        <Chip variant="bold" color="soft" className="shrink-0">
          {period}
        </Chip>
      </div>

      <div className="flex min-h-0 w-full flex-1 flex-col gap-2">
        <div
          className="grid min-h-0 flex-1 gap-1"
          style={{
            gridTemplateColumns: `auto repeat(${columns.length}, minmax(0, 1fr))`,
            gridTemplateRows: `repeat(${rows.length}, minmax(0, 1fr))`,
          }}
        >
          {rows.map((row, ri) => (
            <div key={row.label} className="contents">
              <span className="flex items-center pe-2 text-caption-1-medium text-text-tertiary">
                {row.label}
              </span>
              {row.values.map((value, ci) => {
                const active = hover?.row === ri && hover?.col === ci;
                const dimmed = hover !== null && !active;
                return (
                  <button
                    key={`${row.label}-${columns[ci]}`}
                    type="button"
                    aria-label={`${row.label} ${columns[ci]}:00, ${value}`}
                    className={cx(
                      "min-h-0 min-w-0 rounded-sm outline-none transition-[opacity,box-shadow] duration-150 ease focus-visible:ring-2 focus-visible:ring-border-focus-ring",
                      TIER_CLASSES[tierFor(value, max)],
                      active && "ring-2 ring-border-focus-ring ring-offset-1 ring-offset-background-secondary-default",
                      dimmed && "opacity-35",
                    )}
                    onMouseEnter={() => setHover({ row: ri, col: ci })}
                    onMouseLeave={() => setHover(null)}
                    onFocus={() => setHover({ row: ri, col: ci })}
                    onBlur={() => setHover(null)}
                  />
                );
              })}
            </div>
          ))}
        </div>

        <div
          className="grid gap-1"
          style={{ gridTemplateColumns: `auto repeat(${columns.length}, minmax(0, 1fr))` }}
        >
          <span aria-hidden className="pe-2" />
          {columns.map((col) => (
            <span
              key={col}
              className="text-center text-caption-1-medium text-text-tertiary tabular-nums"
            >
              {col}
            </span>
          ))}
        </div>
      </div>

      <div className="flex items-center justify-end gap-2 text-caption-1-medium text-text-tertiary">
        <span>少</span>
        <div className="flex items-center gap-1">
          {TIER_CLASSES.slice(1).map((cls) => (
            <span key={cls} className={cx("size-2.5 rounded-sm", cls)} aria-hidden />
          ))}
        </div>
        <span>更多</span>
      </div>
    </section>
  );
}

"use client";

import { useId, useMemo, useState } from "react";
import { Area, ComposedChart, Line, ResponsiveContainer, Tooltip, XAxis, YAxis } from "recharts";

import { Chip } from "../../base/badges/chip";
import {
  SegmentedControl,
  SegmentedControlItem,
} from "../../base/segmented-control/segmented-control";
import { useCountUp } from "@/hooks/use-count-up";
import { cx } from "@/lib/utils";

/**
 * Line Chart Card: a lime area + monotone line with a period switcher.
 * Hovering a month swaps the count-up headline; the active point pulses.
 */

type Period = "weekly" | "monthly" | "yearly";

export type LineChartPoint = {
  label: string;
  value: number;
};

const MONTHS = ["1月", "2月", "3月", "4月", "5月", "6月", "7月", "8月", "9月", "10月", "11月", "12月"];

const PERIOD_META: Record<Period, { total: number; delta: number }> = {
  weekly: { total: 4120, delta: 6.2 },
  monthly: { total: 18240, delta: 9.4 },
  yearly: { total: 214880, delta: 12.1 },
};

const PERIOD_DATA: Record<Period, LineChartPoint[]> = {
  weekly: [
    { label: "1月", value: 280 },
    { label: "2月", value: 310 },
    { label: "3月", value: 295 },
    { label: "4月", value: 340 },
    { label: "5月", value: 360 },
    { label: "6月", value: 355 },
    { label: "7月", value: 390 },
    { label: "8月", value: 375 },
    { label: "9月", value: 410 },
    { label: "10月", value: 430 },
    { label: "11月", value: 405 },
    { label: "12月", value: 370 },
  ],
  monthly: [
    { label: "1月", value: 1240 },
    { label: "2月", value: 1380 },
    { label: "3月", value: 1320 },
    { label: "4月", value: 1490 },
    { label: "5月", value: 1580 },
    { label: "6月", value: 1510 },
    { label: "7月", value: 1720 },
    { label: "8月", value: 1650 },
    { label: "9月", value: 1780 },
    { label: "10月", value: 1860 },
    { label: "11月", value: 1740 },
    { label: "12月", value: 1970 },
  ],
  yearly: [
    { label: "1月", value: 14880 },
    { label: "2月", value: 15620 },
    { label: "3月", value: 16240 },
    { label: "4月", value: 17100 },
    { label: "5月", value: 17840 },
    { label: "6月", value: 18220 },
    { label: "7月", value: 19160 },
    { label: "8月", value: 18640 },
    { label: "9月", value: 19480 },
    { label: "10月", value: 20120 },
    { label: "11月", value: 18840 },
    { label: "12月", value: 18740 },
  ],
};

const formatMoney = (value: number) =>
  value.toLocaleString("en-US", { minimumFractionDigits: 0, maximumFractionDigits: 0 });

const formatK = (value: number) => {
  if (value >= 1000) {
    const k = value / 1000;
    return `$${Number.isInteger(k) ? k : k.toFixed(1)}k`;
  }
  return `$${Math.round(value)}`;
};

function formatDelta(delta: number) {
  const rounded = Math.round(delta * 10) / 10;
  return {
    label: `${rounded > 0 ? "+" : ""}${rounded}%`,
    color: rounded > 0 ? ("lime" as const) : rounded < 0 ? ("rose" as const) : ("neutral" as const),
  };
}

/** Pulsing marker on the active line point. */
function ActiveDot({ cx: x, cy: y }: { cx?: number; cy?: number }) {
  if (x === undefined || y === undefined) return null;
  return (
    <g>
      <circle cx={x} cy={y} r={10} fill="var(--color-chart-2-active)" opacity={0.22}>
        <animate attributeName="r" values="7;12;7" dur="1.25s" repeatCount="indefinite" />
        <animate attributeName="opacity" values="0.32;0.08;0.32" dur="1.25s" repeatCount="indefinite" />
      </circle>
      <circle
        cx={x}
        cy={y}
        r={4}
        fill="var(--color-chart-2-active)"
        stroke="var(--color-background-secondary-default)"
        strokeWidth={2}
      />
    </g>
  );
}

export function LineChartCard({
  className,
  title = "收入",
}: {
  className?: string;
  /** Headline label when no month is hovered. */
  title?: string;
} = {}) {
  const [period, setPeriod] = useState<Period>("monthly");
  const [activeIndex, setActiveIndex] = useState<number | null>(null);
  const gradientId = useId();

  const data = PERIOD_DATA[period];
  const meta = PERIOD_META[period];
  const hovering = activeIndex !== null && activeIndex < data.length;
  const point = hovering ? data[activeIndex] : null;

  const headlineValue = point ? point.value : meta.total;
  const label = point ? point.label : title;
  const delta = formatDelta(meta.delta);
  const display = useCountUp(Math.round(headlineValue));
  const yMax = useMemo(() => Math.max(...data.map((d) => d.value)), [data]);

  return (
    <section
      className={cx(
        "flex flex-col gap-4 rounded-2xl bg-background-secondary-default p-4",
        className,
      )}
    >
      <div className="flex w-full flex-col gap-3 sm:flex-row sm:items-start sm:justify-between">
        <div className="flex min-w-0 flex-col gap-0.5">
          <p className="w-full text-body-medium text-text-secondary">{label}</p>
          <div className="flex w-full items-center gap-2">
            <p
              key={`${period}-${activeIndex ?? "total"}`}
              className="animate-number-fade text-title-1-medium whitespace-nowrap text-text-primary tabular-nums"
            >
              ${formatMoney(display)}
            </p>
            <Chip variant="bold" color={delta.color}>
              {delta.label}
            </Chip>
          </div>
        </div>

        <SegmentedControl
          aria-label="周期"
          selectedKeys={[period]}
          onSelectionChange={(keys) => {
            const next = [...(keys as Set<string>)][0] as Period | undefined;
            if (next) {
              setPeriod(next);
              setActiveIndex(null);
            }
          }}
          className="shrink-0 self-start"
        >
          <SegmentedControlItem id="weekly">每周</SegmentedControlItem>
          <SegmentedControlItem id="monthly">每月</SegmentedControlItem>
          <SegmentedControlItem id="yearly">每年</SegmentedControlItem>
        </SegmentedControl>
      </div>

      <div className="h-[220px] w-full min-w-0">
        <ResponsiveContainer width="100%" height="100%">
          <ComposedChart
            data={data}
            margin={{ top: 8, right: 6, bottom: 0, left: 0 }}
            onMouseMove={(state) => {
              const index = Number(state?.activeTooltipIndex);
              if (state?.isTooltipActive && Number.isFinite(index)) setActiveIndex(index);
            }}
            onMouseLeave={() => setActiveIndex(null)}
          >
            <defs>
              <linearGradient id={gradientId} x1="0" y1="0" x2="0" y2="1">
                <stop offset="0%" stopColor="var(--color-chart-2)" stopOpacity={0.35} />
                <stop offset="100%" stopColor="var(--color-chart-2)" stopOpacity={0} />
              </linearGradient>
            </defs>
            <YAxis
              width={44}
              domain={[0, yMax * 1.15]}
              tickCount={4}
              tickFormatter={formatK}
              tickLine={false}
              axisLine={false}
              tick={{ fontSize: 12, fill: "var(--color-text-tertiary)" }}
            />
            <XAxis
              dataKey="label"
              ticks={MONTHS}
              tickLine={false}
              axisLine={false}
              tickMargin={12}
              interval="preserveStartEnd"
              tick={{ fontSize: 13, fill: "var(--color-text-tertiary)" }}
            />
            <Tooltip
              content={() => null}
              cursor={{ stroke: "var(--color-chart-cursor)", strokeWidth: 1, strokeDasharray: "4 4" }}
            />
            <Area
              type="monotone"
              dataKey="value"
              stroke="none"
              fill={`url(#${gradientId})`}
              isAnimationActive
              animationDuration={450}
            />
            <Line
              type="monotone"
              dataKey="value"
              stroke="var(--color-chart-2-active)"
              strokeWidth={2.5}
              dot={false}
              activeDot={<ActiveDot />}
              isAnimationActive
              animationDuration={450}
            />
          </ComposedChart>
        </ResponsiveContainer>
      </div>
    </section>
  );
}

"use client";

import { useMemo, useState } from "react";
import { RiArrowLeftSLine, RiArrowRightSLine } from "@remixicon/react";
import { cx } from "@/lib/utils";

type DayMetrics = { move: number; exercise: number; stand: number };

const DEMO_MONTH = 6; // July (0-indexed)
const DEMO_YEAR = 2026;

function metricsForDay(day: number): DayMetrics {
  const move = 40 + ((day * 17) % 60);
  const exercise = 35 + ((day * 13) % 55);
  const stand = 45 + ((day * 11) % 50);
  return { move, exercise, stand };
}

function MiniRings({ m, size = 22 }: { m: DayMetrics; size?: number }) {
  const r = [size * 0.42, size * 0.3, size * 0.18];
  const colors = ["#FF2D55", "#A3E635", "#22D3EE"];
  const values = [m.move, m.exercise, m.stand];
  return (
    <svg width={size} height={size} viewBox={`0 0 ${size} ${size}`} aria-hidden>
      {r.map((radius, i) => {
        const c = 2 * Math.PI * radius;
        const pct = Math.min(100, values[i]) / 100;
        return (
          <g key={i}>
            <circle
              cx={size / 2}
              cy={size / 2}
              r={radius}
              fill="none"
              stroke="var(--color-background-tertiary-default)"
              strokeWidth={size * 0.08}
            />
            <circle
              cx={size / 2}
              cy={size / 2}
              r={radius}
              fill="none"
              stroke={colors[i]}
              strokeWidth={size * 0.08}
              strokeLinecap="round"
              strokeDasharray={c}
              strokeDashoffset={c * (1 - pct)}
              transform={`rotate(-90 ${size / 2} ${size / 2})`}
            />
          </g>
        );
      })}
    </svg>
  );
}

function LargeRings({ m }: { m: DayMetrics }) {
  const size = 168;
  const r = [72, 52, 32];
  const colors = ["#FF2D55", "#A3E635", "#22D3EE"];
  const values = [m.move, m.exercise, m.stand];
  return (
    <svg width={size} height={size} viewBox={`0 0 ${size} ${size}`} className="mx-auto">
      {r.map((radius, i) => {
        const c = 2 * Math.PI * radius;
        const pct = Math.min(100, values[i]) / 100;
        return (
          <g key={i}>
            <circle
              cx={size / 2}
              cy={size / 2}
              r={radius}
              fill="none"
              stroke="var(--color-background-tertiary-default)"
              strokeWidth={14}
              opacity={0.85}
            />
            <circle
              cx={size / 2}
              cy={size / 2}
              r={radius}
              fill="none"
              stroke={colors[i]}
              strokeWidth={14}
              strokeLinecap="round"
              strokeDasharray={c}
              strokeDashoffset={c * (1 - pct)}
              transform={`rotate(-90 ${size / 2} ${size / 2})`}
              style={{ filter: `drop-shadow(0 0 6px ${colors[i]}66)` }}
            />
          </g>
        );
      })}
    </svg>
  );
}

/**
 * Most Active Days — scrollable month calendar with per-day mini rings and a
 * detail panel for the selected day.
 */
export function MostActiveDaysCard({ className }: { className?: string }) {
  const [selected, setSelected] = useState(10);
  const daysInMonth = 31;
  const startWeekday = new Date(DEMO_YEAR, DEMO_MONTH, 1).getDay(); // 0=Sun
  const selectedMetrics = useMemo(() => metricsForDay(selected), [selected]);

  const cells = useMemo(() => {
    const blanks = Array.from({ length: startWeekday }, () => null);
    const days = Array.from({ length: daysInMonth }, (_, i) => i + 1);
    return [...blanks, ...days];
  }, [startWeekday]);

  return (
    <section
      className={cx(
        "grid w-full min-w-0 gap-3 rounded-2xl bg-background-secondary-default p-3 sm:grid-cols-2 sm:p-4",
        className,
      )}
    >
      <div className="flex flex-col gap-3 rounded-2xl bg-background-primary-default p-3">
        <div className="flex items-start justify-between gap-2">
          <div>
            <p className="text-body-medium text-text-secondary">最活跃的日子</p>
            <p className="mt-0.5 text-title-3-semibold text-text-primary">
              32,459{" "}
              <span className="text-body-medium text-text-tertiary">总步数</span>
            </p>
          </div>
          <div className="inline-flex items-center gap-1 rounded-full border border-border-button-default px-1 py-0.5">
            <button
              type="button"
              aria-label="上一月"
              className="flex size-6 items-center justify-center rounded-full text-foreground-icon-secondary hover:bg-background-secondary-default"
            >
              <RiArrowLeftSLine className="size-4" />
            </button>
            <span className="min-w-10 text-center text-body-2-medium text-text-primary">
              7月
            </span>
            <button
              type="button"
              aria-label="下一月"
              className="flex size-6 items-center justify-center rounded-full text-foreground-icon-secondary hover:bg-background-secondary-default"
            >
              <RiArrowRightSLine className="size-4" />
            </button>
          </div>
        </div>

        <div className="grid grid-cols-7 gap-1 text-center text-caption-1-medium text-text-tertiary">
          {["日", "一", "二", "三", "四", "五", "六"].map((d) => (
            <span key={d}>{d}</span>
          ))}
        </div>

        <div className="grid max-h-[280px] grid-cols-7 gap-1 overflow-y-auto pe-1 [scrollbar-width:thin]">
          {cells.map((day, i) =>
            day === null ? (
              <div key={`b-${i}`} className="h-12" />
            ) : (
              <button
                key={day}
                type="button"
                onClick={() => setSelected(day)}
                className={cx(
                  "flex h-12 flex-col items-center justify-center gap-0.5 rounded-xl outline-none transition-colors",
                  selected === day
                    ? "bg-background-secondary-hover ring-1 ring-border-button-default"
                    : "hover:bg-background-secondary-default",
                )}
              >
                <span className="text-caption-1-medium text-text-secondary">
                  {day}
                </span>
                <MiniRings m={metricsForDay(day)} />
              </button>
            ),
          )}
        </div>
      </div>

      <div className="flex flex-col gap-4 rounded-2xl bg-background-primary-default p-4">
        <p className="text-body-medium text-text-secondary">
          July {selected}, {DEMO_YEAR} 的活动
        </p>
        <div className="flex flex-wrap gap-2">
          <span className="inline-flex items-center gap-1.5 rounded-full bg-rose-50 px-2.5 py-1 text-body-2-medium text-rose-600 dark:bg-rose-950/40 dark:text-rose-300">
            Move · 816 kcal
          </span>
          <span className="inline-flex items-center gap-1.5 rounded-full bg-lime-50 px-2.5 py-1 text-body-2-medium text-lime-700 dark:bg-lime-950/40 dark:text-lime-300">
            Exercise · 1h 41m
          </span>
          <span className="inline-flex items-center gap-1.5 rounded-full bg-cyan-50 px-2.5 py-1 text-body-2-medium text-cyan-700 dark:bg-cyan-950/40 dark:text-cyan-300">
            Stand · 5.2 km
          </span>
        </div>
        <LargeRings m={selectedMetrics} />
      </div>
    </section>
  );
}

"use client";

import { useState } from "react";
import { Bar, BarChart, ResponsiveContainer, Tooltip, XAxis, YAxis } from "recharts";

import { Chip } from "../../base/badges/chip";
import { useCountUp } from "@/hooks/use-count-up";
import { cx } from "@/lib/utils";

/**
 * Orders Chart Card: a year of monthly orders as bars, this year beside last
 * year for every month, so the comparison is read bar to bar rather than
 * against a line. The header is the same as the revenue chart's: a count-up
 * total with a delta chip, the year-earlier figure under it, and a legend.
 * Hovering a month swaps the headline for that month.
 */

const MONTHS = ["Jan", "Feb", "Mar", "Apr", "May", "Jun", "Jul", "Aug", "Sep", "Oct", "Nov", "Dec"];
const MONTHS_FULL = [
  "January",
  "February",
  "March",
  "April",
  "May",
  "June",
  "July",
  "August",
  "September",
  "October",
  "November",
  "December",
];

export type OrdersPoint = {
  /** Short month label on the axis. */
  label: string;
  /** Orders this year. */
  current: number;
  /** Orders in the same month a year earlier. */
  previous: number;
};

/** Twelve months that add up to the stat cards' total orders. */
export const ORDERS_DATA: OrdersPoint[] = [
  { label: "Jan", current: 1680, previous: 1510 },
  { label: "Feb", current: 1740, previous: 1480 },
  { label: "Mar", current: 1920, previous: 1650 },
  { label: "Apr", current: 1850, previous: 1620 },
  { label: "May", current: 2040, previous: 1710 },
  { label: "Jun", current: 2110, previous: 1760 },
  { label: "Jul", current: 2290, previous: 1840 },
  { label: "Aug", current: 2180, previous: 1890 },
  { label: "Sep", current: 2320, previous: 1930 },
  { label: "Oct", current: 2410, previous: 1970 },
  { label: "Nov", current: 2280, previous: 1810 },
  { label: "Dec", current: 2342, previous: 1798 },
];

const formatK = (value: number) => (value >= 1000 ? `${(value / 1000).toFixed(value % 1000 === 0 ? 0 : 1)}k` : `${value}`);

function describeDelta(current: number, previous: number) {
  if (previous === 0) return { label: "New", color: "neutral" as const };
  const change = ((current - previous) / previous) * 100;
  const rounded = Math.round(change * 10) / 10;
  if (rounded === 0) return { label: "0%", color: "neutral" as const };
  return {
    label: `${rounded > 0 ? "+" : ""}${rounded}%`,
    color: rounded > 0 ? ("lime" as const) : ("rose" as const),
  };
}

