"use client";

import type { ReactNode } from "react";
import { Modal as AriaModal, ModalOverlay as AriaModalOverlay } from "react-aria-components";
import type { DialogRenderProps, ModalOverlayProps } from "react-aria-components";
import {
  ModalBody,
  ModalDialog,
  ModalFooter,
  ModalHeader,
  ModalTrigger,
} from "../modal/modal";
import { useDirection } from "../../foundations/direction/direction";
import { cx, sortCx } from "@/lib/utils";

/**
 * Drawer — a panel that slides in from an edge of the screen over a dimmed
 * page. It is Modal's sibling on the same React Aria ModalOverlay, so focus
 * is trapped and returns to the trigger, the page stops scrolling, and
 * Escape or a press on the backdrop closes it. The header, body, footer,
 * and trigger are Modal's, re-exported under Drawer names.
 *
 *   <DrawerTrigger>
 *     <Button>Filters</Button>
 *     <Drawer placement="end">
 *       {({ close }) => (
 *         <>
 *           <DrawerHeader title="Filters" />
 *           <DrawerBody>…</DrawerBody>
 *           <DrawerFooter>…</DrawerFooter>
 *         </>
 *       )}
 *     </Drawer>
 *   </DrawerTrigger>
 *
 * The panel floats 12px inside the viewport (8px on phones) at radius/3xl,
 * the same surface as Modal and the floating sidebar. `start` and `end`
 * follow the reading direction, so an end drawer opens from the left in RTL.
 *
 * Motion: the panel slides in from past its edge and sharpens from a 4px
 * blur over 300ms on the iOS sheet curve (Modal's timing), and slides back
 * out the same way; the black/40 backdrop fades with it. Reduced motion
 * swaps the slide for a fade.
 */

export type DrawerPlacement = "start" | "end" | "top" | "bottom";
export type DrawerSize = "sm" | "md" | "lg";

const styles = sortCx({
  overlay: "group/drawer fixed inset-x-0 top-0 z-100 flex h-(--visual-viewport-height) p-2 sm:p-3",
  backdrop: [
    "absolute inset-0 bg-black/40",
    "transition-opacity duration-300 ease-out",
    "group-data-[entering]/drawer:opacity-0 group-data-[exiting]/drawer:opacity-0",
  ].join(" "),
  modal: [
    "relative flex w-full flex-col outline-none",
    "transform-gpu transition-[translate,filter,opacity] duration-300 ease-[cubic-bezier(0.32,0.72,0,1)]",
    "motion-safe:data-[entering]:blur-[4px] motion-safe:data-[exiting]:blur-[4px]",
    "motion-reduce:data-[entering]:opacity-0 motion-reduce:data-[exiting]:opacity-0",
  ].join(" "),
  dialog: "flex-1",
  // Each panel starts 24px past its edge (the 12px inset plus its shadow),
  // so no sliver of it shows before it moves. Literal per edge and direction
  // so Tailwind can see every class.
  placement: {
    end: {
      overlay: "justify-end",
      modal: [
        "h-full",
        "motion-safe:ltr:data-[entering]:translate-x-[calc(100%+24px)] motion-safe:ltr:data-[exiting]:translate-x-[calc(100%+24px)]",
        "motion-safe:rtl:data-[entering]:-translate-x-[calc(100%+24px)] motion-safe:rtl:data-[exiting]:-translate-x-[calc(100%+24px)]",
      ].join(" "),
    },
    start: {
      overlay: "justify-start",
      modal: [
        "h-full",
        "motion-safe:ltr:data-[entering]:-translate-x-[calc(100%+24px)] motion-safe:ltr:data-[exiting]:-translate-x-[calc(100%+24px)]",
        "motion-safe:rtl:data-[entering]:translate-x-[calc(100%+24px)] motion-safe:rtl:data-[exiting]:translate-x-[calc(100%+24px)]",
      ].join(" "),
    },
    bottom: {
      overlay: "items-end",
      modal: "max-h-[85%] motion-safe:data-[entering]:translate-y-[calc(100%+24px)] motion-safe:data-[exiting]:translate-y-[calc(100%+24px)]",
    },
    top: {
      overlay: "items-start",
      modal: "max-h-[85%] motion-safe:data-[entering]:-translate-y-[calc(100%+24px)] motion-safe:data-[exiting]:-translate-y-[calc(100%+24px)]",
    },
  },
  // Side drawers only; top and bottom drawers span the screen.
  size: {
    sm: "max-w-[320px]",
    md: "max-w-[400px]",
    lg: "max-w-[600px]",
  },
});

export interface DrawerProps extends Omit<ModalOverlayProps, "children" | "className" | "style"> {
  /** The edge the panel slides in from. `start` and `end` follow the reading direction. */
  placement?: DrawerPlacement;
  /** Width of a start or end drawer: 320, 400 (default), or 600px. */
  size?: DrawerSize;
  /** Accessible name when the content has no DrawerHeader title. */
  "aria-label"?: string;
  /** Classes on the panel surface. */
  className?: string;
  /** Classes on the full-screen overlay. */
  overlayClassName?: string;
  children: ReactNode | ((renderProps: DialogRenderProps) => ReactNode);
}

export function Drawer({
  placement = "end",
  size = "md",
  "aria-label": ariaLabel,
  className,
  overlayClassName,
  isDismissable = true,
  children,
  ...props
}: DrawerProps) {
  const direction = useDirection();
  const edge = styles.placement[placement];
  const side = placement === "start" || placement === "end";

  return (
    <AriaModalOverlay
      {...props}
      dir={direction}
      isDismissable={isDismissable}
      className={cx(styles.overlay, edge.overlay, overlayClassName)}
    >
      <div aria-hidden className={styles.backdrop} />
      <AriaModal className={cx(styles.modal, edge.modal, side && styles.size[size])}>
        <ModalDialog aria-label={ariaLabel} className={cx(styles.dialog, className)}>
          {children}
        </ModalDialog>
      </AriaModal>
    </AriaModalOverlay>
  );
}

export {
  ModalBody as DrawerBody,
  ModalFooter as DrawerFooter,
  ModalHeader as DrawerHeader,
  ModalTrigger as DrawerTrigger,
};
export type {
  ModalBodyProps as DrawerBodyProps,
  ModalHeaderProps as DrawerHeaderProps,
  ModalTriggerProps as DrawerTriggerProps,
} from "../modal/modal";

"use client";

import { useState, type ReactNode } from "react";
import type { DialogRenderProps } from "react-aria-components";
import { Button } from "../buttons/button";
import {
  Drawer,
  DrawerBody,
  DrawerFooter,
  DrawerHeader,
  DrawerTrigger,
  type DrawerPlacement,
  type DrawerProps,
  type DrawerSize,
} from "../drawer/drawer";
import { SpinnerGlyph } from "../spinner/spinner";
import { cx } from "@/lib/utils";

/**
 * DrawerForm — side drawer preset for edit flows: sticky header, scrollable
 * body, sticky footer with 取消 / 保存. Reuses Drawer's placement motion and
 * Modal's header / body / footer scroll-fade behaviour.
 *
 *   <DrawerFormTrigger>
 *     <Button>编辑资料</Button>
 *     <DrawerForm
 *       title="编辑资料"
 *       description="保存后立即生效。"
 *       onSave={async () => { await api.save(); }}
 *     >
 *       <Input label="显示名" />
 *     </DrawerForm>
 *   </DrawerFormTrigger>
 */

export type DrawerFormPlacement = Extract<DrawerPlacement, "start" | "end">;

export interface DrawerFormRenderProps extends DialogRenderProps {
  /** True while an async `onSave` is in flight. */
  pending: boolean;
}

export interface DrawerFormProps
  extends Omit<DrawerProps, "children" | "placement" | "size" | "aria-label"> {
  title: ReactNode;
  description?: ReactNode;
  /** Side edge. Default `end`. */
  placement?: DrawerFormPlacement;
  /** Width: 320 / 400 / 600. Default `md`. */
  size?: DrawerSize;
  cancelLabel?: ReactNode;
  saveLabel?: ReactNode;
  /** Label on the save button while `onSave` is pending. */
  pendingLabel?: ReactNode;
  /** Runs on save. Return a promise to keep the drawer open until it settles. */
  onSave?: () => void | Promise<unknown>;
  onCancel?: () => void;
  /** Disable the save action (e.g. until the form is valid). */
  isSaveDisabled?: boolean;
  /** Accessible name when `title` is not a string. */
  "aria-label"?: string;
  className?: string;
  children: ReactNode | ((renderProps: DrawerFormRenderProps) => ReactNode);
}

function PendingGlyph({ className }: { className?: string }) {
  return <SpinnerGlyph size="sm" className={cx(className, "text-current")} />;
}

export function DrawerForm({
  title,
  description,
  placement = "end",
  size = "md",
  cancelLabel = "取消",
  saveLabel = "保存",
  pendingLabel,
  onSave,
  onCancel,
  isSaveDisabled = false,
  "aria-label": ariaLabel,
  className,
  children,
  ...props
}: DrawerFormProps) {
  const [pending, setPending] = useState(false);

  return (
    <Drawer
      {...props}
      placement={placement}
      size={size}
      aria-label={ariaLabel}
      isDismissable={props.isDismissable !== false && !pending}
      isKeyboardDismissDisabled={pending || props.isKeyboardDismissDisabled}
      className={className}
    >
      {(renderProps) => {
        const { close } = renderProps;

        const save = async () => {
          if (pending) return;
          const result = onSave?.();
          if (!result || typeof result.then !== "function") {
            close();
            return;
          }
          setPending(true);
          try {
            await result;
            close();
          } catch {
            // Stay open: the caller reports the failure.
          } finally {
            setPending(false);
          }
        };

        return (
          <>
            <DrawerHeader title={title} description={description} />
            <DrawerBody>
              {typeof children === "function"
                ? children({ ...renderProps, pending })
                : children}
            </DrawerBody>
            <DrawerFooter>
              <Button
                variant="secondary"
                disabled={pending}
                onClick={() => {
                  onCancel?.();
                  close();
                }}
              >
                {cancelLabel}
              </Button>
              <Button
                variant="primary"
                disabled={isSaveDisabled}
                aria-busy={pending || undefined}
                leadingIcon={pending ? PendingGlyph : undefined}
                onClick={save}
              >
                {pending && pendingLabel ? pendingLabel : saveLabel}
              </Button>
            </DrawerFooter>
          </>
        );
      }}
    </Drawer>
  );
}

export { DrawerTrigger as DrawerFormTrigger };
export type { DrawerTriggerProps as DrawerFormTriggerProps } from "../drawer/drawer";

"use client";

import { createContext, useContext, useRef, useState, type ComponentProps, type ReactNode, type RefObject } from "react";
import {
  Button as AriaButton,
  Dialog as AriaDialog,
  DialogTrigger as AriaDialogTrigger,
  Popover as AriaPopover,
} from "react-aria-components";
import {
  MENU_ITEM,
  MENU_ITEM_ACTIVE,
  MENU_ITEM_INTERACTIVE,
  MENU_POPOVER_SURFACE,
  MENU_POPOVER_WIDTH,
} from "./menu-styles";
import { cx } from "@/lib/utils";
import { useDismissOnOutsidePress, useTriggerToggle } from "@/lib/use-dismiss-on-outside-press";

/**
 * Dropdown — the JoyUI popover-menu recipe as composable primitives, built
 * on React Aria's DialogTrigger/Popover. Unlike Select (which picks a value
 * into a trigger), Dropdown is a free-form menu surface: grouped rows of
 * actions, headers, footers, whatever the panel needs.
 *
 * The same recipe powers the dashboard sidebar's team/account menus and the
 * AI chat template's add/model/folder menus:
 *
 * - Panel: white, 1px border/button/default, radius 16, p 10, shadow/dropdown.
 * - Appear animation: 150ms fade + scale-95 + 2px blur in and out.
 * - Rows: rounded-2lg, background/secondary/hover on hover and on the selected
 *   row, body-medium labels, 4px apart (the panel's flex column carries a
 *   gap-1, the same rhythm as the Select listbox).
 *
 * Composition:
 *
 * ```tsx
 * <Dropdown isOpen={isOpen} onOpenChange={setIsOpen}>
 *   <DropdownTrigger>Open</DropdownTrigger>
 *   <DropdownPopover aria-label="Actions" placement="bottom start">
 *     <DropdownGroup label="Add">
 *       <DropdownItem onSelect={close}>…row content…</DropdownItem>
 *     </DropdownGroup>
 *     <DropdownDivider />
 *     <DropdownGroup label="Plugins">…</DropdownGroup>
 *   </DropdownPopover>
 * </Dropdown>
 * ```
 *
 * State can be uncontrolled (omit isOpen/onOpenChange) — control it when the
 * trigger needs to react to the open state (e.g. rotating a chevron).
 */

/* ------------------------------------------------------------------- shell */

interface DropdownContextValue {
  triggerRef: RefObject<HTMLButtonElement | null>;
  popoverRef: RefObject<HTMLElement | null>;
}

const DropdownContext = createContext<DropdownContextValue | null>(null);

export interface DropdownProps {
  isOpen?: boolean;
  onOpenChange?: (isOpen: boolean) => void;
  /** Trigger (a DropdownTrigger) followed by a DropdownPopover. */
  children: ReactNode;
}

/**
 * The popover is `isNonModal`: react-aria's modal scroll lock puts
 * `overflow: hidden` on <html>, which collapses the page scroll position and
 * visibly yanks sticky layout (e.g. the docs sidebar) whenever a menu opens.
 * Non-modal skips the lock, but react-aria hard-couples outside-press
 * dismissal to modality — so open state lives here (bridging any controlled
 * props) and dismissal is restored via useDismissOnOutsidePress, the same
 * fix as Select and the date-picker family.
 */
export function Dropdown({ isOpen: controlledOpen, onOpenChange, children }: DropdownProps) {
  const triggerRef = useRef<HTMLButtonElement>(null);
  const popoverRef = useRef<HTMLElement>(null);
  const [uncontrolledOpen, setUncontrolledOpen] = useState(false);

  const isOpen = controlledOpen ?? uncontrolledOpen;
  const setOpen = (next: boolean) => {
    setUncontrolledOpen(next);
    onOpenChange?.(next);
  };

  useDismissOnOutsidePress(isOpen, () => setOpen(false), [triggerRef, popoverRef]);
  // Pressing the trigger while open closes the menu instead of reopening
  const allowOpenChange = useTriggerToggle(isOpen, triggerRef);

  return (
    <DropdownContext.Provider value={{ triggerRef, popoverRef }}>
      <AriaDialogTrigger isOpen={isOpen} onOpenChange={(o) => allowOpenChange(o) && setOpen(o)}>
        {children}
      </AriaDialogTrigger>
    </DropdownContext.Provider>
  );
}

/** The element that opens the menu. Style it entirely via className. */
export function DropdownTrigger({ className, ...props }: ComponentProps<typeof AriaButton>) {
  const context = useContext(DropdownContext);
  return (
    <AriaButton
      ref={context?.triggerRef}
      {...props}
      className={cx(
        "cursor-pointer outline-none focus-visible:ring-2 focus-visible:ring-border-focus-ring",
        className as string,
      )}
    />
  );
}

/* ------------------------------------------------------------------- panel */

export interface DropdownPopoverProps
  extends Pick<ComponentProps<typeof AriaPopover>, "placement" | "offset" | "crossOffset"> {
  "aria-label": string;
  /** Extra classes on the panel — e.g. a width override (default w-[266px]). */
  className?: string;
  /** Classes on the inner dialog (the flex column), e.g. gap between groups. */
  dialogClassName?: string;
  children: ReactNode;
}

export function DropdownPopover({
  "aria-label": ariaLabel,
  placement = "bottom start",
  offset = 4,
  crossOffset,
  className,
  dialogClassName,
  children,
}: DropdownPopoverProps) {
  const context = useContext(DropdownContext);
  return (
    <AriaPopover
      ref={context?.popoverRef}
      isNonModal
      placement={placement}
      offset={offset}
      crossOffset={crossOffset}
      className={cx(
        MENU_POPOVER_WIDTH,
        MENU_POPOVER_SURFACE,
        className,
      )}
    >
      {/* gap-1 keeps bare DropdownItems 4px apart, the same rhythm as the
          Select listbox; DropdownDivider's margins are sized to absorb it. */}
      <AriaDialog aria-label={ariaLabel} className={cx("flex flex-col gap-1 outline-none", dialogClassName)}>
        {children}
      </AriaDialog>
    </AriaPopover>
  );
}

/* ----------------------------------------------------------------- content */

export interface DropdownGroupProps {
  /** Muted body-medium heading above the rows. */
  label?: string;
  className?: string;
  children: ReactNode;
}

export function DropdownGroup({ label, className, children }: DropdownGroupProps) {
  return (
    // pt-1 is spacing for the group LABEL — a label-less group must not
    // carry it, or its first row floats 4px lower than the panel padding
    // implies (visible as extra space above the first item's hover pill).
    <div className={cx("flex w-full flex-col gap-1.5", label && "pt-1", className)}>
      {label && <span className="ps-2 text-body-medium text-text-secondary">{label}</span>}
      <div className="flex w-full flex-col gap-1">{children}</div>
    </div>
  );
}

export interface DropdownItemProps {
  /** Highlights the row like the hover state (current selection). */
  selected?: boolean;
  onSelect?: () => void;
  /** Row padding defaults to p-2 — override for denser rows (px-2 py-1.5). */
  className?: string;
  children: ReactNode;
}

/**
 * A menu row. Content is free-form — icon + label, avatar + name, label +
 * trailing badge — laid out in a gap-2 flex row.
 */
export function DropdownItem({ selected, onSelect, className, children }: DropdownItemProps) {
  return (
    <button
      type="button"
      aria-pressed={selected}
      onClick={onSelect}
      className={cx(
        MENU_ITEM,
        selected ? MENU_ITEM_ACTIVE : MENU_ITEM_INTERACTIVE,
        className,
      )}
    >
      {children}
    </button>
  );
}

/** Full-bleed 1px divider between groups (bleeds through the panel's p-2.5).
 *  my-1.5 + the dialog's gap-1 on both sides = the original 10px breathing room. */
export function DropdownDivider({ className }: { className?: string }) {
  return <div className={cx("-mx-2.5 my-1.5 h-px shrink-0 bg-border-button-default", className)} />;
}

/**
 * Shared visual recipe for JoyUI menu surfaces.
 *
 * Select and Dropdown intentionally keep their distinct React Aria semantics
 * (single-value listbox vs. action menu), while consuming the same panel,
 * motion, and row treatments from here.
 */
export const MENU_POPOVER_SURFACE = [
  // z-110 sits above the modal layer (z-100), so menus opened inside a
  // Modal or Drawer render over it rather than behind its backdrop.
  "z-110 max-w-[calc(100vw-32px)] overflow-y-auto",
  // Dark: lift to quaternary-700 so menus leave primary-800 cards; light stays primary white.
  "rounded-2xl border border-border-button-default bg-background-primary-default p-2.5 shadow-dropdown dark:bg-background-quaternary-default",
  "transition duration-150 ease-out",
  "data-[entering]:opacity-0 data-[entering]:scale-95 data-[entering]:blur-[2px]",
  "data-[exiting]:opacity-0 data-[exiting]:scale-95 data-[exiting]:blur-[2px]",
  "data-[placement=bottom]:origin-top-left rtl:data-[placement=bottom]:origin-top-right data-[placement=top]:origin-bottom-left rtl:data-[placement=top]:origin-bottom-right",
  "data-[placement=left]:origin-right data-[placement=right]:origin-left",
].join(" ");

export const MENU_POPOVER_WIDTH = "w-[266px]";

export const MENU_ITEMS_CONTAINER = "flex w-full flex-col gap-1 outline-none";

export const MENU_ITEM = [
  "flex w-full cursor-pointer items-center gap-2 rounded-2lg p-2 text-start",
  "text-text-primary outline-none transition-colors",
].join(" ");

export const MENU_ITEM_ACTIVE = "bg-dropdown-item-hover-background";

export const MENU_ITEM_INTERACTIVE =
  "hover:bg-dropdown-item-hover-background focus-visible:bg-dropdown-item-hover-background";

