 *     suggestions={["本季热播", "已完结", "纪录片"]}
 *     onSuggestionSelect={(s) => setQuery(s)}
 *     onClear={() => setQuery("")}
 *   />
 */

type IconComponent = ComponentType<{
  className?: string;
  "aria-hidden"?: boolean | "true" | "false";
}>;

export interface EmptyStateSearchProps
  extends Omit<HTMLAttributes<HTMLDivElement>, "title"> {
  /** Search string to echo in the description. */
  query: string;
  /** Override default title. */
  title?: ReactNode;
  /** Override default description (otherwise echoes `query`). */
  description?: ReactNode;
  /** Remix Icon component reference. Defaults to search. */
  icon?: IconComponent;
  /** Suggestion chips under the copy. */
  suggestions?: readonly string[];
  onSuggestionSelect?: (suggestion: string) => void;
  /** Clear / reset search. */
  onClear?: () => void;
  clearLabel?: ReactNode;
  /** Optional suggestions heading. */
  suggestionsLabel?: ReactNode;
  ref?: Ref<HTMLDivElement>;
}

export function EmptyStateSearch({
  query,
  title = "未找到相关结果",
  description,
  icon: Icon = RiSearchLine,
  suggestions = [],
  onSuggestionSelect,
  onClear,
  clearLabel = "清除搜索",
  suggestionsLabel = "试试这些关键词",
  className,
  ref,
  ...props
}: EmptyStateSearchProps) {
  const resolvedDescription =
    description ??
    (query.trim()
      ? (
          <>
            没有与「
            <span className="text-text-primary">{query.trim()}</span>
            」匹配的内容，换个词试试。
          </>
        )
      : "输入关键词开始搜索。");

  return (
    <div
      ref={ref}
      className={cx(
        "flex w-full flex-col items-center justify-center gap-3 px-6 py-10 text-center",
        className,
      )}
      {...props}
    >
      <span className="mb-1.5 flex size-16 items-center justify-center rounded-2xl bg-background-secondary-default">
        <Icon className="size-8 text-foreground-icon-primary" aria-hidden />
      </span>
      <div className="flex max-w-md flex-col gap-1">
        <p className="text-body-medium text-text-primary">{title}</p>
        <p className="text-body-regular text-text-tertiary">{resolvedDescription}</p>
      </div>
      {suggestions.length > 0 ? (
        <div className="mt-1 flex w-full max-w-md flex-col items-center gap-2">
          {suggestionsLabel ? (
            <p className="text-caption-1-medium text-text-tertiary">{suggestionsLabel}</p>
          ) : null}
          <div className="flex flex-wrap items-center justify-center gap-2">
            {suggestions.map((item) => (
              <button
                key={item}
                type="button"
                onClick={() => onSuggestionSelect?.(item)}
                className={cx(
                  "inline-flex items-center rounded-full border border-separator-border bg-background-full px-3 py-1.5",
                  "text-caption-1-medium text-text-secondary shadow-xs",
                  "transition-[background-color,border-color,color] duration-200 ease",
                  "hover:border-border-button-default hover:bg-background-secondary-default hover:text-text-primary",
                  "focus-visible:outline-none focus-visible:ring-2 focus-visible:ring-border-focus-ring",
                )}
              >
                {item}
              </button>
            ))}
          </div>
        </div>
      ) : null}
      {onClear ? (
        <div className="mt-1">
          <Button variant="secondary" size="small" onClick={onClear}>
            {clearLabel}
          </Button>
        </div>
      ) : null}
    </div>
  );
}

"use client";

import { useTemplateCopy } from "../../foundations/template-copy/template-copy";

import { useEffect, useRef, useState, type ReactNode } from "react";
import {
  RiFileExcel2Line,
  RiFileImageLine,
  RiFileTextLine,
  RiUploadCloud2Line,
} from "@remixicon/react";
import { cx } from "@/lib/utils";

/**
 * Figma sources: Board UI → "Upload file" (node 4105:25269),
 * "Upload in progress" (node 4107:27192), and the complete state
 * (node 4107:30456).
 *
 * Interactive drag-and-drop file upload with validation, a perimeter progress
 * indicator, animated content transitions, and a completion callback. The
 * upload is simulated so the component is backend-agnostic; connect
 * `onUploadComplete` to the application's upload/storage layer.
 */

const DEFAULT_MAX_BYTES = 8 * 1024 * 1024;
const DEFAULT_EXTENSIONS = ["pdf", "jpg", "jpeg", "png", "xlsx"] as const;

type UploadPhase = "idle" | "uploading" | "complete";
type StaggerState = "shown" | "hiding" | "hidden";

export interface FileUploadProps {
  /** Called after the progress and success states finish. */
  onUploadComplete?: (file: File) => void;
  /** Accepted filename extensions without dots. */
  allowedExtensions?: readonly string[];
  /** Maximum accepted file size in bytes. */
  maxBytes?: number;
  /** Overrides the icon shown while a file uploads. */
  renderFileIcon?: (file: File) => ReactNode;
  className?: string;
}

export function formatFileSize(bytes: number) {
  if (bytes >= 1024 * 1024) {
    const mb = bytes / (1024 * 1024);
    return `${mb >= 10 ? Math.round(mb) : Math.round(mb * 10) / 10} MB`;
  }
  return `${Math.max(1, Math.round(bytes / 1024))} KB`;
}

function extensionFor(fileName: string) {
  return fileName.split(".").pop()?.toLowerCase() ?? "";
}

function DefaultFileIcon({ file }: { file: File }) {
  const extension = extensionFor(file.name);
  const Icon = extension === "xlsx"
    ? RiFileExcel2Line
    : ["jpg", "jpeg", "png"].includes(extension)
      ? RiFileImageLine
      : RiFileTextLine;

  return <Icon className="size-6 shrink-0 text-foreground-icon-secondary" aria-hidden />;
}

/** Drives the Transitions.dev text-reveal states defined in globals.css. */
function useStaggerState(active: boolean): StaggerState {
  const [prevActive, setPrevActive] = useState(active);
  const [hiding, setHiding] = useState(false);

  if (prevActive !== active) {
    setPrevActive(active);
    setHiding(!active);
  }

  useEffect(() => {
    if (!hiding) return;
    const timer = setTimeout(() => setHiding(false), 200);
    return () => clearTimeout(timer);
  }, [hiding]);

  return active ? "shown" : hiding ? "hiding" : "hidden";
}

const staggerContainer = (state: StaggerState) =>
  cx("t-stagger", state === "shown" && "is-shown", state === "hiding" && "is-hiding");

const staggerLine = (state: StaggerState) =>
  cx(
    state === "shown" &&
      "translate-y-0 opacity-100 blur-0 [transition:opacity_var(--stagger-dur)_var(--stagger-ease),translate_var(--stagger-dur)_var(--stagger-ease),filter_var(--stagger-dur)_var(--stagger-ease)]",
    state === "hiding" && "translate-y-0 opacity-0 blur-0 [transition:opacity_200ms_ease]",
    state === "hidden" && "translate-y-3 opacity-0 blur-[3px] transition-none",
  );

/** Rounded-rect progress path beginning at top-center and running clockwise. */
function ringPath(width: number, height: number, inset: number, radius: number) {
  const x0 = inset;
  const y0 = inset;
  const x1 = width - inset;
  const y1 = height - inset;
  const arc = (endX: number, endY: number) =>
    `A ${radius} ${radius} 0 0 1 ${endX} ${endY}`;

  return [
    `M ${width / 2} ${y0}`,
    `H ${x1 - radius}`,
    arc(x1, y0 + radius),
    `V ${y1 - radius}`,
    arc(x1 - radius, y1),
    `H ${x0 + radius}`,
    arc(x0, y1 - radius),
    `V ${y0 + radius}`,
    arc(x0 + radius, y0),
    "Z",
  ].join(" ");
}

export function FileUpload({
  onUploadComplete,
  allowedExtensions = DEFAULT_EXTENSIONS,
  maxBytes = DEFAULT_MAX_BYTES,
  renderFileIcon,
  className,
}: FileUploadProps) {
  const localize = useTemplateCopy();
  const [phase, setPhase] = useState<UploadPhase>("idle");
  const [progress, setProgress] = useState(0);
  const [file, setFile] = useState<File | null>(null);
  const [rejection, setRejection] = useState<string | null>(null);
  const [dragOver, setDragOver] = useState(false);

  const inputRef = useRef<HTMLInputElement>(null);
  const boxRef = useRef<HTMLDivElement>(null);
  const [box, setBox] = useState({ width: 533, height: 164 });
  const timers = useRef<ReturnType<typeof setTimeout>[]>([]);

  useEffect(() => {
    const element = boxRef.current;
    if (!element) return;
    const observer = new ResizeObserver(([entry]) => {
      const { width, height } = entry.contentRect;
      if (width > 0) setBox({ width, height });
    });
    observer.observe(element);
    return () => observer.disconnect();
  }, []);

  useEffect(() => {
    const pending = timers.current;
    return () => pending.forEach(clearTimeout);
  }, []);

  const startUpload = (nextFile: File) => {
    const extension = extensionFor(nextFile.name);
    if (!allowedExtensions.map((value) => value.toLowerCase()).includes(extension)) {
      setRejection(`Only ${allowedExtensions.map((value) => value.toUpperCase()).join(", ")} files are supported`);
      timers.current.push(setTimeout(() => setRejection(null), 2600));
      return;
    }
    if (nextFile.size > maxBytes) {
      setRejection(`That file is larger than ${formatFileSize(maxBytes)}`);
      timers.current.push(setTimeout(() => setRejection(null), 2600));
      return;
    }

    setFile(nextFile);
    setProgress(0);
    setPhase("uploading");

    let value = 0;
    const tick = () => {
      value = Math.min(100, value + 2 + Math.random() * 5);
      setProgress(Math.round(value));
      if (value < 100) {
        timers.current.push(setTimeout(tick, 90));
        return;
      }

      setPhase("complete");
      timers.current.push(
        setTimeout(() => {
          onUploadComplete?.(nextFile);
          setPhase("idle");
          setFile(null);
        }, 1600),
      );
    };
    timers.current.push(setTimeout(tick, 250));
  };

  const busy = phase !== "idle";
  const progressPath = ringPath(box.width, box.height, 1, 15);
  const idleReveal = useStaggerState(!busy);
  const busyReveal = useStaggerState(busy);
  const uploadingLine = useStaggerState(phase === "uploading");
  const completeLine = useStaggerState(phase === "complete");
  const allowedLabel = allowedExtensions
    .filter((extension) => extension.toLowerCase() !== "jpeg")
    .map((extension) => extension.toUpperCase())
    .join(", ");

  return localize(
    <div
      ref={boxRef}
      role="button"
      tabIndex={busy ? -1 : 0}
      aria-label="Upload a file"
      onClick={() => !busy && inputRef.current?.click()}
      onKeyDown={(event) => {
        if (!busy && (event.key === "Enter" || event.key === " ")) {
          event.preventDefault();
          inputRef.current?.click();
        }
      }}
      onDragOver={(event) => {
        event.preventDefault();
        if (!busy) setDragOver(true);
      }}
      onDragLeave={() => setDragOver(false)}
      onDrop={(event) => {
        event.preventDefault();
        setDragOver(false);
        const droppedFile = event.dataTransfer.files?.[0];
        if (droppedFile && !busy) startUpload(droppedFile);
      }}
      className={cx(
        "group relative h-[164px] w-full shrink-0 rounded-2xl outline-none",
        "transition-colors duration-300 ease-out",
        busy ? "bg-background-primary-default" : "cursor-pointer bg-background-secondary-default",
        "focus-visible:ring-2 focus-visible:ring-offset-2 focus-visible:ring-border-focus-ring",
        className,
      )}
    >
      <input
        ref={inputRef}
        type="file"
        aria-label="Choose a file to upload"
        accept={allowedExtensions.map((extension) => `.${extension}`).join(",")}
        className="sr-only"
        tabIndex={-1}
        onChange={(event) => {
          const selectedFile = event.target.files?.[0];
          event.target.value = "";
          if (selectedFile) startUpload(selectedFile);
        }}
      />

      <div
        aria-hidden
        className={cx(
          "pointer-events-none absolute inset-0 rounded-2xl border-2 border-dashed",
          dragOver
            ? "border-border-button-active"
            : "border-border-checkbox-default group-hover:border-border-button-active",
          "transition-[opacity,border-color] duration-300 ease-out",
          busy ? "opacity-0" : "opacity-100",
        )}
      />

      <svg
        aria-hidden
        viewBox={`0 0 ${box.width} ${box.height}`}
        preserveAspectRatio="none"
        className={cx(
          "pointer-events-none absolute inset-0 size-full transition-opacity duration-300 ease-out",
          busy ? "opacity-100" : "opacity-0",
        )}
      >
        <rect
          x={1}
          y={1}
          width={box.width - 2}
          height={box.height - 2}
          rx={15}
          fill="none"
          stroke="var(--color-border-button-default)"
          strokeWidth={2}
        />
        <path
          d={progressPath}
          fill="none"
          stroke="var(--color-accent-400)"
          strokeWidth={2}
          strokeLinecap="round"
          pathLength={100}
          strokeDasharray={`${busy ? (progress >= 100 ? 102 : progress) : 0} 200`}
          className="transition-[stroke-dasharray] duration-200 ease-linear"
        />
      </svg>

      <div
        aria-hidden
        className={cx(
          "absolute -top-[9.5px] left-1/2 -translate-x-1/2 rounded-md bg-accent-400 px-1.5 py-0.5",
          "text-caption-1-medium whitespace-nowrap text-white tabular-nums",
          "[transition:opacity_160ms_ease-out,filter_160ms_ease-out,translate_300ms_ease-out]",
          busy ? "translate-y-0 opacity-100 blur-0" : "-translate-y-2.5 opacity-0 blur-[2px]",
        )}
      >
        {progress}%
      </div>

      <div
        className={cx(
          "absolute inset-0 flex flex-col items-center justify-center gap-3.5",
          staggerContainer(idleReveal),
          busy && "pointer-events-none",
        )}
      >
        <span className="t-stagger-line t-stagger-line--1 flex size-10 items-center justify-center rounded-full bg-file-upload-icon-background p-2.5">
          <RiUploadCloud2Line
            className="size-6 shrink-0 text-file-upload-icon-foreground transition-colors duration-150 ease group-hover:text-file-upload-icon-foreground-hover"
            aria-hidden
          />
        </span>
        <div className="flex flex-col items-center gap-2 text-center">
          <p
            className={cx(
              "t-stagger-line t-stagger-line--2 text-body-medium",
              rejection ? "text-text-error-primary" : "text-text-secondary",
            )}
          >
            {rejection ?? (
              <>
                Drag and drop to upload or <span className="text-accent-500">select</span>
              </>
            )}
          </p>
          <p className="t-stagger-line t-stagger-line--3 text-body-2-regular text-text-tertiary">
            {allowedLabel} (max {formatFileSize(maxBytes)})
          </p>
        </div>
      </div>

      <div
        className={cx(
          "absolute inset-0 flex flex-col items-center justify-center",
          staggerContainer(busyReveal),
          !busy && "pointer-events-none",
        )}
      >
        <span className="t-stagger-line t-stagger-line--1 flex size-10 items-center justify-center rounded-full border border-border-button-default bg-background-primary-default p-2">
          {file && (renderFileIcon ? renderFileIcon(file) : <DefaultFileIcon file={file} />)}
        </span>
        <p className="t-stagger-line t-stagger-line--2 mt-3.5 max-w-[90%] truncate text-body-medium text-text-primary">
          {file?.name}
        </p>
        <div className="t-stagger-line t-stagger-line--3 relative mt-1 h-[18px] w-full">
          <p
            className={cx(
              "absolute inset-x-0 text-center text-body-2-regular text-text-secondary",
              staggerLine(uploadingLine),
            )}
          >
            Uploading {file ? formatFileSize(file.size) : ""}
            ...
          </p>
          <p
            className={cx(
              "absolute inset-x-0 text-center text-body-2-regular text-text-secondary",
              staggerLine(completeLine),
            )}
          >
            Uploaded successfully!
          </p>
        </div>
      </div>
    </div>
  );
}

"use client";

import { useEffect, useMemo, useRef, useState, type ReactNode } from "react";
import {
  RiCloseLine,
  RiFileExcel2Line,
  RiFileImageLine,
  RiFileTextLine,
  RiUploadCloud2Line,
} from "@remixicon/react";
import { cx } from "@/lib/utils";

/**
 * Multi-file upload with a thumbnail / file preview grid.
 *
 *   <FileUploadGallery
 *     onChange={(files) => console.log(files)}
 *     maxFiles={8}
 *   />
 */

const DEFAULT_MAX_BYTES = 8 * 1024 * 1024;
const DEFAULT_EXTENSIONS = ["pdf", "jpg", "jpeg", "png", "xlsx", "webp"] as const;

export interface FileUploadGalleryProps {
  /** Controlled file list. */
  value?: File[];
  /** Uncontrolled initial files. */
  defaultValue?: File[];
  onChange?: (files: File[]) => void;
  /** Accepted filename extensions without dots. */
  allowedExtensions?: readonly string[];
  /** Maximum accepted file size in bytes. */
  maxBytes?: number;
  /** Cap on how many files can be kept. */
  maxFiles?: number;
  /** Drop-zone title. */
  title?: ReactNode;
  /** Drop-zone hint under the title. */
  description?: ReactNode;
  className?: string;
}

function extensionFor(fileName: string) {
  return fileName.split(".").pop()?.toLowerCase() ?? "";
}

function formatFileSize(bytes: number) {
  if (bytes >= 1024 * 1024) {
    const mb = bytes / (1024 * 1024);
    return `${mb >= 10 ? Math.round(mb) : Math.round(mb * 10) / 10} MB`;
  }
  return `${Math.max(1, Math.round(bytes / 1024))} KB`;
}

function FileGlyph({ file }: { file: File }) {
  const extension = extensionFor(file.name);
  const Icon = extension === "xlsx"
    ? RiFileExcel2Line
    : ["jpg", "jpeg", "png", "webp"].includes(extension)
      ? RiFileImageLine
      : RiFileTextLine;
  return <Icon className="size-6 text-foreground-icon-secondary" aria-hidden />;
}

function isImage(file: File) {
  return file.type.startsWith("image/") || ["jpg", "jpeg", "png", "webp"].includes(extensionFor(file.name));
}

export function FileUploadGallery({
  value,
  defaultValue = [],
  onChange,
  allowedExtensions = DEFAULT_EXTENSIONS,
  maxBytes = DEFAULT_MAX_BYTES,
  maxFiles = 8,
  title = "拖放或点击上传",
  description,
  className,
}: FileUploadGalleryProps) {
  const inputRef = useRef<HTMLInputElement>(null);
  const [uncontrolled, setUncontrolled] = useState<File[]>(defaultValue);
  const [dragOver, setDragOver] = useState(false);
  const [rejection, setRejection] = useState<string | null>(null);
  const files = value ?? uncontrolled;

  const allowedLabel = allowedExtensions
    .filter((extension) => extension.toLowerCase() !== "jpeg")
    .map((extension) => extension.toUpperCase())
    .join(", ");

  const commit = (next: File[]) => {
    if (value === undefined) setUncontrolled(next);
    onChange?.(next);
  };

  const reject = (message: string) => {
    setRejection(message);
    window.setTimeout(() => setRejection(null), 2600);
  };

  const addFiles = (incoming: FileList | File[]) => {
    const list = Array.from(incoming);
    if (!list.length) return;

    const next = [...files];
    for (const file of list) {
      if (next.length >= maxFiles) {
        reject(`最多上传 ${maxFiles} 个文件`);
        break;
      }
      const extension = extensionFor(file.name);
      if (!allowedExtensions.map((v) => v.toLowerCase()).includes(extension)) {
        reject(`仅支持 ${allowedLabel}`);
        continue;
      }
      if (file.size > maxBytes) {
        reject(`文件超过 ${formatFileSize(maxBytes)}`);
        continue;
      }
      next.push(file);
    }
    commit(next);
  };

  const removeAt = (index: number) => {
    commit(files.filter((_, i) => i !== index));
  };

  const previewUrls = useMemo(
    () =>
      files.map((file) => (isImage(file) ? URL.createObjectURL(file) : null)),
    [files],
  );

  useEffect(() => {
    return () => {
      previewUrls.forEach((url) => {
        if (url) URL.revokeObjectURL(url);
      });
    };
  }, [previewUrls]);

  return (
    <div className={cx("flex w-full flex-col gap-3", className)}>
      <div
        role="button"
        tabIndex={0}
        aria-label="上传多个文件"
        onClick={() => inputRef.current?.click()}
        onKeyDown={(event) => {
          if (event.key === "Enter" || event.key === " ") {
            event.preventDefault();
            inputRef.current?.click();
          }
        }}
        onDragOver={(event) => {
          event.preventDefault();
          setDragOver(true);
        }}
        onDragLeave={() => setDragOver(false)}
        onDrop={(event) => {
          event.preventDefault();
          setDragOver(false);
          if (event.dataTransfer.files?.length) addFiles(event.dataTransfer.files);
        }}
        className={cx(
          "flex min-h-28 cursor-pointer flex-col items-center justify-center gap-2 rounded-2xl border-2 border-dashed px-4 py-6 text-center outline-none transition-colors",
          "bg-background-secondary-default focus-visible:ring-2 focus-visible:ring-border-focus-ring focus-visible:ring-offset-2",
          dragOver
            ? "border-border-button-active"
            : "border-border-checkbox-default hover:border-border-button-active",
        )}
      >
        <span className="flex size-10 items-center justify-center rounded-full bg-file-upload-icon-background p-2.5">
          <RiUploadCloud2Line
            className="size-6 text-file-upload-icon-foreground"
            aria-hidden
          />
        </span>
        <div className="flex flex-col gap-1">
          <p className="text-body-medium text-text-primary">{title}</p>
          <p className="text-body-2-regular text-text-tertiary">
            {description ?? `${allowedLabel} · 单文件 ≤ ${formatFileSize(maxBytes)} · 最多 ${maxFiles} 个`}
          </p>
        </div>
        <input
          ref={inputRef}
          type="file"
          multiple
          aria-label="选择多个文件"
          accept={allowedExtensions.map((extension) => `.${extension}`).join(",")}
          className="sr-only"
          tabIndex={-1}
          onChange={(event) => {
            if (event.target.files?.length) addFiles(event.target.files);
            event.target.value = "";
          }}
        />
      </div>

      {rejection ? (
        <p className="text-body-2-regular text-notification-error-foreground" role="status">
          {rejection}
        </p>
      ) : null}

      {files.length > 0 ? (
        <ul className="grid grid-cols-2 gap-2 sm:grid-cols-3 md:grid-cols-4" aria-label="已选文件">
          {files.map((file, index) => (
            <li
              key={`${file.name}-${file.size}-${index}`}
              className="group relative flex flex-col overflow-hidden rounded-2xl border border-separator-border bg-background-primary-default"
            >
              <div className="flex aspect-square items-center justify-center bg-background-secondary-default">
                {previewUrls[index] ? (
                  // eslint-disable-next-line @next/next/no-img-element
                  <img
                    src={previewUrls[index]!}
                    alt=""
                    className="size-full object-cover"
                  />
                ) : (
                  <FileGlyph file={file} />
                )}
              </div>
              <div className="flex flex-col gap-0.5 p-2">
                <p className="truncate text-caption-1-medium text-text-primary">{file.name}</p>
                <p className="text-caption-1-regular text-text-tertiary">{formatFileSize(file.size)}</p>
              </div>
              <button
                type="button"
                aria-label={`移除 ${file.name}`}
                onClick={() => removeAt(index)}
                className="absolute right-1.5 top-1.5 flex size-7 items-center justify-center rounded-full bg-background-primary-default/90 text-text-secondary opacity-0 shadow-xs outline-none transition-opacity hover:text-text-primary focus-visible:opacity-100 focus-visible:ring-2 focus-visible:ring-border-focus-ring group-hover:opacity-100"
              >
                <RiCloseLine className="size-4" aria-hidden />
              </button>
            </li>
          ))}
        </ul>
      ) : null}
    </div>
  );
}

"use client";

import type { HTMLAttributes, ReactNode, Ref } from "react";
import { HintText } from "../input/hint-text";
import { Label } from "../input/label";
import { cx } from "@/lib/utils";

/**
 * Form row shell — Label + control + hint/error. Use when composing fields
 * that are not already wrapped (Input / Select already include Label).
 *
 *   <FormField label="名称" hint="对外名" isRequired>
 *     <InputBase … />
 *   </FormField>
 */

export interface FormFieldProps extends HTMLAttributes<HTMLDivElement> {
  label?: ReactNode;
  hint?: ReactNode;
  errorMessage?: ReactNode;
  isRequired?: boolean;
  isInvalid?: boolean;
  /** Associates label with a control id. */
  htmlFor?: string;
  children: ReactNode;
  ref?: Ref<HTMLDivElement>;
}

export function FormField({
  label,
  hint,
  errorMessage,
  isRequired = false,
  isInvalid = false,
  htmlFor,
  children,
  className,
  ref,
  ...props
}: FormFieldProps) {
  const showError = Boolean(errorMessage) || isInvalid;
  const caption = showError && errorMessage ? errorMessage : hint;

  return (
    <div
      ref={ref}
      className={cx("flex w-full flex-col gap-1.5", className)}
      {...props}
    >
      {label ? (
        <Label htmlFor={htmlFor} isRequired={isRequired} isInvalid={showError}>
          {label}
        </Label>
      ) : null}
      {children}
      {caption ? <HintText isInvalid={showError}>{caption}</HintText> : null}
    </div>
  );
}

import dayjs from "dayjs";
import customParseFormat from "dayjs/plugin/customParseFormat.js";
import duration from "dayjs/plugin/duration.js";
import localizedFormat from "dayjs/plugin/localizedFormat.js";
import relativeTime from "dayjs/plugin/relativeTime.js";
import timezone from "dayjs/plugin/timezone.js";
import utc from "dayjs/plugin/utc.js";
import "dayjs/locale/zh-cn.js";

dayjs.extend(customParseFormat);
dayjs.extend(duration);
dayjs.extend(localizedFormat);
dayjs.extend(relativeTime);
dayjs.extend(timezone);
dayjs.extend(utc);

export type DateInput = string | number | Date | dayjs.Dayjs | null | undefined;

export function toDayjs(value: DateInput, locale = "zh-cn") {
  return dayjs(value ?? undefined).locale(locale);
}

/** Format a date. Default pattern mirrors common dashboard tables. */
export function formatDate(
  value: DateInput,
  pattern = "YYYY-MM-DD HH:mm",
  locale = "zh-cn",
) {
  const d = toDayjs(value, locale);
  return d.isValid() ? d.format(pattern) : "";
}

export function fromNow(value: DateInput, locale = "zh-cn") {
  const d = toDayjs(value, locale);
  return d.isValid() ? d.fromNow() : "";
}

export function toNativeDate(value: DateInput) {
  const d = toDayjs(value);
  return d.isValid() ? d.toDate() : undefined;
}

export function formatNumber(
  value: number,
  locale = "zh-CN",
  options?: Intl.NumberFormatOptions,
) {
  return new Intl.NumberFormat(locale, options).format(value);
}

export function formatPercent(
  value: number,
  locale = "zh-CN",
  fractionDigits = 1,
) {
  return new Intl.NumberFormat(locale, {
    style: "percent",
    maximumFractionDigits: fractionDigits,
  }).format(value);
}

export function formatCurrency(
  value: number,
  currency = "CNY",
  locale = "zh-CN",
) {
  return new Intl.NumberFormat(locale, {
    style: "currency",
    currency,
    maximumFractionDigits: 2,
  }).format(value);
}

export function formatCompact(value: number, locale = "zh-CN") {
  return new Intl.NumberFormat(locale, {
    notation: "compact",
    maximumFractionDigits: 1,
  }).format(value);
}

const BYTE_UNITS = ["B", "KB", "MB", "GB", "TB"] as const;

export function formatBytes(bytes: number, fractionDigits = 1) {
  if (!Number.isFinite(bytes) || bytes < 0) return "";
  if (bytes === 0) return "0 B";
  const i = Math.min(
    Math.floor(Math.log(bytes) / Math.log(1024)),
    BYTE_UNITS.length - 1,
  );
  const n = bytes / 1024 ** i;
  return `${n.toFixed(fractionDigits)} ${BYTE_UNITS[i]}`;
}

