/**
 * Hover / focus preview card — beUI Profile hover card on JoyUI Popover chrome
 * (`rounded-[20px]`, `border-button`, `shadow-dropdown`).
 *
 *   <HoverCard content={<div>…profile…</div>}>
 *     <Avatar initials="JL" />
 *   </HoverCard>
 */

export interface HoverCardProps {
  children: ReactNode;
  content: ReactNode;
  /** Delay before open (ms). */
  openDelay?: number;
  /** Delay before close (ms). */
  closeDelay?: number;
  className?: string;
  contentClassName?: string;
}

export function HoverCard({
  children,
  content,
  openDelay = 160,
  closeDelay = 120,
  className,
  contentClassName,
}: HoverCardProps) {
  const id = useId();
  const triggerRef = useRef<HTMLSpanElement>(null);
  const panelRef = useRef<HTMLDivElement>(null);
  const timer = useRef<number | null>(null);
  const [open, setOpen] = useState(false);
  const [coords, setCoords] = useState({ top: 0, left: 0 });
  const [mounted, setMounted] = useState(false);
  const [visible, setVisible] = useState(false);

  useEffect(() => {
    setMounted(true);
  }, []);

  useEffect(() => {
    if (!open) {
      setVisible(false);
      return;
    }
    const id = requestAnimationFrame(() => setVisible(true));
    return () => cancelAnimationFrame(id);
  }, [open]);

  const clear = () => {
    if (timer.current != null) {
      window.clearTimeout(timer.current);
      timer.current = null;
    }
  };

  const place = () => {
    const el = triggerRef.current;
    if (!el) return;
    const rect = el.getBoundingClientRect();
    setCoords({
      top: rect.bottom + 8 + window.scrollY,
      left: rect.left + window.scrollX,
    });
  };

  const scheduleOpen = () => {
    clear();
    timer.current = window.setTimeout(() => {
      place();
      setOpen(true);
    }, openDelay);
  };

  const scheduleClose = () => {
    clear();
    timer.current = window.setTimeout(() => setOpen(false), closeDelay);
  };

  useEffect(() => () => clear(), []);

  return (
    <>
      <span
        ref={triggerRef}
        className={cx("inline-flex", className)}
        aria-describedby={open ? id : undefined}
        onMouseEnter={scheduleOpen}
        onMouseLeave={scheduleClose}
        onFocus={scheduleOpen}
        onBlur={scheduleClose}
      >
        {children}
      </span>
      {mounted && open
        ? createPortal(
            <div
              ref={panelRef}
              id={id}
              role="tooltip"
              className={cx(
                // Same surface recipe as Popover.
                "z-110 w-72 max-w-[calc(100vw-32px)] rounded-[20px] border border-border-button-default bg-background-primary-default p-1.5 shadow-dropdown",
                "transition-[opacity,transform,filter] duration-150 ease-out",
                visible
                  ? "opacity-100 scale-100 blur-0"
                  : "opacity-0 scale-95 blur-[2px] motion-reduce:scale-100 motion-reduce:blur-0",
                contentClassName,
              )}
              style={{ position: "absolute", top: coords.top, left: coords.left }}
              onMouseEnter={clear}
              onMouseLeave={scheduleClose}
            >
              <div className="rounded-[14px] p-2.5">{content}</div>
            </div>,
            document.body,
          )
        : null}
    </>
  );
}

"use client";

import type { ReactNode } from "react";
import { Avatar, type AvatarProps } from "../avatar/avatar";
import { HoverCard, type HoverCardProps } from "../hover-card/hover-card";
import { cx } from "@/lib/utils";

/**
 * Profile hover card — HoverCard + Avatar composition for mentions and assignees.
 *
 *   <HoverCardProfile name="林晓" role="产品设计" handle="@linxiao" initials="林" color="lime">
 *     <Avatar initials="林" color="lime" />
 *   </HoverCardProfile>
 */

export interface HoverCardProfileProps
  extends Pick<HoverCardProps, "openDelay" | "closeDelay" | "className" | "contentClassName"> {
  name: string;
  role?: string;
  handle?: string;
  initials?: string;
  color?: AvatarProps["color"];
  /** Trigger element (usually an Avatar or mention chip). */
  children: ReactNode;
}

export function HoverCardProfile({
  name,
  role,
  handle,
  initials,
  color = "neutral",
  children,
  openDelay,
  closeDelay,
  className,
  contentClassName,
}: HoverCardProfileProps) {
  const resolvedInitials =
    initials ??
    name
      .split(/\s+/)
      .filter(Boolean)
      .slice(0, 2)
      .map((part) => part[0])
      .join("")
      .toUpperCase();

  return (
    <HoverCard
      openDelay={openDelay}
      closeDelay={closeDelay}
      className={className}
      contentClassName={contentClassName}
      content={
        <div className={cx("flex items-center gap-3")}>
          <Avatar size="lg" color={color} initials={resolvedInitials} />
          <div className="min-w-0">
            <p className="truncate text-body-medium text-text-primary">{name}</p>
            {(role || handle) && (
              <p className="truncate text-body-2-regular text-text-secondary">
                {[role, handle].filter(Boolean).join(" · ")}
              </p>
            )}
          </div>
        </div>
      }
    >
      {children}
    </HoverCard>
  );
}

