/** The field shell's state for a render-prop className. */
export interface InputFieldState {
  isFocusWithin: boolean;
  isHovered: boolean;
  isDisabled: boolean;
  isInvalid: boolean;
}

/**
 * The field shell's classes for a state. InputBase uses it, and so do fields
 * whose editable part isn't an <input> (Time Field's segments).
 */
export function inputFieldClassName(
  { isFocusWithin, isHovered, isDisabled, isInvalid }: InputFieldState,
  size: InputSize = "medium",
  hasAddon = false,
  surface: InputSurface = "well",
) {
  const outline = surface === "outline";
  return cx(
    outline ? inputStyles.fieldOutline : inputStyles.fieldWell,
    hasAddon ? inputStyles.fieldWithAddonSize[size] : inputStyles.fieldSize[size],
    // Hover
    isHovered &&
      !isFocusWithin &&
      !isDisabled &&
      !isInvalid &&
      (outline
        ? "border-border-button-hover bg-background-primary-hover"
        : "ring-2 ring-border-button-hover"),
    // Focus wins over hover
    isFocusWithin &&
      !isDisabled &&
      !isInvalid &&
      (outline
        ? "border-border-button-active ring-2 ring-border-button-active"
        : "ring-2 ring-border-button-active"),
    // Disabled
    isDisabled &&
      (outline
        ? "border-border-secondary-default bg-background-primary-disabled text-input-disabled-foreground shadow-none"
        : "bg-input-disabled-background text-input-disabled-foreground ring-border-secondary-default/70"),
    // Invalid
    isInvalid &&
      (outline
        ? "border-border-error-default bg-background-tertiary-error text-foreground-icon-error ring-2 ring-border-error-default"
        : "bg-background-tertiary-error text-foreground-icon-error ring-2 ring-border-error-default"),
  );
}

export function InputBase({
  size: sizeProp,
  surface = "well",
  leadingIcon: Leading,
  trailingIcon: Trailing,
  leadingAddon,
  trailingAddon,
  fieldClassName,
  className,
  ref,
  groupRef,
  ...inputProps
}: InputBaseProps) {
  const { direction } = useLocale();
  const ctx = useContext(TextFieldContext);
  const size: InputSize = sizeProp ?? ctx.size ?? "medium";
  const hasAddon = leadingAddon !== undefined && leadingAddon !== null;

  return (
    <AriaGroup
      ref={groupRef}
      className={(state) =>
        cx(inputFieldClassName(state, size, hasAddon, surface), ctx.fieldClassName, fieldClassName)
      }
    >
      <div className={inputStyles.content}>
        <div className={inputStyles.leftSection}>
          {hasAddon ? (
            leadingAddon
          ) : Leading ? (
            <Leading className={inputStyles.icon} aria-hidden />
          ) : null}
          <AriaInput
            ref={ref}
            {...inputProps}
            // Align to the field's start even when email/URL values use LTR.
            className={cx(inputStyles.input, direction === "rtl" ? "pr-1 text-right" : "pl-1 text-left", ctx.inputClassName, className)}
          />
        </div>
        {trailingAddon ?? (Trailing ? (
          <Trailing className={inputStyles.icon} aria-hidden />
        ) : null)}
      </div>
    </AriaGroup>
  );
}

