"use client";

import { useTemplateCopy } from "../../foundations/template-copy/template-copy";

import { useEffect, useState } from "react";
import { ChevronLeft16, ChevronRight16 } from "../../base/date-picker/shared";
import { cx } from "@/lib/utils";

/** Rectangular chevron hover, matched 1:1 to the date picker's month-nav
 *  buttons (see `MonthPanel` in date-picker/shared). */
const NAV_BUTTON = cx(
  "flex size-4 shrink-0 cursor-pointer items-center justify-center rounded-[3px] text-text-secondary outline-none",
  "transition-colors duration-150 ease hover:bg-background-secondary-hover",
  "focus-visible:ring-2 focus-visible:ring-border-focus-ring",
);

/**
 * Rolling-counter label: on change the outgoing value lifts 5px + fades out
 * while the incoming value rises in from 5px below + fades in. Both labels
 * coexist for the ~220ms transition, clipped to the line box so the movement
 * reads like a counter tick rather than a crossfade.
 */
function AnimatedLabel({ label }: { label: string }) {
  const localize = useTemplateCopy();
  const [current, setCurrent] = useState(label);
  const [previous, setPrevious] = useState<string | null>(null);

  useEffect(() => {
    if (label !== current) {
      setPrevious(current);
      setCurrent(label);
    }
  }, [label, current]);

  useEffect(() => {
    if (previous === null) return;
    const t = setTimeout(() => setPrevious(null), 240);
    return () => clearTimeout(t);
  }, [previous]);

  return localize((
    <span className="relative flex-1 overflow-hidden text-center text-body-medium whitespace-nowrap text-text-primary">
      {/* Invisible spacer keeps the line box height/width for the absolutes. */}
      <span className="invisible">{current}</span>
      {previous !== null && (
        <span
          key={`out-${previous}`}
          className="animate-label-out absolute inset-0 flex items-center justify-center"
        >
          {previous}
        </span>
      )}
      <span
        key={`in-${current}`}
        className={cx(
          "absolute inset-0 flex items-center justify-center",
          previous !== null && "animate-label-in",
        )}
      >
        {current}
      </span>
    </span>
  ));
}

/**
 * Figma source: Board UI → medical profile dashboard → "Month 1" pill (e.g.
 * node 3950:5720 for the "29 Jun - 5 Jul" week variant, node 3950:5897 for
 * the "December" month variant on Most active days) — same 151×32 chrome
 * for both. 151px is a minimum, not a fixed width: a longer label (a wide
 * week, or a translation) grows the pill instead of being clipped.
 *
 * Pass `onPrev`/`onNext` to make the chevrons real buttons (the Most active
 * days month switcher); omit them for the decorative static pill used by
 * the other cards, where Figma shows the same fixed range everywhere.
 */
export function WeekRangePill({
  label,
  onPrev,
  onNext,
  className,
}: {
  label: string;
  onPrev?: () => void;
  onNext?: () => void;
  /** Override the default 151px minimum width (e.g. the narrower month switcher). */
  className?: string;
}) {
  const localize = useTemplateCopy();
  const interactive = !!(onPrev || onNext);
  return localize((
    <div
      className={cx(
        "flex h-8 min-w-[151px] shrink-0 items-center justify-between gap-1 rounded-2lg border border-border-button-default bg-background-primary-default px-1 py-1 shadow-xs",
        className,
      )}
    >
      {interactive ? (
        <button type="button" aria-label="Previous" onClick={onPrev} className={NAV_BUTTON}>
          <ChevronLeft16 />
        </button>
      ) : (
        <span className="flex size-4 shrink-0 items-center justify-center text-text-secondary" aria-hidden>
          <ChevronLeft16 />
        </span>
      )}
      {/* The interactive switcher rolls its label like a counter as the month
          changes; static pills just render plain text. */}
      {interactive ? (
        <AnimatedLabel label={label} />
      ) : (
        <span className="flex-1 text-center text-body-medium whitespace-nowrap text-text-primary">
          {label}
        </span>
      )}
      {interactive ? (
        <button type="button" aria-label="Next" onClick={onNext} className={NAV_BUTTON}>
          <ChevronRight16 />
        </button>
      ) : (
        <span className="flex size-4 shrink-0 items-center justify-center text-text-secondary" aria-hidden>
          <ChevronRight16 />
        </span>
      )}
    </div>
  ));
}

"use client";

import type { ReactNode } from "react";
import { Meter as AriaMeter } from "react-aria-components";
import type { MeterProps as AriaMeterProps } from "react-aria-components";
import { Label } from "../input/label";
import { ProgressTrack, type ProgressSize } from "../progress/progress";
import { cx, sortCx } from "@/lib/utils";

/**
 * Meter — a quantity within a known range: storage used, seats taken, a
 * password's strength. Unlike ProgressBar it describes a level rather than
 * a task moving towards done, and React Aria's Meter announces it that way
 * (role="meter").
 *
 *   <Meter label="Storage" value={72} valueLabel="7.2 of 10 GB" />
 *   <Meter label="Seats" value={19} maxValue={20} tone="warning" />
 *
 * It is drawn on ProgressBar's track: the same rail, fill, and eased
 * translate when the value changes. `tone` colours the fill from semantic
 * tokens, so a meter can turn amber or red as it fills up.
 */

export type MeterTone = "accent" | "success" | "warning" | "error";

const tones = sortCx({
  accent: "text-accent-500",
  success: "text-notification-success-foreground",
  warning: "text-chart-8-active",
  error: "text-notification-error-foreground",
});

export interface MeterProps extends Omit<AriaMeterProps, "children" | "className"> {
  label?: ReactNode;
  /** Show the formatted value at the end of the label row. Default: shown with a label. */
  showValueLabel?: boolean;
  /** Helper text under the bar. */
  description?: ReactNode;
  /** Colour of the fill. Default `accent`. */
  tone?: MeterTone;
  /** Track thickness: 4, 6 (default), or 8px. */
  size?: ProgressSize;
  className?: string;
}

export function Meter({
  label,
  showValueLabel,
  description,
  tone = "accent",
  size = "md",
  className,
  ...props
}: MeterProps) {
  const showValue = showValueLabel ?? label != null;
  return (
    <AriaMeter {...props} className={cx("flex w-full flex-col gap-1.5", className)}>
      {({ percentage, valueText }) => (
        <>
          {label != null || showValue ? (
            <div className="flex items-baseline justify-between gap-3">
              {label != null ? <Label className="min-w-0 truncate">{label}</Label> : <span />}
              {showValue ? (
                <span className="shrink-0 text-body-medium text-text-secondary tabular-nums">{valueText}</span>
              ) : null}
            </div>
          ) : null}
          <ProgressTrack percentage={percentage} size={size} className={tones[tone]} />
          {description ? <span className="text-caption-1-medium text-text-secondary">{description}</span> : null}
        </>
      )}
    </AriaMeter>
  );
}

"use client";

import {
  Children,
  createContext,
  isValidElement,
  useContext,
  useId,
  useLayoutEffect,
  useState,
} from "react";
import type { ComponentType, ReactElement, ReactNode } from "react";
import {
  Dialog as AriaDialog,
  DialogTrigger as AriaDialogTrigger,
  Heading as AriaHeading,
  Modal as AriaModal,
  ModalOverlay as AriaModalOverlay,
  OverlayTriggerStateContext,
  Pressable,
} from "react-aria-components";
import type { DialogRenderProps, DialogTriggerProps, ModalOverlayProps } from "react-aria-components";
import { RiErrorWarningLine } from "@remixicon/react";
import { Button } from "../buttons/button";
import { CloseButton } from "../buttons/close-button";
import { SpinnerGlyph } from "../spinner/spinner";
import { useDirection } from "../../foundations/direction/direction";
import { ScrollFade, useScrollFade } from "../../foundations/scroll-fade/scroll-fade";
import { useTemplateCopy } from "../../foundations/template-copy/template-copy";
import { cx, sortCx } from "@/lib/utils";

/**
 * Modal — a centred dialog over a dimmed page, built on React Aria's
 * ModalOverlay / Modal / Dialog: focus is trapped inside and returns to the
 * trigger on close, the page behind stops scrolling, and Escape or a press on
 * the backdrop dismisses it.
 *
 *   <ModalTrigger>
 *     <Button>Invite teammates</Button>
 *     <Modal>
 *       {({ close }) => (
 *         <>
 *           <ModalHeader title="Invite teammates" description="…" />
 *           <ModalBody>…</ModalBody>
 *           <ModalFooter>
 *             <Button variant="secondary" onClick={close}>Cancel</Button>
 *             <Button onClick={close}>Send invites</Button>
 *           </ModalFooter>
 *         </>
 *       )}
 *     </Modal>
 *   </ModalTrigger>
 *
 * Or control it from your own state with `isOpen` / `onOpenChange`, no trigger.
 * `AlertDialog` is the destructive-confirm preset: role="alertdialog", no
 * backdrop dismissal, focus starts on Cancel.
 *
 * Surface and motion follow Settings Modal: black/70 backdrop fading over
 * 300ms; the panel fades and sharpens from scale 0.85 and a 4px blur over
 * 300ms on the iOS sheet curve, and plays the same transition in reverse
 * before it unmounts. Reduced motion keeps the fade and drops the scale and
 * blur.
 */

type IconComponent = ComponentType<{ className?: string; "aria-hidden"?: boolean | "true" | "false" }>;

export type ModalSize = "sm" | "md" | "lg" | "xl";

const styles = sortCx({
  overlay: "group/modal fixed inset-x-0 top-0 z-100 flex h-(--visual-viewport-height) items-center justify-center p-4 sm:p-6",
  backdrop: [
    "absolute inset-0 bg-black/70",
    "transition-opacity duration-300 ease-out",
    "group-data-[entering]/modal:opacity-0 group-data-[exiting]/modal:opacity-0",
  ].join(" "),
  modal: [
    "relative flex max-h-full w-full flex-col outline-none",
    "transform-gpu transition-[opacity,scale,filter] duration-300 ease-[cubic-bezier(0.32,0.72,0,1)]",
    "data-[entering]:opacity-0 data-[exiting]:opacity-0",
    "motion-safe:data-[entering]:scale-[0.85] motion-safe:data-[entering]:blur-[4px]",
    "motion-safe:data-[exiting]:scale-[0.85] motion-safe:data-[exiting]:blur-[4px]",
  ].join(" "),
  dialog: [
    // overflow-CLIP, not hidden: a hidden box is still programmatically
    // scrollable, so focusing a field clipped by the body's scroller could
    // scroll the whole panel instead (see Settings Modal).
    "flex min-h-0 flex-col gap-4 overflow-clip py-6 outline-none",
    // Settings Modal's surface: page white in light mode, and in dark mode a
    // ground darker than the inputs and menus it holds, so they keep an edge.
    "rounded-3xl border border-separator-border bg-background-full shadow-xs",
  ].join(" "),
  size: {
    sm: "max-w-[400px]",
    md: "max-w-[480px]",
    lg: "max-w-[640px]",
    xl: "max-w-[800px]",
  },
  icon: {
    default: "bg-background-tertiary-default text-foreground-icon-secondary",
    danger: "bg-notification-error-background text-notification-error-foreground",
  },
});

/* ------------------------------------------------------------------ context */

interface ModalContextValue {
  descriptionId: string;
  setDescribed: (described: boolean) => void;
}

const ModalContext = createContext<ModalContextValue | null>(null);

/** Closes the surrounding Modal, Drawer, or AlertDialog. */
export function useModalClose() {
  const state = useContext(OverlayTriggerStateContext);
  return () => state?.close();
}

/* ------------------------------------------------------------------ trigger */

export interface ModalTriggerProps extends Omit<DialogTriggerProps, "children"> {
  /**
   * The trigger, then the Modal (or AlertDialog). The trigger can be any
   * JoyUI button: anything that forwards its ref and spreads its props.
   * React Aria's own Button already speaks to DialogTrigger; use that
   * directly instead of wrapping it here.
   */
  children: ReactNode;
}

export function ModalTrigger({ children, ...props }: ModalTriggerProps) {
  const [trigger, ...rest] = Children.toArray(children);
  return (
    <AriaDialogTrigger {...props}>
      {isValidElement(trigger) ? <Pressable>{trigger as ReactElement<Record<string, unknown>, string>}</Pressable> : trigger}
      {rest}
    </AriaDialogTrigger>
  );
}

/* -------------------------------------------------------------------- modal */

export interface ModalProps extends Omit<ModalOverlayProps, "children" | "className" | "style"> {
  /** Panel width: 400, 480 (default), 640, or 800px. */
  size?: ModalSize;
  /** `alertdialog` for confirmations that interrupt the user; see AlertDialog. */
  role?: "dialog" | "alertdialog";
  /** Accessible name when the content has no ModalHeader title. */
  "aria-label"?: string;
  /** Classes on the panel surface (the dialog). */
  className?: string;
  /** Classes on the full-screen overlay, e.g. to align the panel to the top. */
  overlayClassName?: string;
  children: ReactNode | ((renderProps: DialogRenderProps) => ReactNode);
}

export function Modal({
  size = "md",
  role,
  "aria-label": ariaLabel,
  className,
  overlayClassName,
  isDismissable = true,
  children,
  ...props
}: ModalProps) {
  const direction = useDirection();

  return (
    <AriaModalOverlay {...props} dir={direction} isDismissable={isDismissable} className={cx(styles.overlay, overlayClassName)}>
      <div aria-hidden className={styles.backdrop} />
      <AriaModal className={cx(styles.modal, styles.size[size])}>
        <ModalDialog role={role} aria-label={ariaLabel} className={className}>
          {children}
        </ModalDialog>
      </AriaModal>
    </AriaModalOverlay>
  );
}

export interface ModalDialogProps {
  role?: "dialog" | "alertdialog";
  "aria-label"?: string;
  /** Classes merged onto the panel surface. */
  className?: string;
  children: ReactNode | ((renderProps: DialogRenderProps) => ReactNode);
}

/**
 * The panel surface and dialog element shared by Modal and Drawer: the
 * ModalHeader title names it and the description is wired to
 * aria-describedby. Render it inside a React Aria Modal.
 */
export function ModalDialog({ role, "aria-label": ariaLabel, className, children }: ModalDialogProps) {
  const descriptionId = useId();
  const [described, setDescribed] = useState(false);

  return (
    <AriaDialog
      role={role}
      aria-label={ariaLabel}
      aria-describedby={described ? descriptionId : undefined}
      className={cx(styles.dialog, className)}
    >
      {(renderProps) => (
        <ModalContext.Provider value={{ descriptionId, setDescribed }}>
          {typeof children === "function" ? children(renderProps) : children}
        </ModalContext.Provider>
      )}
    </AriaDialog>
  );
}

/* ------------------------------------------------------------------ content */

export interface ModalHeaderProps {
  title: ReactNode;
  /** Supporting copy under the title; announced as the dialog's description. */
  description?: ReactNode;
  /** Remix Icon shown in a 40px circle beside the title. */
  icon?: IconComponent;
  /** `danger` tints the icon circle for destructive dialogs. */
  tone?: "default" | "danger";
  /** Show the dismiss button in the top corner. Default true. */
  showCloseButton?: boolean;
  closeLabel?: string;
  className?: string;
  /** Extra content under the description, e.g. tabs or a step indicator. */
  children?: ReactNode;
}

export function ModalHeader({
  title,
  description,
  icon: Icon,
  tone = "default",
  showCloseButton = true,
  closeLabel = "Close",
  className,
  children,
}: ModalHeaderProps) {
  const localize = useTemplateCopy();
  const context = useContext(ModalContext);
  const close = useModalClose();
  const setDescribed = context?.setDescribed;
  const hasDescription = description != null && description !== false;

  useLayoutEffect(() => {
    if (!hasDescription || !setDescribed) return;
    setDescribed(true);
    return () => setDescribed(false);
  }, [hasDescription, setDescribed]);

  // Icon sits beside the title (not stacked above) so AlertDialog / sheet
  // headers don't leave a large empty column on the trailing side.
  return localize(
    <div className={cx("flex shrink-0 items-start gap-3 px-6", className)}>
      {Icon ? (
        <span
          className={cx(
            "mt-0.5 flex size-10 shrink-0 items-center justify-center rounded-full",
            styles.icon[tone],
          )}
        >
          <Icon className="size-5" aria-hidden />
        </span>
      ) : null}
      <div className="flex min-w-0 flex-1 flex-col">
        <AriaHeading slot="title" className="text-title-3-medium text-text-primary">
          {title}
        </AriaHeading>
        {hasDescription ? (
          <p id={context?.descriptionId} className="mt-1 text-body-regular text-text-secondary">
            {description}
          </p>
        ) : null}
        {children}
      </div>
      {showCloseButton ? (
        <CloseButton
          size="sm"
          aria-label={closeLabel}
          onClick={close}
          className="-me-1 -mt-0.5 shrink-0 bg-transparent hover:bg-background-tertiary-default"
        />
      ) : null}
    </div>,
  );
}

export interface ModalBodyProps {
  /** Classes on the scrolling region (it carries px-6 by default). */
  className?: string;
  children: ReactNode;
}

/**
 * The content between the header and the footer. It scrolls on its own when
 * the panel reaches the viewport's height, with the header and footer held
 * in place and a progressive blur softening the top edge once scrolled.
 */
export function ModalBody({ className, children }: ModalBodyProps) {
  const fade = useScrollFade();
  return (
    // flex-1 fills a full-height panel (Drawer) and is inert in an
    // auto-height one: a 0% basis against an indefinite height acts as auto.
    <div className="relative flex min-h-0 flex-1 flex-col">
      <div
        onScroll={fade.onScroll}
        className={cx("min-h-0 flex-1 overflow-y-auto overscroll-contain px-6 py-1 text-body-regular text-text-secondary", className)}
      >
        {children}
      </div>
      <ScrollFade progress={fade.progress} surfaceClassName="from-background-full" />
    </div>
  );
}

export function ModalFooter({ className, children }: { className?: string; children: ReactNode }) {
  return (
    <div
      className={cx(
        // Stacked full-width on phones (primary action on top), a trailing
        // row from sm up. 8px extra over the dialog's gap-4 sets the actions
        // apart from the content.
        "mt-2 flex shrink-0 flex-col-reverse gap-2 px-6 sm:flex-row sm:items-center sm:justify-end",
        className,
      )}
    >
      {children}
    </div>
  );
}

/* ------------------------------------------------------------- alert dialog */

export interface AlertDialogProps
  extends Omit<ModalProps, "children" | "role" | "aria-label" | "isDismissable"> {
  title: ReactNode;
  description?: ReactNode;
  /** `danger` (default) pairs a tinted warning icon with a danger confirm button. */
  variant?: "danger" | "default";
  /** Leading icon; `false` hides it. Defaults to a warning glyph. */
  icon?: IconComponent | false;
  confirmLabel?: ReactNode;
  cancelLabel?: ReactNode;
  /**
   * Runs on confirm. Return a promise to keep the dialog open until it
   * settles: Cancel is disabled, and the confirm button turns busy with a
   * spinner and `pendingLabel`. It closes on success and stays open if the
   * promise rejects.
   */
  onConfirm?: () => void | Promise<unknown>;
  onCancel?: () => void;
  /** Confirm-button label while an async `onConfirm` runs. */
  pendingLabel?: ReactNode;
  /** Disables the confirm action, e.g. until a confirmation phrase is typed. */
  isConfirmDisabled?: boolean;
  /** Close on a backdrop press. Off by default: an alert asks for an answer. */
  isDismissable?: boolean;
  /** Extra content between the description and the actions. */
  children?: ReactNode;
}

/** Spinner sized for Button's icon slot, in the button's own text colour. */
function PendingGlyph({ className }: { className?: string }) {
  return <SpinnerGlyph size="sm" className={cx(className, "text-current")} />;
}

export function AlertDialog({
  title,
  description,
  variant = "danger",
  icon = RiErrorWarningLine,
  confirmLabel = "Confirm",
  cancelLabel = "Cancel",
  onConfirm,
  onCancel,
  pendingLabel,
  isConfirmDisabled = false,
  isDismissable = false,
  size = "sm",
  children,
  ...props
}: AlertDialogProps) {
  const localize = useTemplateCopy();
  const [pending, setPending] = useState(false);

  return localize(
    <Modal
      {...props}
      size={size}
      role="alertdialog"
      isDismissable={isDismissable && !pending}
      isKeyboardDismissDisabled={pending}
    >
      {({ close }) => {
        const confirm = async () => {
          if (pending) return;
          const result = onConfirm?.();
          if (!result || typeof result.then !== "function") return close();
          setPending(true);
          try {
            await result;
            close();
          } catch {
            // Stay open: the caller reports the failure.
          } finally {
            setPending(false);
          }
        };

        return (
          <>
            <ModalHeader
              title={title}
              description={description}
              icon={icon || undefined}
              tone={variant === "danger" ? "danger" : "default"}
              showCloseButton={false}
            />
            {children ? <ModalBody>{children}</ModalBody> : null}
            <ModalFooter>
              <Button
                variant="secondary"
                autoFocus
                disabled={pending}
                onClick={() => {
                  onCancel?.();
                  close();
                }}
              >
                {cancelLabel}
              </Button>
              <Button
                variant={variant === "danger" ? "danger" : "primary"}
                // Busy rather than disabled while pending: the button keeps
                // its colour, so the spinner on it stays legible.
                disabled={isConfirmDisabled}
                aria-busy={pending || undefined}
                leadingIcon={pending ? PendingGlyph : undefined}
                onClick={confirm}
              >
                {pending && pendingLabel ? pendingLabel : confirmLabel}
              </Button>
            </ModalFooter>
          </>
        );
