   * focus is in a toast stack. The countdown resumes where it stopped.
   */
  paused?: boolean;
  /** Dismiss from outside: plays the exit animation, then calls `onDismiss`. */
  dismissed?: boolean;
  /** Optional entrance delay in seconds. */
  introDelay?: number;
