"use client";

import { useTemplateCopy } from "../../foundations/template-copy/template-copy";

import { useEffect, useRef, useState } from "react";
import { RiArrowLeftLine, RiArrowRightLine } from "@remixicon/react";
import { Button } from "../buttons/button";
import { cx } from "@/lib/utils";

/**
 * Pagination — designed to match the Board UI dashboard style (no dedicated
 * Figma frame yet, so it reuses shipped tokens/components):
 *   - Previous / Next use the secondary small `Button` (same as the Recent
 *     hires card pager) with arrow icons.
 *   - Page numbers are 32×32 (radius/lg) cells. Active cell borrows the
 *     secondary-button surface (white + border/button/default + shadow/xs);
 *     inactive cells are ghost with a secondary-hover background on hover.
 *   - Overflow collapses to leading/trailing dots around a sibling window.
 *
 * Below `COMPACT_WIDTH`, a `ResizeObserver` on the nav switches to a compact
 * layout — icon-only Previous/Next and `siblingCount` clamped to 0 — so the
 * row never overflows a narrow container instead of clipping mid-label.
 *
 * Controlled: pass `page`, `totalPages`, and `onChange`.
 */

export interface PaginationProps {
  page: number;
  totalPages: number;
  onChange: (page: number) => void;
  /** Page numbers shown on each side of the current page. Default 1. */
  siblingCount?: number;
  className?: string;
  /** Visible and accessible navigation labels for the application's locale. */
  previousLabel?: string;
  nextLabel?: string;
  "aria-label"?: string;
}

const DOTS = "dots";

function range(start: number, end: number): number[] {
  return Array.from({ length: end - start + 1 }, (_, i) => start + i);
}

function paginationRange(
  current: number,
  total: number,
  sibling: number,
): (number | typeof DOTS)[] {
  // first + last + current + 2*sibling + 2 dots
  const totalPageNumbers = sibling * 2 + 5;
  if (totalPageNumbers >= total) return range(1, total);

  const leftSibling = Math.max(current - sibling, 1);
  const rightSibling = Math.min(current + sibling, total);
  const showLeftDots = leftSibling > 2;
  const showRightDots = rightSibling < total - 2;

  if (!showLeftDots && showRightDots) {
    return [...range(1, 3 + 2 * sibling), DOTS, total];
  }
  if (showLeftDots && !showRightDots) {
    return [1, DOTS, ...range(total - (2 + 2 * sibling), total)];
  }
  return [1, DOTS, ...range(leftSibling, rightSibling), DOTS, total];
}

// No transition on the cells: animating background/shadow/color makes the
// previously-active number visibly fade out ("flicker") on every page change.
const cell = "flex size-8 shrink-0 items-center justify-center rounded-lg text-body-medium";

/** Below this nav width, Previous/Next drop their labels and siblingCount
 *  clamps to 0 — the full-label, full-sibling layout starts clipping
 *  somewhere around 380–420px depending on totalPages' digit count. */
const COMPACT_WIDTH = 420;

function useIsCompact() {
  const ref = useRef<HTMLElement>(null);
  const [isCompact, setIsCompact] = useState(false);

  useEffect(() => {
    const el = ref.current;
    if (!el) return;
    const observer = new ResizeObserver(([entry]) => {
      setIsCompact(entry.contentRect.width < COMPACT_WIDTH);
    });
    observer.observe(el);
    return () => observer.disconnect();
  }, []);

  return [ref, isCompact] as const;
}

export function Pagination({
  page,
  totalPages,
  onChange,
  siblingCount = 1,
  className,
  previousLabel = "Previous",
  nextLabel = "Next",
  "aria-label": ariaLabel = "Pagination",
}: PaginationProps) {
  const localize = useTemplateCopy();
  const [navRef, isCompact] = useIsCompact();
  const safeTotal = Number.isFinite(totalPages) ? Math.max(0, Math.floor(totalPages)) : 0;
  const safePage = Number.isFinite(page) ? Math.min(Math.max(1, Math.floor(page)), Math.max(safeTotal, 1)) : 1;
  if (safeTotal <= 1) return null;
  const pages = paginationRange(safePage, safeTotal, isCompact ? 0 : siblingCount);

  return localize((
    <nav
      ref={navRef}
      aria-label={ariaLabel}
      className={cx("flex w-full items-center justify-between gap-2", className)}
    >
      <Button
        variant="secondary"
        size="small"
        iconOnly={isCompact}
        leadingIcon={RiArrowLeftLine}
        aria-label={isCompact ? previousLabel : undefined}
        disabled={safePage <= 1}
        onClick={() => onChange(safePage - 1)}
      >
        {isCompact ? undefined : previousLabel}
      </Button>

      <ul className="flex min-w-0 items-center gap-0.5">
        {pages.map((item, i) =>
          item === DOTS ? (
            <li
              key={`dots-${i}`}
              aria-hidden
              className={cx(cell, "text-text-tertiary")}
            >
              …
            </li>
          ) : (
            <li key={`page-${item}-${i}`}>
              <button
                type="button"
                aria-label={`Go to page ${item}`}
                aria-current={item === safePage ? "page" : undefined}
                onClick={() => onChange(item)}
                className={cx(
                  cell,
                  "cursor-pointer outline-none focus-visible:ring-2 focus-visible:ring-offset-2 focus-visible:ring-border-focus-ring",
                  item === safePage
                    ? "border border-border-button-default bg-background-primary-default text-text-primary shadow-xs"
                    : "text-text-secondary hover:bg-background-secondary-hover hover:text-text-primary",
                )}
              >
                {item}
              </button>
            </li>
          ),
        )}
      </ul>

      <Button
        variant="secondary"
        size="small"
        iconOnly={isCompact}
        leadingIcon={isCompact ? RiArrowRightLine : undefined}
        trailingIcon={isCompact ? undefined : RiArrowRightLine}
        aria-label={isCompact ? nextLabel : undefined}
        disabled={safePage >= safeTotal}
        onClick={() => onChange(safePage + 1)}
      >
        {isCompact ? undefined : nextLabel}
      </Button>
    </nav>
  ));
}

"use client";

import type { HTMLAttributes, ReactNode, Ref } from "react";
import { cx, sortCx } from "@/lib/utils";

/**
 * Segmented password strength meter — Bencho Password strength pattern,
 * coloured with the same semantic tones as Meter / Notification.
 *
 *   <PasswordStrength value={password} />
 */

export type PasswordStrengthLevel = 0 | 1 | 2 | 3 | 4;

export interface PasswordStrengthProps
  extends Omit<HTMLAttributes<HTMLDivElement>, "children"> {
  /** Raw password (scored client-side; never send elsewhere). */
  value?: string;
  /** Override scored level 0–4. */
  level?: PasswordStrengthLevel;
  /** Show label under the bars. Default true. */
  showLabel?: boolean;
  labels?: [string, string, string, string, string];
  ref?: Ref<HTMLDivElement>;
}

const DEFAULT_LABELS: [string, string, string, string, string] = [
  "输入密码",
  "弱",
  "一般",
  "较强",
  "很强",
];

/** Track + fill — ProgressTrack rail, Meter semantic fills. */
const barTone = sortCx({
  idle: "bg-border-button-default",
  1: "bg-notification-error-foreground",
  2: "bg-chart-8-active",
  3: "bg-status-yellow-text",
  4: "bg-notification-success-foreground",
});

const labelTone = sortCx({
  0: "text-text-secondary",
  1: "text-notification-error-foreground",
  2: "text-chart-8-active",
  3: "text-status-yellow-text",
  4: "text-notification-success-foreground",
});

/** Lightweight heuristic — length + character classes. */
export function scorePassword(value: string): PasswordStrengthLevel {
  if (!value) return 0;
  let score = 0;
  if (value.length >= 8) score += 1;
  if (value.length >= 12) score += 1;
  if (/[a-z]/.test(value) && /[A-Z]/.test(value)) score += 1;
  if (/\d/.test(value)) score += 1;
  if (/[^A-Za-z0-9]/.test(value)) score += 1;
  if (score <= 1) return value.length > 0 ? 1 : 0;
  if (score === 2) return 2;
  if (score === 3) return 3;
  return 4;
}

export function PasswordStrength({
  value = "",
  level,
  showLabel = true,
  labels = DEFAULT_LABELS,
  className,
  ref,
  ...props
}: PasswordStrengthProps) {
  const resolved = level ?? scorePassword(value);
  const label: ReactNode = labels[resolved] ?? labels[0];
  const fillKey = (resolved === 0 ? 1 : resolved) as 1 | 2 | 3 | 4;

  return (
    <div ref={ref} className={cx("flex w-full flex-col gap-1.5", className)} {...props}>
      <div
        className="flex gap-1"
        role="meter"
        aria-valuemin={0}
        aria-valuemax={4}
        aria-valuenow={resolved}
        aria-label="密码强度"
      >
        {([1, 2, 3, 4] as const).map((i) => (
          <span
            key={i}
            aria-hidden
            className={cx(
              // Progress `md` track height.
              "h-1.5 flex-1 rounded-full transition-colors duration-200 ease-[cubic-bezier(0.22,1,0.36,1)]",
              resolved >= i ? barTone[fillKey] : barTone.idle,
            )}
          />
        ))}
      </div>
      {showLabel ? (
        <span className={cx("text-caption-1-medium", labelTone[resolved])}>{label}</span>
      ) : null}
    </div>
  );
}

