 *   </PopoverTrigger>
 *
 * Like Select and Dropdown it is non-modal: React Aria's modal popovers lock
 * page scroll, and the reflow shunts sticky layout. Outside-press dismissal
 * is restored with useDismissOnOutsidePress, and pressing the trigger again
 * closes it.
 *
 * Surface: the composer permission popover's recipe, radius 20 with p-1.5,
 * 1px border/button/default, background/primary, shadow/dropdown. The
 * optional arrow is Tooltip's caret in the same colours. Motion is the menu
 * family's: 150ms fade, scale 0.95 and 2px blur in and out, grown from the
 * point nearest the trigger. Reduced motion keeps only the fade.
 */

interface PopoverContextValue {
  popoverRef: RefObject<HTMLElement | null>;
}

const PopoverContext = createContext<PopoverContextValue | null>(null);

export interface PopoverTriggerProps {
  isOpen?: boolean;
  defaultOpen?: boolean;
  onOpenChange?: (isOpen: boolean) => void;
  /**
   * The trigger, then the Popover. The trigger can be any JoyUI button:
   * anything that forwards its ref and spreads its props.
   */
  children: ReactNode;
}

export function PopoverTrigger({ isOpen: controlledOpen, defaultOpen = false, onOpenChange, children }: PopoverTriggerProps) {
  const triggerRef = useRef<HTMLElement>(null);
  const popoverRef = useRef<HTMLElement>(null);
  const [uncontrolledOpen, setUncontrolledOpen] = useState(defaultOpen);
  const isOpen = controlledOpen ?? uncontrolledOpen;
  const setOpen = (next: boolean) => {
    setUncontrolledOpen(next);
    onOpenChange?.(next);
  };

  useDismissOnOutsidePress(isOpen, () => setOpen(false), [triggerRef, popoverRef]);
  // Pressing the trigger while open closes the popover instead of reopening it.
  const allowOpenChange = useTriggerToggle(isOpen, triggerRef);

  const [trigger, ...rest] = Children.toArray(children);
  return (
    <PopoverContext.Provider value={{ popoverRef }}>
      <AriaDialogTrigger isOpen={isOpen} onOpenChange={(next) => allowOpenChange(next) && setOpen(next)}>
        {isValidElement(trigger) ? (
          <Pressable ref={triggerRef}>{trigger as ReactElement<Record<string, unknown>, string>}</Pressable>
        ) : (
          trigger
        )}
        {rest}
      </AriaDialogTrigger>
    </PopoverContext.Provider>
  );
}

export interface PopoverProps
  extends Pick<AriaPopoverProps, "placement" | "offset" | "crossOffset" | "shouldFlip" | "containerPadding" | "triggerRef" | "isOpen" | "onOpenChange"> {
  /** Draw a caret pointing at the trigger. */
  showArrow?: boolean;
  /** Accessible name when the content has no PopoverHeader title. */
  "aria-label"?: string;
  /** Classes on the surface, e.g. a width (default 320px). */
  className?: string;
  /** Classes on the inner dialog; `p-0` suits menu-like rows that pad themselves. */
  dialogClassName?: string;
  children: ReactNode | ((renderProps: DialogRenderProps) => ReactNode);
}

export function Popover({
  showArrow = false,
  placement = "bottom",
  offset,
  "aria-label": ariaLabel,
  className,
  dialogClassName,
  children,
  ...props
}: PopoverProps) {
  const context = useContext(PopoverContext);
  const direction = useDirection();

  return (
    <AriaPopover
      {...props}
      ref={context?.popoverRef}
      dir={direction}
      // Standalone (triggerRef + isOpen) popovers keep React Aria's own
      // dismissal; inside PopoverTrigger the trigger restores it.
      isNonModal={context != null}
      placement={placement}
      offset={offset ?? (showArrow ? 10 : 8)}
      className={cx(
        "z-110 w-80 max-w-[calc(100vw-32px)]",
        "rounded-[20px] border border-border-button-default bg-background-primary-default p-1.5 shadow-dropdown dark:bg-background-quaternary-default",
        "origin-(--trigger-anchor-point) transition-[opacity,scale,filter] duration-150 ease-out",
        "data-[entering]:opacity-0 data-[exiting]:opacity-0",
        "motion-safe:data-[entering]:scale-95 motion-safe:data-[entering]:blur-[2px]",
        "motion-safe:data-[exiting]:scale-95 motion-safe:data-[exiting]:blur-[2px]",
        className,
      )}
    >
      {showArrow ? (
        <AriaOverlayArrow>
          {({ placement: side }) => {
            const caret = TOOLTIP_CARETS[side as keyof typeof TOOLTIP_CARETS] ?? TOOLTIP_CARETS.top;
            return (
              <svg
                width={caret.width}
                height={caret.height}
                viewBox={`0 0 ${caret.width} ${caret.height}`}
                className="block overflow-visible fill-background-primary-default stroke-border-button-default"
                style={{ filter: `drop-shadow(${caret.shadow} rgb(0 0 0 / 0.05))` }}
              >
                <path d={caret.path} />
              </svg>
            );
          }}
        </AriaOverlayArrow>
      ) : null}
      <AriaDialog aria-label={ariaLabel} className={cx("flex flex-col gap-3 p-2.5 outline-none", dialogClassName)}>
        {children}
      </AriaDialog>
    </AriaPopover>
  );
}

export interface PopoverHeaderProps {
  title: ReactNode;
  description?: ReactNode;
  className?: string;
}

/** Title and supporting copy; the title names the popover's dialog. */
export function PopoverHeader({ title, description, className }: PopoverHeaderProps) {
  return (
    <div className={cx("flex flex-col gap-0.5", className)}>
      <AriaHeading slot="title" className="text-body-medium text-text-primary">
        {title}
      </AriaHeading>
      {description ? <p className="text-body-2-regular text-text-secondary">{description}</p> : null}
    </div>
  );
}

/** A trailing row of actions. */
export function PopoverFooter({ className, children }: { className?: string; children: ReactNode }) {
  return <div className={cx("flex items-center justify-end gap-2", className)}>{children}</div>;
}

"use client";

import type { ReactNode } from "react";
import { ProgressBar as AriaProgressBar } from "react-aria-components";
import type { ProgressBarProps as AriaProgressBarProps } from "react-aria-components";
import { Label } from "../input/label";
import { SpinnerGlyph } from "../spinner/spinner";
import { useDirection } from "../../foundations/direction/direction";
import { cx, sortCx } from "@/lib/utils";

/**
 * Progress — how far along a task is: an upload, an import, an onboarding
 * checklist. Built on React Aria's ProgressBar, so it is announced with its
 * label and value, and formats the value for the locale.
 *
 *   <ProgressBar label="Uploading Q3-report.pdf" value={64} />
 *   <ProgressBar label="Preparing export" isIndeterminate />
 *   <ProgressCircle value={64} aria-label="Upload" />
 *
 * The bar is the agent limits card's rounded rail with an accent fill, on
 * File Upload's track colour. The fill moves by translate rather than width, so it eases
 * to each new value on the compositor (500ms, the card's ease-out).
 *
 * Indeterminate, a band of light sweeps the track, drawn like Spinner and
 * Composer Loader: a crisp core with a rounded head, a tight glow and a wide
 * bloom that bleed a few pixels past the rail, the soft layers pulled back
 * so the sharp head leads. It runs right to left in RTL. The ring's
 * indeterminate state is Spinner's orbiting light. Reduced motion slows the
 * sweep rather than stopping it.
 */

export type ProgressSize = "sm" | "md" | "lg";

const EASE = "ease-[cubic-bezier(0.22,1,0.36,1)]";

const styles = sortCx({
  track: {
    sm: "h-1",
    md: "h-1.5",
    lg: "h-2",
  },
  ring: {
    sm: { box: 16, line: 2, spinner: "sm" },
    md: { box: 24, line: 2.5, spinner: "lg" },
    lg: { box: 32, line: 3, spinner: "xl" },
  },
});

/* -------------------------------------------------------------------- bar */

export interface ProgressBarProps extends Omit<AriaProgressBarProps, "children" | "className"> {
  label?: ReactNode;
  /** Show the formatted value at the end of the label row. Default: shown with a label. */
  showValueLabel?: boolean;
  /** Helper text under the bar. */
  description?: ReactNode;
  /** Track thickness: 4, 6 (default), or 8px. */
  size?: ProgressSize;
  className?: string;
}

/** The sweeping band of light for an indeterminate bar. */
function Sweep() {
  return (
    // The clip keeps the light inside the rail's length but lets the glow
    // and bloom bleed past its thickness.
    <span aria-hidden className="absolute inset-0 [clip-path:inset(-8px_0_round_9999px)]">
      <span
        className={cx(
          "absolute inset-y-0 left-0 w-2/5",
          "animate-[bui-progress-sweep_1.6s_cubic-bezier(0.65,0,0.35,1)_infinite]",
          "rtl:[animation-direction:reverse] motion-reduce:[animation-duration:4s]",
        )}
      >
        <span className="absolute inset-0 rtl:-scale-x-100">
          <span className="absolute -inset-y-[5px] right-[10px] left-0 rounded-full bg-linear-to-r from-transparent to-current opacity-30 blur-[5px]" />
          <span className="absolute -inset-y-[1.5px] right-[4px] left-[25%] rounded-full bg-linear-to-r from-transparent to-current opacity-60 blur-[2px]" />
          <span className="absolute inset-y-0 right-0 left-[35%] rounded-full bg-linear-to-r from-transparent to-current" />
        </span>
      </span>
    </span>
  );
}

export interface ProgressTrackProps {
  /** 0 to 100. */
  percentage: number;
  size?: ProgressSize;
  /** Draw the indeterminate sweep instead of a fill. */
  isIndeterminate?: boolean;
  /** Colour of the fill, from the text colour. Default accent. */
  className?: string;
}

/** The rail and its fill, shared by ProgressBar and Meter. */
export function ProgressTrack({ percentage, size = "md", isIndeterminate = false, className }: ProgressTrackProps) {
  const direction = useDirection();
  return (
    // The rail is File Upload's ring track colour, which keeps an edge on
    // every surface in both themes (chart-track matches dark cards).
    <div className={cx("relative w-full rounded-full bg-border-button-default text-accent-500", styles.track[size], className)}>
      {isIndeterminate ? (
        <Sweep />
      ) : (
        <span className="absolute inset-0 overflow-hidden rounded-full">
          <span
            className={cx("absolute inset-0 rounded-full bg-current transition-[translate] duration-500 motion-reduce:transition-none", EASE)}
            style={{ translate: `${(direction === "rtl" ? 1 : -1) * (100 - Math.min(100, Math.max(0, percentage)))}% 0` }}
          />
        </span>
      )}
    </div>
  );
}

export function ProgressBar({
  label,
  showValueLabel,
  description,
  size = "md",
  isIndeterminate,
  className,
  ...props
}: ProgressBarProps) {
  const showValue = showValueLabel ?? (label != null && !isIndeterminate);

  return (
    <AriaProgressBar {...props} isIndeterminate={isIndeterminate} className={cx("flex w-full flex-col gap-1.5", className)}>
      {({ percentage = 0, valueText }) => (
        <>
          {label != null || showValue ? (
            <div className="flex items-baseline justify-between gap-3">
              {label != null ? <Label className="min-w-0 truncate">{label}</Label> : <span />}
              {showValue ? (
                <span className="shrink-0 text-body-medium text-text-secondary tabular-nums">{valueText}</span>
              ) : null}
            </div>
          ) : null}
          <ProgressTrack percentage={percentage} size={size} isIndeterminate={isIndeterminate} />
          {description ? <span className="text-caption-1-medium text-text-secondary">{description}</span> : null}
        </>
      )}
    </AriaProgressBar>
  );
}

/* ------------------------------------------------------------------- ring */

export interface ProgressCircleProps extends Omit<AriaProgressBarProps, "children" | "className"> {
  /** 16, 24 (default), or 32px. */
  size?: ProgressSize;
  /** Colour of the arc, from the text colour. Default accent. */
  className?: string;
}

/**
 * A ring for tight spots: a file tile, a table cell, a checklist header. Name
 * it with `aria-label`. The arc draws by stroke-dashoffset, a paint-only
 * change on a few pixels of SVG, eased like the bar.
 */
export function ProgressCircle({ size = "md", isIndeterminate, className, ...props }: ProgressCircleProps) {
  const { box, line, spinner } = styles.ring[size];
  const radius = (box - line) / 2;
  const circumference = 2 * Math.PI * radius;

  return (
    <AriaProgressBar {...props} isIndeterminate={isIndeterminate} className="inline-flex shrink-0">
      {({ percentage = 0 }) =>
        isIndeterminate ? (
          <SpinnerGlyph size={spinner as "sm" | "lg" | "xl"} className={className} />
        ) : (
          <svg
            aria-hidden
            width={box}
            height={box}
            viewBox={`0 0 ${box} ${box}`}
            className={cx("-rotate-90 text-accent-500", className)}
          >
            <circle cx={box / 2} cy={box / 2} r={radius} fill="none" strokeWidth={line} className="stroke-border-button-default" />
            <circle
              cx={box / 2}
              cy={box / 2}
              r={radius}
              fill="none"
              stroke="currentColor"
              strokeWidth={line}
              strokeLinecap="round"
              strokeDasharray={circumference}
              strokeDashoffset={circumference * (1 - percentage / 100)}
              className={cx("transition-[stroke-dashoffset] duration-500 motion-reduce:transition-none", EASE)}
            />
          </svg>
        )
      }
    </AriaProgressBar>
  );
}

