import type { HTMLAttributes, Ref } from "react";
import { RiStarFill, RiStarLine } from "@remixicon/react";
import { cx, sortCx } from "@/lib/utils";

/**
 * Read-only or interactive star rating. Discovery grids and review cards.
 */

export interface RatingProps extends Omit<HTMLAttributes<HTMLDivElement>, "onChange"> {
  /** Current value (0 … max). */
  value?: number;
  max?: number;
  /** Allow clicking a star to change value. */
  interactive?: boolean;
  size?: "sm" | "md";
  /** Accessible name, e.g. "Rating". */
  "aria-label"?: string;
  onChange?: (value: number) => void;
  ref?: Ref<HTMLDivElement>;
}

const styles = sortCx({
  star: {
    sm: "size-3.5",
    md: "size-4",
  },
});

export function Rating({
  value = 0,
  max = 5,
  interactive = false,
  size = "md",
  "aria-label": ariaLabel = "Rating",
  onChange,
  className,
  ref,
  ...props
}: RatingProps) {
  const clamped = Math.max(0, Math.min(max, value));
  return (
    <div
      ref={ref}
      role={interactive ? "radiogroup" : "img"}
      aria-label={ariaLabel}
      className={cx("inline-flex items-center gap-0.5 text-status-yellow-text", className)}
      {...props}
    >
      {Array.from({ length: max }, (_, i) => {
        const n = i + 1;
        const filled = n <= Math.round(clamped);
        const Icon = filled ? RiStarFill : RiStarLine;
        if (!interactive) {
          return <Icon key={n} className={styles.star[size]} aria-hidden />;
        }
        return (
          <button
            key={n}
            type="button"
            role="radio"
            aria-checked={n === Math.round(clamped)}
            aria-label={`${n}`}
            className="rounded-sm outline-none focus-visible:ring-2 focus-visible:ring-border-focus-ring"
            onClick={() => onChange?.(n)}
          >
            <Icon className={styles.star[size]} aria-hidden />
          </button>
        );
      })}
    </div>
  );
}

"use client";

import { useState, type HTMLAttributes, type Ref } from "react";
import { cx, sortCx } from "@/lib/utils";

/**
 * Emoji rating scale — for NPS / mood feedback where stars feel too formal.
 *
 *   <RatingEmoji value={4} interactive onChange={setValue} aria-label="满意度" />
 */

const DEFAULT_EMOJIS = ["😠", "😕", "😐", "🙂", "🤩"] as const;

export interface RatingEmojiProps
  extends Omit<HTMLAttributes<HTMLDivElement>, "onChange"> {
  /** Current value (1 … emojis.length). 0 / undefined = none selected. */
  value?: number;
  defaultValue?: number;
  /** Override the emoji sequence (length becomes max). */
  emojis?: readonly string[];
  interactive?: boolean;
  size?: "sm" | "md" | "lg";
  "aria-label"?: string;
  onChange?: (value: number) => void;
  ref?: Ref<HTMLDivElement>;
}

const styles = sortCx({
  emoji: {
    sm: "text-title-3-medium size-8",
    md: "text-title-2-medium size-10",
    lg: "text-title-1-medium size-12",
  },
});

export function RatingEmoji({
  value,
  defaultValue = 0,
  emojis = DEFAULT_EMOJIS,
  interactive = false,
  size = "md",
  "aria-label": ariaLabel = "表情评分",
  onChange,
  className,
  ref,
  ...props
}: RatingEmojiProps) {
  const [uncontrolled, setUncontrolled] = useState(defaultValue);
  const current = value ?? uncontrolled;
  const clamped = Math.max(0, Math.min(emojis.length, current));

  const select = (n: number) => {
    if (value === undefined) setUncontrolled(n);
    onChange?.(n);
  };

  return (
    <div
      ref={ref}
      role={interactive ? "radiogroup" : "img"}
      aria-label={ariaLabel}
      className={cx("inline-flex items-center gap-1.5", className)}
      {...props}
    >
      {emojis.map((emoji, index) => {
        const n = index + 1;
        const selected = n === clamped;
        const dimmed = clamped > 0 && !selected;

        if (!interactive) {
          return (
            <span
              key={n}
              aria-hidden
              className={cx(
                "inline-flex items-center justify-center transition-opacity",
                styles.emoji[size],
                dimmed && "opacity-55",
              )}
            >
              {emoji}
            </span>
          );
        }

        return (
          <button
            key={n}
            type="button"
            role="radio"
            aria-checked={selected}
            aria-label={`${n}`}
            className={cx(
              "inline-flex items-center justify-center rounded-xl outline-none transition-[transform,opacity,background-color]",
              "hover:bg-background-secondary-default focus-visible:ring-2 focus-visible:ring-border-focus-ring",
              styles.emoji[size],
              dimmed && "opacity-55",
              selected && "scale-110 bg-background-secondary-default",
            )}
            onClick={() => select(n)}
          >
            <span aria-hidden>{emoji}</span>
          </button>
        );
      })}
    </div>
  );
}

"use client";

import { useEffect, useMemo, useState, type Ref, type TimeHTMLAttributes } from "react";
import { cx } from "@/lib/utils";

/**
 * Live relative timestamp for logs, feeds, and activity rows.
 * Uses `Intl.RelativeTimeFormat` — no dayjs in the component tree.
 *
 *   <RelativeTime date={row.createdAt} />
 */

export type RelativeTimeDate = string | number | Date;

export interface RelativeTimeProps
  extends Omit<TimeHTMLAttributes<HTMLTimeElement>, "dateTime" | "children"> {
  date: RelativeTimeDate;
  /** BCP 47 locale. Defaults to runtime language. */
  locale?: string;
  /** Refresh interval in ms. Default 60s. */
  refreshMs?: number;
  /** Absolute tooltip / title. Default true. */
  showAbsoluteTitle?: boolean;
  ref?: Ref<HTMLTimeElement>;
}

const DIVISIONS: { amount: number; unit: Intl.RelativeTimeFormatUnit }[] = [
  { amount: 60, unit: "second" },
  { amount: 60, unit: "minute" },
  { amount: 24, unit: "hour" },
  { amount: 7, unit: "day" },
  { amount: 4.34524, unit: "week" },
  { amount: 12, unit: "month" },
  { amount: Number.POSITIVE_INFINITY, unit: "year" },
];

function toDate(value: RelativeTimeDate): Date {
  return value instanceof Date ? value : new Date(value);
}

export function formatRelativeTime(
  date: RelativeTimeDate,
  locale?: string,
  now = Date.now(),
): string {
  const d = toDate(date);
  if (Number.isNaN(d.getTime())) return "";
  let duration = (d.getTime() - now) / 1000;
  const rtf = new Intl.RelativeTimeFormat(locale, { numeric: "auto" });
  for (const division of DIVISIONS) {
    if (Math.abs(duration) < division.amount) {
      return rtf.format(Math.round(duration), division.unit);
    }
    duration /= division.amount;
  }
  return rtf.format(Math.round(duration), "year");
}

export function RelativeTime({
  date,
  locale,
  refreshMs = 60_000,
  showAbsoluteTitle = true,
  className,
  ref,
  ...props
}: RelativeTimeProps) {
  const [now, setNow] = useState(() => Date.now());
  const resolvedLocale =
    locale ?? (typeof navigator !== "undefined" ? navigator.language : "zh-CN");

  useEffect(() => {
    const id = window.setInterval(() => setNow(Date.now()), refreshMs);
    return () => window.clearInterval(id);
  }, [refreshMs]);

  const d = useMemo(() => toDate(date), [date]);
  const label = formatRelativeTime(d, resolvedLocale, now);
  const absolute = Number.isNaN(d.getTime()) ? undefined : d.toLocaleString(resolvedLocale);

  return (
    <time
      ref={ref}
      dateTime={Number.isNaN(d.getTime()) ? undefined : d.toISOString()}
      title={showAbsoluteTitle ? absolute : props.title}
      className={cx("text-caption-1-medium text-text-secondary tabular-nums", className)}
      {...props}
    >
      {label || absolute || "—"}
    </time>
  );
}

"use client";

import {
  useEffect,
  useRef,
  useState,
  type CSSProperties,
  type HTMLAttributes,
  type ReactNode,
  type Ref,
} from "react";
import { cx, sortCx } from "@/lib/utils";

/**
 * Mount / scroll reveal — fade + slight rise, Progress ease. Respects
 * prefers-reduced-motion (instant show).
 *
 *   <Reveal><Card>…</Card></Reveal>
 */

export type RevealFrom = "up" | "down" | "left" | "right" | "none";

export interface RevealProps extends HTMLAttributes<HTMLDivElement> {
  children: ReactNode;
  /** Delay before animating in (ms). */
  delay?: number;
  /** Animation duration (ms). */
  duration?: number;
  from?: RevealFrom;
  /** Distance of the entrance offset (px). */
  offset?: number;
  /** Observe once and stay visible. Default true. */
  once?: boolean;
  /** Root margin for IntersectionObserver. */
  rootMargin?: string;
  ref?: Ref<HTMLDivElement>;
}

const styles = sortCx({
  root: "bui-reveal",
  visible: "bui-reveal-visible",
});

export function Reveal({
  children,
  delay = 0,
  duration = 480,
  from = "up",
  offset = 12,
  once = true,
  rootMargin = "0px 0px -8% 0px",
  className,
  style,
  ref,
  ...props
}: RevealProps) {
  const localRef = useRef<HTMLDivElement | null>(null);
  const [visible, setVisible] = useState(false);

  const setRefs = (node: HTMLDivElement | null) => {
    localRef.current = node;
    if (typeof ref === "function") ref(node);
    else if (ref) ref.current = node;
  };

  useEffect(() => {
    const el = localRef.current;
    if (!el) return;

    const reduce =
      typeof window !== "undefined" &&
      window.matchMedia("(prefers-reduced-motion: reduce)").matches;
    if (reduce) {
      setVisible(true);
      return;
    }

    const io = new IntersectionObserver(
      ([entry]) => {
        if (entry?.isIntersecting) {
          setVisible(true);
          if (once) io.disconnect();
        } else if (!once) {
          setVisible(false);
        }
      },
      { rootMargin, threshold: 0.12 },
    );
    io.observe(el);
    return () => io.disconnect();
  }, [once, rootMargin]);

  const axis: CSSProperties = (() => {
    switch (from) {
      case "up":
        return { "--bui-reveal-x": "0px", "--bui-reveal-y": `${offset}px` } as CSSProperties;
      case "down":
        return { "--bui-reveal-x": "0px", "--bui-reveal-y": `-${offset}px` } as CSSProperties;
      case "left":
        return { "--bui-reveal-x": `${offset}px`, "--bui-reveal-y": "0px" } as CSSProperties;
      case "right":
        return { "--bui-reveal-x": `-${offset}px`, "--bui-reveal-y": "0px" } as CSSProperties;
      default:
        return { "--bui-reveal-x": "0px", "--bui-reveal-y": "0px" } as CSSProperties;
    }
  })();

  return (
    <div
      ref={setRefs}
      className={cx(styles.root, visible && styles.visible, className)}
      style={
        {
          ...axis,
          "--bui-reveal-delay": `${delay}ms`,
          "--bui-reveal-duration": `${duration}ms`,
          ...style,
        } as CSSProperties
      }
      {...props}
    >
      {children}
    </div>
  );
}

"use client";

import {
  Children,
  cloneElement,
  isValidElement,
  type HTMLAttributes,
  type ReactElement,
  type ReactNode,
  type Ref,
} from "react";
import { Reveal, type RevealFrom, type RevealProps } from "../reveal/reveal";
import { cx } from "@/lib/utils";

/**
 * Staggered reveal for a list of children — each child mounts with an
 * incremental delay. Prefer this over hand-rolling `delay` on every Reveal.
 *
 *   <RevealStagger stagger={80}>
 *     <Card>一</Card>
 *     <Card>二</Card>
 *     <Card>三</Card>
 *   </RevealStagger>
 */

export interface RevealStaggerProps extends HTMLAttributes<HTMLDivElement> {
  children: ReactNode;
  /** Delay between consecutive children (ms). */
  stagger?: number;
  /** Initial delay before the first child (ms). */
  delay?: number;
  duration?: number;
  from?: RevealFrom;
  offset?: number;
  once?: boolean;
  rootMargin?: string;
  /** Layout direction of the stack. */
  gap?: string;
  ref?: Ref<HTMLDivElement>;
}

export function RevealStagger({
  children,
  stagger = 80,
  delay = 0,
  duration = 480,
  from = "up",
  offset = 12,
  once = true,
  rootMargin,
  gap = "0.75rem",
  className,
  style,
  ref,
  ...props
}: RevealStaggerProps) {
  const items = Children.toArray(children);

  return (
    <div
      ref={ref}
      className={cx("flex w-full flex-col", className)}
      style={{ gap, ...style }}
      {...props}
    >
      {items.map((child, index) => {
        const childDelay = delay + index * stagger;

        if (isValidElement(child) && child.type === Reveal) {
          const reveal = child as ReactElement<RevealProps>;
          return cloneElement(reveal, {
            key: reveal.key ?? index,
            delay: reveal.props.delay ?? childDelay,
            duration: reveal.props.duration ?? duration,
            from: reveal.props.from ?? from,
            offset: reveal.props.offset ?? offset,
            once: reveal.props.once ?? once,
            rootMargin: reveal.props.rootMargin ?? rootMargin,
          });
        }

        return (
          <Reveal
            key={isValidElement(child) && child.key != null ? child.key : index}
            delay={childDelay}
            duration={duration}
            from={from}
            offset={offset}
            once={once}
            rootMargin={rootMargin}
          >
            {child}
          </Reveal>
        );
      })}
    </div>
  );
}

"use client";

import {
  useCallback,
  useRef,
  useState,
  type HTMLAttributes,
  type PointerEvent,
  type ReactNode,
  type Ref,
} from "react";
import { cx } from "@/lib/utils";

/**
 * Press ripple — Libraries.dev / Material energy on buttons and cards,
 * tinted with currentColor (set text-accent-500 on the host).
 *
 *   <Ripple className="text-accent-500">
 *     <Button>Ripple</Button>
 *   </Ripple>
 */

type RippleWave = { id: number; x: number; y: number; size: number };

export interface RippleProps extends HTMLAttributes<HTMLDivElement> {
  children: ReactNode;
  /** Disable the effect. */
  disabled?: boolean;
  ref?: Ref<HTMLDivElement>;
}

export function Ripple({
  children,
  disabled = false,
  className,
  onPointerDown,
  ref,
  ...props
}: RippleProps) {
  const hostRef = useRef<HTMLDivElement | null>(null);
  const [waves, setWaves] = useState<RippleWave[]>([]);
  const seq = useRef(0);

  const setRefs = useCallback(
    (node: HTMLDivElement | null) => {
      hostRef.current = node;
      if (typeof ref === "function") ref(node);
      else if (ref) ref.current = node;
    },
    [ref],
  );

  const spawn = (event: PointerEvent<HTMLDivElement>) => {
    if (disabled) return;
    const reduce =
      typeof window !== "undefined" &&
      window.matchMedia("(prefers-reduced-motion: reduce)").matches;
    if (reduce) return;

    const el = hostRef.current;
    if (!el) return;
    const rect = el.getBoundingClientRect();
    const size = Math.max(rect.width, rect.height) * 2;
    const id = ++seq.current;
    setWaves((prev) => [
      ...prev,
      {
        id,
        x: event.clientX - rect.left - size / 2,
        y: event.clientY - rect.top - size / 2,
        size,
      },
    ]);
    window.setTimeout(() => {
      setWaves((prev) => prev.filter((w) => w.id !== id));
    }, 520);
  };

  return (
    <div
      ref={setRefs}
      className={cx("bui-ripple relative isolate overflow-hidden", className)}
      onPointerDown={(event) => {
        spawn(event);
        onPointerDown?.(event);
      }}
      {...props}
    >
      {children}
      <span aria-hidden className="pointer-events-none absolute inset-0">
        {waves.map((wave) => (
          <span
            key={wave.id}
            className="bui-ripple-wave absolute rounded-full bg-current"
            style={{
              left: wave.x,
              top: wave.y,
              width: wave.size,
              height: wave.size,
            }}
          />
        ))}
      </span>
    </div>
  );
}

"use client";

import { useCallback, useState } from "react";
import type { UIEvent } from "react";
import { cx } from "@/lib/utils";

/**
 * The soft top edge of an internal scroll region: a 24px masked 1px backdrop
 * blur, a 16px masked 4px blur closer to the edge, and a wash of the
 * enclosing surface colour. Each layer fades in over the first 24px
 * scrolled, so the resting state keeps a plain top edge.
 *
 *   const fade = useScrollFade();
 *   <div className="relative min-h-0 flex-1">
 *     <div onScroll={fade.onScroll} className="h-full overflow-y-auto">…</div>
 *     <ScrollFade progress={fade.progress} surfaceClassName="from-background-primary-default" />
 *   </div>
 *
 * Keep the header outside the scroll region, and the overlay outside the
 * scroller (it must stay put while the content moves under it). Opacity goes
 * on each layer, never on the wrapper: a translucent parent becomes the
 * backdrop root, and the blur layers would sample nothing.
 */

/** Scroll distance, in px, over which the fade ramps from 0 to 1. */
export const SCROLL_FADE_DISTANCE = 24;

export function useScrollFade(distance = SCROLL_FADE_DISTANCE) {
  const [progress, setProgress] = useState(0);
  const onScroll = useCallback(
    (event: UIEvent<HTMLElement>) => setProgress(Math.min(1, Math.max(0, event.currentTarget.scrollTop) / distance)),
    [distance],
  );
  const reset = useCallback(() => setProgress(0), []);
  return { progress, onScroll, reset };
}

export interface ScrollFadeProps {
  /** 0 at rest, 1 once the region has scrolled `SCROLL_FADE_DISTANCE`. */
  progress: number;
  /**
   * The `from-*` class of the surface the region sits on, written out in
   * full so Tailwind can see it. Defaults to the primary surface.
   */
  surfaceClassName?: string;
  className?: string;
}

export function ScrollFade({ progress, surfaceClassName = "from-background-primary-default", className }: ScrollFadeProps) {
  return (
    <div aria-hidden className={cx("pointer-events-none absolute inset-x-0 top-0 z-10 h-6", className)}>
      <div
        className="absolute inset-0 backdrop-blur-[1px] [mask-image:linear-gradient(to_bottom,black,transparent)]"
        style={{ opacity: progress }}
      />
      <div
        className="absolute inset-x-0 top-0 h-4 backdrop-blur-[4px] [mask-image:linear-gradient(to_bottom,black,transparent)]"
        style={{ opacity: progress }}
      />
      <div className={cx("absolute inset-0 bg-linear-to-b to-transparent", surfaceClassName)} style={{ opacity: progress }} />
    </div>
  );
}

"use client";

import {
  useEffect,
  useState,
  type CSSProperties,
  type HTMLAttributes,
  type Ref,
  type RefObject,
} from "react";
import { cx } from "@/lib/utils";

/**
 * Thin reading progress bar pinned to the top of the viewport (or a
 * container). Bencho / docs-site energy for long articles.
 *
 *   <ScrollProgress />
 */

export interface ScrollProgressProps extends HTMLAttributes<HTMLDivElement> {
  /** Scroll container; defaults to `window`. */
  target?: RefObject<HTMLElement | null>;
  /** Track thickness. Default 2. */
  height?: number;
  ref?: Ref<HTMLDivElement>;
}

export function ScrollProgress({
  target,
  height = 2,
  className,
  style,
  ref,
  ...props
}: ScrollProgressProps) {
  const [progress, setProgress] = useState(0);

  useEffect(() => {
    const read = () => {
      const el = target?.current;
      if (el) {
        const max = el.scrollHeight - el.clientHeight;
        setProgress(max <= 0 ? 0 : el.scrollTop / max);
        return;
      }
      const doc = document.documentElement;
      const max = doc.scrollHeight - window.innerHeight;
      setProgress(max <= 0 ? 0 : window.scrollY / max);
    };

    read();
    const el = target?.current;
    if (el) {
      el.addEventListener("scroll", read, { passive: true });
      return () => el.removeEventListener("scroll", read);
    }
    window.addEventListener("scroll", read, { passive: true });
    window.addEventListener("resize", read);
    return () => {
      window.removeEventListener("scroll", read);
      window.removeEventListener("resize", read);
    };
  }, [target]);

  return (
    <div
      ref={ref}
      role="progressbar"
      aria-valuemin={0}
      aria-valuemax={100}
      aria-valuenow={Math.round(progress * 100)}
      aria-label="阅读进度"
      className={cx(
        "pointer-events-none inset-x-0 top-0 z-50 bg-border-button-default",
        // Default fixed for app chrome; pass `absolute` + a relative parent for demos.
        !className?.includes("absolute") && "fixed",
        className,
      )}
      style={{ height, ...style } as CSSProperties}
      {...props}
    >
      <div
        className="h-full origin-left transition-transform duration-75 ease-[cubic-bezier(0.22,1,0.36,1)] motion-reduce:transition-none"
        style={{
          transform: `scaleX(${Math.min(1, Math.max(0, progress))})`,
          backgroundImage: "var(--gradient-button-primary-default)",
        }}
      />
    </div>
  );
}

