"use client";

import type { CSSProperties, ReactNode } from "react";
import { cx, sortCx } from "@/lib/utils";

/**
 * Skeleton — placeholders in the shape of the content that is on its way.
 *
 *   <Skeleton shape="circle" className="size-10" />
 *   <SkeletonText lines={3} />
 *   <Skeleton isLoaded={user != null}><Avatar … /></Skeleton>
 *
 * Blocks are tinted from the text colour at 8%, so they show on any surface
 * in both themes (a fixed grey disappears on dark cards). A sheen of light
 * sweeps each one, drawn in layers like Spinner and Progress: a crisp 2px
 * line leads, a tight glow and a wide bloom trail it. It mirrors in RTL and
 * gives way to a gentle opacity pulse under reduced motion. The sheen lives
 * in globals.css (`.bui-skeleton`).
 *
 * With children, a Skeleton sizes itself to them: it lays the real content
 * out invisibly, then, once `isLoaded`, cross-fades the block away while the
 * content sharpens in from a 4px blur.
 *
 * Skeletons are hidden from assistive technology; mark the region that is
 * loading with `aria-busy`.
 */

export type SkeletonShape = "rect" | "text" | "circle";

const styles = sortCx({
  // 14% keeps bones visible on dark primary-800 cards (8% vanished).
  block: "bui-skeleton block bg-text-primary/14",
  shape: {
    rect: "rounded-xl",
    text: "rounded-md",
    circle: "rounded-full",
  },
});

const FADE = "transition-[opacity,filter] duration-300 ease-out motion-reduce:transition-none";

export interface SkeletonProps {
  /** `rect` (radius 12, default), `text` (radius 6), or `circle`. */
  shape?: SkeletonShape;
  /** With children: show them once true, blurring them in. */
  isLoaded?: boolean;
  /** Size and placement, e.g. `h-4 w-40` or `size-10`. */
  className?: string;
  style?: CSSProperties;
  /** Real content to measure the placeholder from and reveal when loaded. */
  children?: ReactNode;
}

export function Skeleton({ shape = "rect", isLoaded = false, className, style, children }: SkeletonProps) {
  if (children === undefined) {
    return <span aria-hidden className={cx(styles.block, "relative", styles.shape[shape], className)} style={style} />;
  }

  return (
    <span className={cx("relative block", className)} style={style}>
      <span
        aria-hidden={!isLoaded || undefined}
        inert={!isLoaded}
        className={cx("block", FADE, isLoaded ? "opacity-100 blur-[0px]" : "opacity-0 motion-safe:blur-[4px]")}
      >
        {children}
      </span>
      <span
        aria-hidden
        className={cx(styles.block, styles.shape[shape], "pointer-events-none absolute inset-0", FADE, isLoaded && "opacity-0")}
      />
    </span>
  );
}

export interface SkeletonTextProps {
  /** Number of lines. Default 3; the last one runs 60% wide. */
  lines?: number;
  /** Line height, matched to the text it stands in for. Default `h-3.5` (Body 1). */
  lineClassName?: string;
  className?: string;
}

export function SkeletonText({ lines = 3, lineClassName = "h-3.5", className }: SkeletonTextProps) {
  return (
    <span aria-hidden className={cx("flex w-full flex-col gap-2.5", className)}>
      {Array.from({ length: lines }, (_, index) => (
        <Skeleton
          key={index}
          shape="text"
          className={cx(lineClassName, index === lines - 1 && lines > 1 ? "w-3/5" : "w-full")}
        />
      ))}
    </span>
  );
}

"use client";

import {
  useCallback,
  useRef,
  useState,
  type HTMLAttributes,
  type PointerEvent,
  type Ref,
} from "react";
import { RiArrowRightLine, RiCheckLine } from "@remixicon/react";
import { cx } from "@/lib/utils";

/**
 * Drag the thumb across the track to confirm a destructive / irreversible
 * action — Bencho “Slide to confirm”, drawn like JoyUI Switch (track + thumb).
 *
 *   <SlideToConfirm label="滑动确认删除" onConfirm={deleteRow} />
 */

export interface SlideToConfirmProps
  extends Omit<HTMLAttributes<HTMLDivElement>, "onChange"> {
  label?: string;
  confirmedLabel?: string;
  disabled?: boolean;
  /** Fraction of track (0–1) that counts as confirmed. Default 0.92. */
  threshold?: number;
  onConfirm?: () => void;
  /** Reset after confirm (ms). `0` keeps confirmed state. Default 1600. */
  resetMs?: number;
  ref?: Ref<HTMLDivElement>;
}

const THUMB = 36;
const PAD = 4;
const EASE = "ease-[cubic-bezier(0.22,1,0.36,1)]";

export function SlideToConfirm({
  label = "滑动确认",
  confirmedLabel = "已确认",
  disabled = false,
  threshold = 0.92,
  onConfirm,
  resetMs = 1600,
  className,
  ref,
  ...props
}: SlideToConfirmProps) {
  const trackRef = useRef<HTMLDivElement | null>(null);
  const [offset, setOffset] = useState(0);
  const [dragging, setDragging] = useState(false);
  const [done, setDone] = useState(false);
  const confirmedRef = useRef(false);
  const offsetRef = useRef(0);

  const setRefs = useCallback(
    (node: HTMLDivElement | null) => {
      trackRef.current = node;
      if (typeof ref === "function") ref(node);
      else if (ref) ref.current = node;
    },
    [ref],
  );

  const maxOffset = () => {
    const el = trackRef.current;
    if (!el) return 0;
    return Math.max(0, el.clientWidth - THUMB - PAD * 2);
  };

  const setOffsetSafe = (value: number) => {
    const next = Math.min(maxOffset(), Math.max(0, value));
    offsetRef.current = next;
    setOffset(next);
    return next;
  };

  const finish = (value: number) => {
    const max = maxOffset();
    const ratio = max === 0 ? 0 : value / max;
    if (ratio >= threshold && !confirmedRef.current) {
      confirmedRef.current = true;
      setDone(true);
      setOffsetSafe(max);
      onConfirm?.();
      if (resetMs > 0) {
        window.setTimeout(() => {
          confirmedRef.current = false;
          setDone(false);
          setOffsetSafe(0);
        }, resetMs);
      }
    } else if (!confirmedRef.current) {
      setOffsetSafe(0);
    }
  };

  const onPointerDown = (event: PointerEvent<HTMLButtonElement>) => {
    if (disabled || done) return;
    event.currentTarget.setPointerCapture(event.pointerId);
    setDragging(true);
    const el = trackRef.current;
    if (!el) return;
    const rect = el.getBoundingClientRect();
    setOffsetSafe(event.clientX - rect.left - PAD - THUMB / 2);
  };

  const onPointerMove = (event: PointerEvent<HTMLButtonElement>) => {
    if (!dragging || disabled || done) return;
    const el = trackRef.current;
    if (!el) return;
    const rect = el.getBoundingClientRect();
    setOffsetSafe(event.clientX - rect.left - PAD - THUMB / 2);
  };

  const onPointerUp = (event: PointerEvent<HTMLButtonElement>) => {
    if (!dragging) return;
    setDragging(false);
    try {
      event.currentTarget.releasePointerCapture(event.pointerId);
    } catch {
      /* ignore */
    }
    finish(offsetRef.current);
  };

  const ratio = maxOffset() === 0 ? 0 : offset / maxOffset();
  const fill = done ? 1 : ratio;

  return (
    <div
      ref={setRefs}
      role="group"
      aria-disabled={disabled || undefined}
      className={cx(
        // Switch-off track: recessed tertiary fill + quiet ring so the track
        // stays visible on dark cards that also use background-* surfaces.
        "relative flex h-11 w-full max-w-sm select-none items-center overflow-hidden rounded-full",
        "bg-background-tertiary-default ring-2 ring-inset ring-border-secondary-default",
        disabled && "pointer-events-none opacity-60",
        className,
      )}
      {...props}
    >
      <div
        aria-hidden
        className={cx(
          "absolute inset-y-0 start-0 rounded-full transition-[width] duration-150 motion-reduce:transition-none",
          EASE,
          done ? "shadow-checkbox-selected" : "",
        )}
        style={{
          width: `${Math.max(fill * 100, 0)}%`,
          backgroundImage: "var(--gradient-button-primary-default)",
          opacity: fill === 0 ? 0 : 0.22 + fill * 0.78,
        }}
      />
      <span
        className={cx(
          "pointer-events-none absolute inset-0 flex items-center justify-center px-12 text-body-medium text-text-primary transition-opacity duration-150",
          ratio > 0.12 || done ? "opacity-0" : "opacity-100",
        )}
      >
        {label}
      </span>
      <span
        className={cx(
          "pointer-events-none absolute inset-0 flex items-center justify-center text-body-medium text-white transition-opacity duration-150",
          done ? "opacity-100" : "opacity-0",
        )}
      >
        {confirmedLabel}
      </span>
      <button
        type="button"
        aria-label={done ? confirmedLabel : label}
        disabled={disabled || done}
        onPointerDown={onPointerDown}
        onPointerMove={onPointerMove}
        onPointerUp={onPointerUp}
        onPointerCancel={onPointerUp}
        className={cx(
          // Thumb sits above the recessed track — elevated surface + border
          // so it doesn't dissolve into dark tertiary fills.
          "absolute top-1 z-10 flex size-9 items-center justify-center rounded-full touch-none",
          "bg-background-secondary-default text-foreground-icon-primary shadow-xs",
          "ring-1 ring-border-secondary-default",
          "outline-none focus-visible:ring-2 focus-visible:ring-offset-2 focus-visible:ring-border-focus-ring",
          !dragging && cx("transition-transform duration-150", EASE),
          done && "text-accent-600",
        )}
        style={{
          left: PAD,
          transform: `translateX(${offset}px)`,
        }}
      >
        {done ? (
          <RiCheckLine className="size-5" aria-hidden />
        ) : (
          <RiArrowRightLine className="size-5" aria-hidden />
        )}
      </button>
    </div>
  );
}

