import type { ReactNode } from "react";
import {
  Label as AriaLabel,
  Slider as AriaSlider,
  SliderThumb as AriaSliderThumb,
  SliderTrack as AriaSliderTrack,
} from "react-aria-components";
import type { SliderProps as AriaSliderProps } from "react-aria-components";
import { cx } from "@/lib/utils";

type SliderValue = number | number[];

type SliderBaseProps<T extends SliderValue> = Omit<
  AriaSliderProps<T>,
  "children" | "className" | "orientation"
> & {
  /** Optional visible label associated with every thumb. */
  label?: ReactNode;
  /** Show the exact value in a persistent bubble above each thumb. Default `true`. */
  showTooltip?: boolean;
  /** Custom visual formatter for the value bubbles. */
  formatValue?: (value: number, index: number) => ReactNode;
  className?: string;
};

export type SliderProps = SliderBaseProps<number> & {
  /** Accessible name for the single thumb. */
  thumbLabel?: string;
};

export type RangeSliderProps = SliderBaseProps<number[]> & {
  /** Accessible names for the lower and upper thumbs. */
  thumbLabels?: [string, string];
};

type SliderBaseInternalProps<T extends SliderValue> = SliderBaseProps<T> & {
  thumbLabels: string[];
};

/**
 * Shared single and multi-thumb slider presentation.
 *
 * React Aria owns the value model, drag behavior, hidden range inputs,
 * keyboard controls, RTL handling, and collision rules. JoyUI owns the
 * visual track, selected range, thumbs, and exact-value bubbles.
 */
function SliderBase<T extends SliderValue>({
  className,
  label,
  showTooltip = true,
  formatValue,
  thumbLabels,
  ...props
}: SliderBaseInternalProps<T>) {
  return (
    <AriaSlider
      {...props}
      orientation="horizontal"
      className={({ isDisabled }) =>
        cx(
          "group flex w-full min-w-0 flex-col gap-2",
          isDisabled && "cursor-not-allowed opacity-50",
          className,
        )
      }
    >
      {({ state }) => {
        const isRange = state.values.length > 1;
        const startPercent = isRange ? state.getThumbPercent(0) : 0;
        const endPercent = state.getThumbPercent(state.values.length - 1);

        return (
          <>
            {label != null && (
              <AriaLabel className="text-body-medium text-text-primary">
                {label}
              </AriaLabel>
            )}

            <AriaSliderTrack
              className={cx(
                "relative h-8 w-full touch-none",
                showTooltip && "mt-8",
              )}
            >
              {({ isHovered }) => (
                <>
                  <span
                    aria-hidden
                    className={cx(
                      "absolute top-1/2 end-0 start-0 h-1.5 -translate-y-1/2 rounded-full",
                      "bg-background-tertiary-default shadow-[inset_0_1px_1px_rgb(0_0_0/0.06)]",
                      "transition-colors duration-150 ease",
                      isHovered && "bg-background-tertiary-hover",
                    )}
                  />
                  <span
                    aria-hidden
                    className={cx(
                      "absolute top-1/2 h-1.5 -translate-y-1/2 rounded-full",
                      "bg-linear-to-r from-accent-500 to-accent-600",
                      "shadow-[inset_0_1px_0_rgb(255_255_255/0.24),0_1px_2px_rgb(4_80_226/0.16)]",
                    )}
                    style={{
                      insetInlineStart: `${startPercent * 100}%`,
                      insetInlineEnd: `${(1 - endPercent) * 100}%`,
                    }}
                  />

                  {state.values.map((value, index) => {
                    const valueLabel =
                      formatValue?.(value, index) ??
                      state.getThumbValueLabel(index);

                    return (
                      <AriaSliderThumb
                        key={index}
                        index={index}
                        aria-label={
                          thumbLabels[index] ??
                          (isRange ? `Value ${index + 1}` : "Value")
                        }
                        className={({
                          isDragging,
                          isHovered: isThumbHovered,
                          isFocusVisible,
                          isDisabled,
                        }) =>
                          cx(
                            "top-1/2 size-5 rounded-full border border-border-button-default outline-none",
                            "flex items-center justify-center bg-control-indicator-background",
                            "shadow-[0_2px_4px_rgb(0_0_0/0.10),inset_0_1px_0_rgb(255_255_255/0.8)]",
                            "transition-[scale,box-shadow,border-color] duration-150 ease",
                            isThumbHovered && !isDragging && "scale-105 border-border-button-hover",
                            isDragging && "z-20 scale-110 border-accent-500 shadow-[0_3px_8px_color-mix(in_srgb,var(--color-accent-600)_22%,transparent)]",
                            isFocusVisible && "ring-2 ring-border-focus-ring ring-offset-2",
                            isDisabled ? "cursor-not-allowed" : "cursor-grab active:cursor-grabbing",
                          )
                        }
                      >
                        {({ isDragging, isFocused }) => (
                          <>
                            {showTooltip && (
                              <span
                                aria-hidden
                                className={cx(
                                  "pointer-events-none absolute bottom-[calc(100%+9px)] left-1/2 -translate-x-1/2",
                                  "flex h-7 min-w-8 items-center justify-center rounded-lg border border-border-button-default",
                                  "bg-background-primary-default px-2 text-caption-1-medium whitespace-nowrap text-text-primary shadow-xs",
                                  "transition-[translate,box-shadow] duration-150 ease",
                                  (isDragging || isFocused) && "-translate-y-0.5 shadow-dropdown",
                                )}
                              >
                                {valueLabel}
                                <span
                                  aria-hidden
                                  className="absolute -bottom-[4.5px] left-1/2 size-2 -translate-x-1/2 rotate-45 border-r border-b border-border-button-default bg-background-primary-default"
                                />
                              </span>
                            )}
                            <span
                              aria-hidden
                              className={cx(
                                "size-2 rounded-full bg-linear-to-b from-accent-500 to-accent-600",
                                "shadow-[inset_0_1px_0_rgb(255_255_255/0.24)] transition-[filter] duration-150 ease",
                                (isDragging || isFocused) && "brightness-110",
                              )}
                            />
                          </>
                        )}
                      </AriaSliderThumb>
                    );
                  })}
                </>
              )}
            </AriaSliderTrack>
          </>
        );
      }}
    </AriaSlider>
  );
}

/** A single-value slider with an exact-value bubble above the thumb. */
export function Slider({ thumbLabel = "Value", ...props }: SliderProps) {
  return <SliderBase {...props} thumbLabels={[thumbLabel]} />;
}

/** A two-thumb slider for selecting a minimum and maximum value. */
export function RangeSlider({
  thumbLabels = ["Minimum", "Maximum"],
  ...props
}: RangeSliderProps) {
  return <SliderBase {...props} thumbLabels={thumbLabels} />;
}

import type { AnchorHTMLAttributes, ButtonHTMLAttributes, ReactNode, Ref } from "react";
import { cx, sortCx } from "@/lib/utils";
import { SOCIAL_COLOR_LOGOS } from "./social-color-logos";
import {
  SOCIAL_PROVIDERS,
  type SocialProvider,
} from "./social-providers";

/**
 * Sign-in button for a third-party provider — 24 of them, from Google and
 * Apple through to Okta and Auth0, plus `custom` for anything else.
 *
 * The brand is named, not passed as artwork: `brand="google"` supplies the
 * logo, the brand colour and the accessible label together, so a stack of
 * these cannot drift out of sync.
 *
 *   <SocialButton brand="google" />                       Continue with Google
 *   <SocialButton brand="github" appearance="white" />    outlined, colour mark
 *   <SocialButton brand="apple" iconOnly />               square, logo only
 *   <SocialButton brand="figma" href="/auth/figma" />     renders an anchor
 *
 * Three appearances. `colorful` (default) fills with the brand colour and
 * puts a white glyph on it. `black` is the same shape in high-contrast solid
 * black. `white` is the outlined treatment, and the one that shows each
 * provider's real multi-colour mark, which is what most sign-in screens use.
 *
 * One rounding, deliberately: a sign-in stack reads as a set, and mixing pill
 * and square corners across providers is noise rather than expression.
 */

export type SocialBrand = SocialProvider | "custom";
export type SocialButtonSize = "medium" | "small";
export type SocialButtonAppearance = "colorful" | "black" | "white";

/** Everything a brand needs, for providers that are not built in. */
export interface SocialBrandConfig {
  icon: ReactNode;
  /** Used in the label and as the accessible name. Defaults to "SSO". */
  label?: string;
  /** Fill for `colorful`. Defaults to black. */
  color?: string;
}

interface SocialButtonBaseProps {
  brand: SocialBrand;
  /** Required when `brand="custom"`; ignored otherwise. */
  config?: SocialBrandConfig;
  size?: SocialButtonSize;
  appearance?: SocialButtonAppearance;
  /** Square button showing only the logo; the label becomes the aria-label. */
  iconOnly?: boolean;
  /** Drop the fixed width and fill the container instead. */
  fullWidth?: boolean;
  /** Defaults to "Continue with <Brand>". */
  children?: ReactNode;
  className?: string;
}

export interface SocialButtonProps
  extends SocialButtonBaseProps,
    Omit<ButtonHTMLAttributes<HTMLButtonElement>, "children" | "color"> {
  href?: never;
  ref?: Ref<HTMLButtonElement>;
}

export interface SocialButtonLinkProps
  extends SocialButtonBaseProps,
    Omit<AnchorHTMLAttributes<HTMLAnchorElement>, "children" | "color"> {
  /** Renders an anchor instead of a button — OAuth starts are navigations. */
  href: string;
  ref?: Ref<HTMLAnchorElement>;
}

/**
 * Brands whose real mark is drawn in near-black. On a dark surface they
 * disappear into it, so dark mode repaints their paths white — the official
 * treatment both publish for dark backgrounds. Colourful marks (Google,
 * Slack) are left exactly as drawn.
 */
const DARK_INVERTED_BRANDS = new Set<SocialBrand>(["apple", "github", "x"]);

const styles = sortCx({
  base: [
    "inline-flex items-center justify-center gap-2 whitespace-nowrap overflow-hidden",
    "font-sans select-none cursor-pointer",
    "button-press-motion",
    "transition-[background-color,border-color,box-shadow,color,filter] duration-150 ease",
    "outline-none focus-visible:ring-2 focus-visible:ring-offset-2 focus-visible:ring-border-focus-ring",
    "disabled:cursor-not-allowed disabled:opacity-60 aria-disabled:cursor-not-allowed aria-disabled:opacity-60",
  ].join(" "),
  // Heights, radii and glyph sizes are the base Button's medium and small to
  // the pixel, so a social button can sit in a form beside a Button without
  // a half-step in the rhythm. The fixed width is the one addition: a column
  // of providers should line up without a wrapper doing the work, and
  // `fullWidth` opts out.
  size: {
    medium: "h-9 w-[300px] rounded-2lg px-3 text-body-medium",
    small: "h-8 w-[250px] rounded-lg px-2.5 text-body-medium",
  },
  iconOnlySize: {
    medium: "size-9 w-9 rounded-2lg px-0",
    small: "size-8 w-8 rounded-lg px-0",
  },
  // A touch under the base Button's icon sizes (20/18): a brand mark is
  // denser than a line icon and reads heavier at the same box.
  glyph: {
    medium: "size-[18px] shrink-0",
    small: "size-4 shrink-0",
  },
  appearance: {
    // The same recipe as `bg-button-primary`: a 180deg gradient from the
    // brand colour into a darker stop, with the system's own button shadow.
    // A flat fill read as a foreign control next to JoyUI's own buttons.
    // The gradient itself is set inline, since it is per-brand.
    colorful: "text-white shadow-xs",
    black:
      "bg-neutral-950 text-white shadow-xs hover:bg-neutral-800 active:bg-neutral-900",
    // Matches the system's secondary button, so it sits in a form beside the
    // rest of JoyUI without looking like a different family.
    white: [
      "bg-background-primary-default text-text-primary",
      "border border-border-button-default shadow-xs",
      "hover:bg-background-primary-hover hover:border-border-button-hover",
      "active:bg-background-primary-active active:border-border-button-active",
    ].join(" "),
  },
});

export function SocialButton({ href, ...props }: SocialButtonProps | SocialButtonLinkProps) {
  const {
    brand,
    config,
    size = "medium",
    appearance = "colorful",
    iconOnly = false,
    fullWidth = false,
    children,
    className,
    ref,
    ...rest
  } = props as SocialButtonBaseProps & {
    ref?: Ref<HTMLButtonElement & HTMLAnchorElement>;
  } & Record<string, unknown>;

  const custom = brand === "custom";
  const meta = custom ? undefined : SOCIAL_PROVIDERS[brand as SocialProvider];
  if (!custom && !meta) {
    throw new Error(
      `SocialButton: unknown brand "${String(brand)}". Use a SocialProvider key or brand="custom" with config.`,
    );
  }
  const label = custom ? (config?.label ?? "SSO") : meta!.label;
  const fill = custom ? (config?.color ?? "#000000") : meta!.brand;

  // The outlined treatment is where the real multi-colour mark belongs: on a
  // brand or black fill it would fight the background. Not every provider has
  // one upstream (see social-color-logos.ts), so a missing mark falls back to
  // the monochrome glyph tinted with the brand colour.
  const colorLogo =
    appearance === "white" && !custom
      ? SOCIAL_COLOR_LOGOS[brand as SocialProvider]
      : undefined;

  const glyph = custom ? (
    <span className={cx(styles.glyph[size], "inline-flex items-center justify-center")}>
      {config?.icon}
    </span>
  ) : colorLogo ? (
    <svg
      viewBox={colorLogo.viewBox}
      aria-hidden
      className={cx(
        styles.glyph[size],
        DARK_INVERTED_BRANDS.has(brand) && "dark:[&_path]:fill-white",
      )}
      // The mark carries its own fills, so it goes in as markup. This is a
      // build-time constant from this repo, never caller- or user-supplied.
      dangerouslySetInnerHTML={{ __html: colorLogo.body }}
    />
  ) : (
    <svg
      viewBox={meta!.viewBox}
      aria-hidden
      className={styles.glyph[size]}
      // On the filled appearances the glyph rides the white label; outlined
      // falls back to the brand colour so it is not a grey smudge.
      style={appearance === "white" ? { color: meta!.brand } : undefined}
    >
      <path d={meta!.path} fill="currentColor" />
    </svg>
  );

  const content = (
    <>
      {glyph}
      {iconOnly ? null : <span className="truncate">{children ?? `Continue with ${label}`}</span>}
    </>
  );

  // A brand whose colour is a system token (Google) hands the fill straight
  // to `bg-button-primary`, so it is the primary button, gradient, hover and
  // active included, rather than an approximation of it. Every other brand
  // gets that gradient's shape derived from its own colour: down in
  // lightness and up slightly in chroma, which is what blue-500 → blue-600
  // does. Mixing toward black instead would wash the second stop out.
  const systemFill = appearance === "colorful" && fill.startsWith("var(");

  const classes = cx(
    styles.base,
    iconOnly ? styles.iconOnlySize[size] : styles.size[size],
    styles.appearance[appearance],
    // `bg-button-primary` carries its own hover and active gradients; the
    // derived brands need the brightness shift instead.
    systemFill
      ? "bg-button-primary"
      : appearance === "colorful" && "hover:brightness-[1.06] active:brightness-95",
    fullWidth && !iconOnly && "w-full",
    className,
  );

  // The visible label already names the brand; when it is hidden the element
  // needs that name back, or the control announces as unlabelled.
  const accessibleName = iconOnly ? `Continue with ${label}` : undefined;

  const inlineStyle =
    appearance === "colorful" && !systemFill
      ? {
          backgroundImage: `linear-gradient(180deg, ${fill} 0%, oklch(from ${fill} calc(l - 0.04) calc(c + 0.01) h) 100%)`,
        }
      : undefined;

  if (href !== undefined) {
    return (
      <a
        ref={ref as Ref<HTMLAnchorElement>}
        href={href}
        aria-label={accessibleName}
        className={classes}
        style={inlineStyle}
        {...(rest as AnchorHTMLAttributes<HTMLAnchorElement>)}
      >
        {content}
      </a>
    );
  }

  return (
    <button
      ref={ref as Ref<HTMLButtonElement>}
      type="button"
      aria-label={accessibleName}
      className={classes}
      style={inlineStyle}
      {...(rest as ButtonHTMLAttributes<HTMLButtonElement>)}
    >
      {content}
    </button>
  );
}

export { SOCIAL_PROVIDERS, type SocialProvider };

"use client";

import type { CSSProperties } from "react";
import { ProgressBar as AriaProgressBar } from "react-aria-components";
import { cx } from "@/lib/utils";

/**
 * Spinner — an orbiting light for work of unknown length.
 *
 *   <Spinner />                                  // 20px, accent
 *   <Spinner size="sm" className="text-white" /> // inside a primary button
 *
 * The light is drawn the way Composer Loader draws its band: the same arc
 * at three scales, a crisp line with a rounded head, a tight glow and a wide
 * bloom, each on its own blur. The soft layers carry shorter arcs and turn a
 * few degrees behind, so the sharp head always leads and the glow gathers
 * just behind it like the tail of a comet. A faint track completes the
 * circle. Everything is drawn in `currentColor`, so a text colour sets it.
 *
 * Announced as an indeterminate progress bar labelled "Loading" (override
 * with `aria-label`). Pass `aria-hidden` where the surrounding control
 * already says it is busy, e.g. a pending button. Reduced motion slows the
 * orbit rather than stopping it: the motion is the message.
 */

export type SpinnerSize = "xs" | "sm" | "md" | "lg" | "xl";

/** Box size and line width in px. */
const SIZES: Record<SpinnerSize, { box: number; line: number }> = {
  xs: { box: 12, line: 1.5 },
  sm: { box: 16, line: 2 },
  md: { box: 20, line: 2 },
  lg: { box: 24, line: 2.5 },
  xl: { box: 32, line: 3 },
};

/** One scale of the light: a conic arc masked to a ring, blurred by its wrapper. */
function Arc({
  box,
  line,
  width,
  blur,
  opacity,
  arc,
  lag,
}: {
  box: number;
  line: number;
  /** Ring thickness, px. */
  width: number;
  blur: number;
  opacity: number;
  /** Arc length in degrees; the head sits at 12 o'clock before the turn. */
  arc: number;
  /** Degrees this layer trails the crisp head. */
  lag: number;
}) {
  const center = box / 2 - line / 2;
  const inner = center - width / 2;
  const outer = center + width / 2;
  // The wrapper is grown to hold the ring plus its blur, so nothing clips.
  const bleed = Math.max(0, outer + blur * 2 - box / 2);
  const ring = `radial-gradient(circle, transparent ${inner}px, #000 ${inner + 0.5}px, #000 ${outer - 0.5}px, transparent ${outer}px)`;
  const style: CSSProperties = {
    inset: -bleed,
    filter: blur > 0 ? `blur(${blur}px)` : undefined,
    opacity,
    rotate: `${-lag}deg`,
  };
  return (
    <span aria-hidden className="absolute" style={style}>
      <span
        className="absolute inset-0"
        style={{
          background: `conic-gradient(transparent ${360 - arc}deg, currentColor 360deg)`,
          maskImage: ring,
          WebkitMaskImage: ring,
        }}
      />
    </span>
  );
}

export interface SpinnerProps {
  /** 12, 16, 20 (default), 24, or 32px. */
  size?: SpinnerSize;
  /** Draw the faint full circle under the light. Default true. */
  track?: boolean;
  /** Accessible name. Default "Loading". */
  "aria-label"?: string;
  /** Hide it from assistive technology when a parent already announces the wait. */
  "aria-hidden"?: boolean;
  /** Colour comes from the text colour, e.g. `text-white`. Default accent. */
  className?: string;
}

export function SpinnerGlyph({ size = "md", track = true, className }: Omit<SpinnerProps, "aria-label" | "aria-hidden">) {
  const { box, line } = SIZES[size];
  return (
    <span
      aria-hidden
      className={cx("relative inline-flex shrink-0 text-accent-500", className)}
      style={{ width: box, height: box }}
    >
      {track ? (
        <span className="absolute inset-0 rounded-full border-current opacity-15" style={{ borderWidth: line }} />
      ) : null}
      <span className="absolute inset-0 animate-spin [animation-duration:900ms] motion-reduce:[animation-duration:2400ms]">
        <Arc box={box} line={line} width={line * 4} blur={line * 1.6} opacity={0.32} arc={110} lag={22} />
        <Arc box={box} line={line} width={line * 2} blur={line * 0.6} opacity={0.6} arc={200} lag={9} />
        <Arc box={box} line={line} width={line} blur={0} opacity={1} arc={290} lag={0} />
        {/* The crisp line's rounded head, at the arc's leading end. */}
        <span
          className="absolute left-1/2 top-0 rounded-full bg-current"
          style={{ width: line, height: line, translate: "-50% 0" }}
        />
      </span>
    </span>
  );
}

export function Spinner({ size = "md", track = true, "aria-label": ariaLabel = "Loading", "aria-hidden": ariaHidden, className }: SpinnerProps) {
  if (ariaHidden) return <SpinnerGlyph size={size} track={track} className={className} />;
  return (
    <AriaProgressBar isIndeterminate aria-label={ariaLabel} className="inline-flex shrink-0">
      <SpinnerGlyph size={size} track={track} className={className} />
    </AriaProgressBar>
  );
}

"use client";

import {
  useCallback,
  useRef,
  useState,
  type CSSProperties,
  type HTMLAttributes,
  type MouseEvent,
  type ReactNode,
  type Ref,
} from "react";
import { cx, sortCx } from "@/lib/utils";

/**
 * Card that follows the pointer with a soft radial wash — Bencho-style
 * micro-interaction on JoyUI Card surfaces.
 *
 *   <SpotlightCard>
 *     <p className="text-body-medium">Feature title</p>
 *   </SpotlightCard>
 */

export type SpotlightCardPadding = "sm" | "md" | "lg";

export interface SpotlightCardProps extends HTMLAttributes<HTMLDivElement> {
  children?: ReactNode;
  /** Spotlight radius in px. */
  size?: number;
  /** Spotlight colour (defaults to accent at low alpha). */
  color?: string;
  padding?: SpotlightCardPadding;
  ref?: Ref<HTMLDivElement>;
}

const styles = sortCx({
  // Mirror Card `outline` so spotlight tiles sit next to real Cards.
  base: "bui-spotlight-card relative isolate overflow-hidden rounded-2xl border border-border-secondary-default bg-background-primary-default dark:bg-background-secondary-default",
  padding: {
    sm: "p-3",
    md: "p-4",
    lg: "p-6 sm:p-8",
  },
});

export function SpotlightCard({
  children,
  className,
  size = 260,
  color,
  padding = "md",
  style,
  onMouseMove,
  onMouseLeave,
  ref,
  ...props
}: SpotlightCardProps) {
  const localRef = useRef<HTMLDivElement | null>(null);
  const [pos, setPos] = useState({ x: 0, y: 0, on: false });

  const setRefs = useCallback(
    (node: HTMLDivElement | null) => {
      localRef.current = node;
      if (typeof ref === "function") ref(node);
      else if (ref) ref.current = node;
    },
    [ref],
  );

  const handleMove = (event: MouseEvent<HTMLDivElement>) => {
    const el = localRef.current;
    if (el) {
      const rect = el.getBoundingClientRect();
      setPos({
        x: event.clientX - rect.left,
        y: event.clientY - rect.top,
        on: true,
      });
    }
    onMouseMove?.(event);
  };

  const handleLeave = (event: MouseEvent<HTMLDivElement>) => {
    setPos((p) => ({ ...p, on: false }));
    onMouseLeave?.(event);
  };

  const spotColor =
    color ?? "color-mix(in oklab, var(--color-accent-500) 18%, transparent)";

  return (
    <div
      ref={setRefs}
      onMouseMove={handleMove}
      onMouseLeave={handleLeave}
      className={cx(styles.base, styles.padding[padding], className)}
      style={
        {
          "--bui-spotlight-x": `${pos.x}px`,
          "--bui-spotlight-y": `${pos.y}px`,
          "--bui-spotlight-size": `${size}px`,
          "--bui-spotlight-color": spotColor,
          "--bui-spotlight-opacity": pos.on ? "1" : "0",
          ...style,
        } as CSSProperties
      }
      {...props}
    >
      <span aria-hidden className="bui-spotlight-card-glow pointer-events-none absolute inset-0" />
      <div className="relative z-10 min-w-0">{children}</div>
    </div>
  );
}

"use client";

import {
  useCallback,
  useRef,
  useState,
  type CSSProperties,
  type HTMLAttributes,
  type MouseEvent,
  type ReactNode,
  type Ref,
} from "react";
import { cx, sortCx } from "@/lib/utils";

/**
 * Spotlight card with a soft conic border beam chasing the edge.
 * Combines pointer-follow wash + BorderBeam-style masked spin — no purple glow.
 *
 *   <SpotlightCardBorder>
 *     <p className="text-body-medium">Pro feature</p>
 *   </SpotlightCardBorder>
 */

export type SpotlightCardBorderPadding = "sm" | "md" | "lg";

export interface SpotlightCardBorderProps
  extends HTMLAttributes<HTMLDivElement> {
  children?: ReactNode;
  /** Spotlight radius in px. */
  size?: number;
  /** Spotlight colour (defaults to accent at low alpha). */
  color?: string;
  /** Border beam thickness in px. */
  borderWidth?: number;
  /** Full lap duration in seconds. */
  duration?: number;
  /** Beam colour; defaults to accent. */
  beamColor?: string;
  /** Soft trailing colour. */
  beamFrom?: string;
  padding?: SpotlightCardBorderPadding;
  ref?: Ref<HTMLDivElement>;
}

const styles = sortCx({
  base: "bui-spotlight-card relative isolate overflow-hidden rounded-2xl border border-border-secondary-default bg-background-primary-default dark:bg-background-secondary-default",
  padding: {
    sm: "p-3",
    md: "p-4",
    lg: "p-6 sm:p-8",
  },
});

export function SpotlightCardBorder({
  children,
  className,
  size = 240,
  color,
  borderWidth = 1.5,
  duration = 9,
  beamColor,
  beamFrom,
  padding = "md",
  style,
  onMouseMove,
  onMouseLeave,
  ref,
  ...props
}: SpotlightCardBorderProps) {
  const localRef = useRef<HTMLDivElement | null>(null);
  const [pos, setPos] = useState({ x: 0, y: 0, on: false });

  const setRefs = useCallback(
    (node: HTMLDivElement | null) => {
      localRef.current = node;
      if (typeof ref === "function") ref(node);
      else if (ref) ref.current = node;
    },
    [ref],
  );

  const handleMove = (event: MouseEvent<HTMLDivElement>) => {
    const el = localRef.current;
    if (el) {
      const rect = el.getBoundingClientRect();
      setPos({
        x: event.clientX - rect.left,
        y: event.clientY - rect.top,
        on: true,
      });
    }
    onMouseMove?.(event);
  };

  const handleLeave = (event: MouseEvent<HTMLDivElement>) => {
    setPos((p) => ({ ...p, on: false }));
    onMouseLeave?.(event);
  };

  const spotColor =
    color ?? "color-mix(in oklab, var(--color-accent-500) 14%, transparent)";

  return (
    <div
      ref={setRefs}
      onMouseMove={handleMove}
      onMouseLeave={handleLeave}
      className={cx(
        "bui-border-beam relative isolate overflow-hidden rounded-2xl",
        className,
      )}
      style={
        {
          "--bui-spotlight-x": `${pos.x}px`,
          "--bui-spotlight-y": `${pos.y}px`,
          "--bui-spotlight-size": `${size}px`,
          "--bui-spotlight-color": spotColor,
          "--bui-spotlight-opacity": pos.on ? "1" : "0",
          "--bui-border-beam-width": `${borderWidth}px`,
          "--bui-border-beam-duration": `${duration}s`,
          "--bui-border-beam-color": beamColor ?? "var(--color-accent-500)",
          "--bui-border-beam-from": beamFrom ?? "var(--color-accent-300)",
          ...style,
        } as CSSProperties
      }
      {...props}
    >
      <div className={cx(styles.base, styles.padding[padding], "border-0")}>
        <span
          aria-hidden
          className="bui-spotlight-card-glow pointer-events-none absolute inset-0"
        />
        <div className="relative z-10 min-w-0">{children}</div>
      </div>
      <span
        aria-hidden
        className="bui-border-beam-glow pointer-events-none absolute inset-0 rounded-[inherit]"
      />
    </div>
  );
}

"use client";

import {
  useCallback,
  useEffect,
  useRef,
  useState,
  type CSSProperties,
  type HTMLAttributes,
  type MouseEvent,
  type ReactNode,
  type Ref,
} from "react";
import { cx, sortCx } from "@/lib/utils";

/**
 * Spotlight card with subtle pointer-driven 3D tilt.
 * Same surface language as SpotlightCard; tilt stays soft (≤8°) and
 * respects prefers-reduced-motion.
 *
 *   <SpotlightCardTilt>
 *     <p className="text-body-medium">Feature title</p>
 *   </SpotlightCardTilt>
 */

export type SpotlightCardTiltPadding = "sm" | "md" | "lg";

export interface SpotlightCardTiltProps extends HTMLAttributes<HTMLDivElement> {
  children?: ReactNode;
  /** Spotlight radius in px. */
  size?: number;
  /** Spotlight colour (defaults to accent at low alpha). */
  color?: string;
  /** Max tilt in degrees on each axis. Default 7. */
  maxTilt?: number;
  padding?: SpotlightCardTiltPadding;
  ref?: Ref<HTMLDivElement>;
}

const styles = sortCx({
  base: "bui-spotlight-card relative isolate overflow-hidden rounded-2xl border border-border-secondary-default bg-background-primary-default shadow-sm will-change-transform dark:bg-background-secondary-default",
  padding: {
    sm: "p-3",
    md: "p-4",
    lg: "p-6 sm:p-8",
  },
});

export function SpotlightCardTilt({
  children,
  className,
  size = 260,
  color,
  maxTilt = 7,
  padding = "md",
  style,
  onMouseMove,
  onMouseLeave,
  ref,
  ...props
}: SpotlightCardTiltProps) {
  const localRef = useRef<HTMLDivElement | null>(null);
  const [pos, setPos] = useState({ x: 0, y: 0, on: false });
  const [tilt, setTilt] = useState({ rx: 0, ry: 0 });
  const [reduceMotion, setReduceMotion] = useState(false);

  useEffect(() => {
    const mq = window.matchMedia("(prefers-reduced-motion: reduce)");
    const sync = () => setReduceMotion(mq.matches);
    sync();
    mq.addEventListener("change", sync);
    return () => mq.removeEventListener("change", sync);
  }, []);

  const setRefs = useCallback(
    (node: HTMLDivElement | null) => {
      localRef.current = node;
      if (typeof ref === "function") ref(node);
      else if (ref) ref.current = node;
    },
    [ref],
  );

  const handleMove = (event: MouseEvent<HTMLDivElement>) => {
    const el = localRef.current;
    if (el) {
      const rect = el.getBoundingClientRect();
      const x = event.clientX - rect.left;
      const y = event.clientY - rect.top;
      setPos({ x, y, on: true });
      if (!reduceMotion) {
        const nx = (x / rect.width) * 2 - 1;
        const ny = (y / rect.height) * 2 - 1;
        setTilt({
          rx: -ny * maxTilt,
          ry: nx * maxTilt,
        });
      }
    }
    onMouseMove?.(event);
  };

  const handleLeave = (event: MouseEvent<HTMLDivElement>) => {
    setPos((p) => ({ ...p, on: false }));
    setTilt({ rx: 0, ry: 0 });
    onMouseLeave?.(event);
  };

  const spotColor =
    color ?? "color-mix(in oklab, var(--color-accent-500) 16%, transparent)";

  return (
    <div
      className="[perspective:900px]"
      style={{ perspectiveOrigin: "50% 50%" }}
    >
      <div
        ref={setRefs}
        onMouseMove={handleMove}
        onMouseLeave={handleLeave}
        className={cx(styles.base, styles.padding[padding], className)}
        style={
          {
            "--bui-spotlight-x": `${pos.x}px`,
            "--bui-spotlight-y": `${pos.y}px`,
            "--bui-spotlight-size": `${size}px`,
            "--bui-spotlight-color": spotColor,
            "--bui-spotlight-opacity": pos.on ? "1" : "0",
            transform: reduceMotion
              ? undefined
              : `rotateX(${tilt.rx}deg) rotateY(${tilt.ry}deg)`,
            transition: reduceMotion
              ? undefined
              : "transform 180ms cubic-bezier(0.22, 1, 0.36, 1)",
            ...style,
          } as CSSProperties
        }
        {...props}
      >
        <span
          aria-hidden
          className="bui-spotlight-card-glow pointer-events-none absolute inset-0"
        />
        <div className="relative z-10 min-w-0">{children}</div>
      </div>
    </div>
  );
}

import type { HTMLAttributes, ReactNode, Ref } from "react";
import { RiCheckLine } from "@remixicon/react";
