/**
 * Tag group — a set of tags to filter by, pick from, or prune: topics,
 * skills, recipients, labels on a ticket.
 *
 *   <TagGroup label="Topics" selectionMode="multiple" defaultSelectedKeys={["design"]}>
 *     <Tag id="design">Design</Tag>
 *     <Tag id="engineering">Engineering</Tag>
 *   </TagGroup>
 *
 *   <TagGroup label="Skills" items={skills} onRemove={(keys) => drop(keys)}>
 *     {(skill) => <Tag>{skill.name}</Tag>}
 *   </TagGroup>
 *
 * Tags take Chip's colour pairs (neutral by default) at 28px, or 24px with
 * `size="small"`. With a `selectionMode`, tags toggle and a selected tag fills
 * with the accent colour. With `onRemove`, each tag gets a small remove
 * button and Backspace or Delete removes the focused tag.
 *
 * Built on React Aria's TagGroup, a grid: Tab enters it once, arrows move
 * between tags, Space and Enter toggle selection, and screen readers hear
 * the tag count, each label and whether it is selected.
 */

type IconComponent = ComponentType<{ className?: string; "aria-hidden"?: boolean | "true" | "false" }>;

export type TagSize = "medium" | "small";

const SizeContext = createContext<TagSize>("medium");

export interface TagGroupProps<T extends object> extends Omit<AriaTagGroupProps, "className" | "children"> {
  label?: ReactNode;
  hint?: ReactNode;
  /** Shown in place of the tags when there are none. */
  emptyState?: ReactNode;
  /** 28px tags (default) or 24px. */
  size?: TagSize;
  /** Tags from data; render each with the children function. */
  items?: Iterable<T>;
  children: ReactNode | ((item: T) => ReactNode);
  className?: string;
}

export function TagGroup<T extends object>({
  label,
  hint,
  emptyState,
  size = "medium",
  items,
  children,
  className,
  ...props
}: TagGroupProps<T>) {
  return (
    <AriaTagGroup {...props} className={cx("flex flex-col items-start gap-1.5", className)}>
      {label ? <Label>{label}</Label> : null}
      <SizeContext.Provider value={size}>
        <AriaTagList
          items={items}
          renderEmptyState={emptyState ? () => <span className="py-1 text-body-regular text-text-tertiary">{emptyState}</span> : undefined}
          className="flex flex-wrap gap-1.5 outline-none"
        >
          {children}
        </AriaTagList>
      </SizeContext.Provider>
      {hint ? <HintText>{hint}</HintText> : null}
    </AriaTagGroup>
  );
}

export interface TagProps extends Omit<AriaTagProps, "className" | "children"> {
  /** Chip's colour pairs. Default neutral. */
  color?: ChipColor;
  /** Remix Icon before the label. */
  icon?: IconComponent;
  className?: string;
  children: ReactNode;
}

export function Tag({ color = "neutral", icon: Icon, className, children, ...props }: TagProps) {
  const size = useContext(SizeContext);

  return (
    <AriaTag
      {...props}
      textValue={props.textValue ?? (typeof children === "string" ? children : undefined)}
      className={({ isSelected, selectionMode, allowsRemoving, isHovered, isFocusVisible, isDisabled }) => {
        const allowsSelection = selectionMode !== "none";
        return cx(
          "inline-flex max-w-full items-center gap-1 rounded-lg outline-none",
          "transition-[background-color,color,box-shadow,filter] duration-150 ease-out",
          size === "small" ? "h-6 px-1.5 text-caption-1-medium" : "h-7 px-2 text-body-medium",
          allowsRemoving && (size === "small" ? "pe-0.5" : "pe-1"),
          isSelected ? "bg-accent-500 text-white" : CHIP_COLORS[color],
          allowsSelection ? "cursor-pointer" : "cursor-default",
          allowsSelection && !isSelected && isHovered && (color === "neutral" ? "bg-background-tertiary-hover" : "brightness-95"),
          isFocusVisible && "ring-2 ring-border-focus-ring",
          isDisabled && "cursor-not-allowed opacity-50",
          className,
        );
      }}
    >
      {({ allowsRemoving }) => (
        <>
          {Icon ? <Icon aria-hidden className={cx("shrink-0", size === "small" ? "size-3.5" : "size-4")} /> : null}
          <span className="truncate">{children}</span>
          {allowsRemoving ? (
            <AriaButton
              slot="remove"
              className={cx(
                "flex shrink-0 cursor-pointer items-center justify-center rounded-md opacity-60 outline-none",
                "transition-[opacity,background-color] duration-150 ease-out hover:bg-current/15 hover:opacity-100",
                size === "small" ? "size-4" : "size-5",
              )}
            >
              <RiCloseLine aria-hidden className={size === "small" ? "size-3" : "size-3.5"} />
            </AriaButton>
          ) : null}
        </>
      )}
    </AriaTag>
  );
}

"use client";

import {
  useCallback,
  useId,
  useRef,
  useState,
  type KeyboardEvent,
  type ReactNode,
  type Ref,
} from "react";
import { RiCloseLine } from "@remixicon/react";
import { HintText } from "../input/hint-text";
import { Label } from "../input/label";
import { cx } from "@/lib/utils";

/**
 * Multi-value tag field — type + Enter / comma to add, Backspace removes the
 * last tag. Shell matches Input (tertiary fill, 2lg radius).
 *
 *   <TagInput label="标签" value={tags} onChange={setTags} placeholder="添加标签" />
 */

export interface TagInputProps {
  label?: ReactNode;
  hint?: ReactNode;
  placeholder?: string;
  value?: string[];
  defaultValue?: string[];
  onChange?: (tags: string[]) => void;
  /** Delimiters that commit the draft. Default Enter + comma. */
  delimiters?: string[];
  maxTags?: number;
  isDisabled?: boolean;
  isInvalid?: boolean;
  isRequired?: boolean;
  size?: "medium" | "small";
  className?: string;
  ref?: Ref<HTMLDivElement>;
}

function normalize(raw: string) {
  return raw.trim().replace(/\s+/g, " ");
}

export function TagInput({
  label,
  hint,
  placeholder = "添加…",
  value,
  defaultValue = [],
  onChange,
  delimiters = [",", "Enter"],
  maxTags,
  isDisabled = false,
  isInvalid = false,
  isRequired = false,
  size = "medium",
  className,
  ref,
}: TagInputProps) {
  const inputId = useId();
  const inputRef = useRef<HTMLInputElement>(null);
  const [draft, setDraft] = useState("");
  const [uncontrolled, setUncontrolled] = useState(defaultValue);
  const tags = value ?? uncontrolled;

  const commit = useCallback(
    (next: string[]) => {
      if (value === undefined) setUncontrolled(next);
      onChange?.(next);
    },
    [onChange, value],
  );

  const addTag = (raw: string) => {
    const text = normalize(raw);
    if (!text || isDisabled) return;
    if (maxTags != null && tags.length >= maxTags) return;
    if (tags.some((t) => t.toLowerCase() === text.toLowerCase())) {
      setDraft("");
      return;
    }
    commit([...tags, text]);
    setDraft("");
  };

  const removeAt = (index: number) => {
    if (isDisabled) return;
    commit(tags.filter((_, i) => i !== index));
  };

  const onKeyDown = (event: KeyboardEvent<HTMLInputElement>) => {
    if (delimiters.includes(event.key)) {
      event.preventDefault();
      addTag(draft);
      return;
    }
    if (event.key === "Backspace" && !draft && tags.length > 0) {
      removeAt(tags.length - 1);
    }
  };

  return (
    <div ref={ref} className={cx("flex w-full flex-col gap-1.5", className)}>
      {label ? (
        <Label htmlFor={inputId} isRequired={isRequired} isInvalid={isInvalid}>
          {label}
        </Label>
      ) : null}
      <div
        data-disabled={isDisabled || undefined}
        data-invalid={isInvalid || undefined}
        onClick={() => inputRef.current?.focus()}
        className={cx(
          "flex w-full flex-wrap items-center gap-1.5 rounded-2lg",
          "bg-background-tertiary-default text-foreground-icon-tertiary",
          // Match Input well: secondary idle ring, button hover/focus, error.
          "ring-2 ring-inset ring-border-secondary-default",
          "transition-[background-color,box-shadow] duration-[var(--input-transition-ms)] ease",
          "hover:ring-border-button-hover focus-within:ring-border-button-active",
          "data-invalid:bg-background-tertiary-error data-invalid:ring-border-error-default",
          "data-disabled:cursor-not-allowed data-disabled:bg-input-disabled-background data-disabled:opacity-60",
          size === "medium" ? "min-h-9 p-2" : "min-h-8 px-1.5 py-1.5",
        )}
      >
        {tags.map((tag, index) => (
          <span
            key={`${tag}-${index}`}
            className={cx(
              "inline-flex max-w-full items-center gap-0.5 rounded-md",
              "bg-background-primary-default px-1.5 py-0.5",
              "text-caption-1-medium text-text-primary shadow-2xs",
            )}
          >
            <span className="truncate">{tag}</span>
            <button
              type="button"
              tabIndex={-1}
              aria-label={`移除 ${tag}`}
              disabled={isDisabled}
              onClick={(e) => {
                e.stopPropagation();
                removeAt(index);
              }}
              className={cx(
                "inline-flex size-4 items-center justify-center rounded-sm",
                "text-foreground-icon-quaternary",
                "hover:bg-background-tertiary-default hover:text-text-primary",
                "disabled:pointer-events-none",
              )}
            >
              <RiCloseLine className="size-3" aria-hidden />
            </button>
          </span>
        ))}
        <input
          ref={inputRef}
          id={inputId}
          value={draft}
          disabled={isDisabled || (maxTags != null && tags.length >= maxTags)}
          placeholder={tags.length === 0 ? placeholder : undefined}
          aria-invalid={isInvalid || undefined}
          onChange={(e) => setDraft(e.target.value)}
          onKeyDown={onKeyDown}
          onBlur={() => {
            if (draft.trim()) addTag(draft);
          }}
          className={cx(
            "min-w-[7rem] flex-1 border-0 bg-transparent p-0 outline-none",
            "font-sans text-body-regular text-text-primary",
            "placeholder:text-text-tertiary",
            "disabled:cursor-not-allowed",
          )}
        />
      </div>
      {hint ? <HintText isInvalid={isInvalid}>{hint}</HintText> : null}
    </div>
  );
}

"use client";

import { cloneElement, createContext, isValidElement, useContext, useMemo, type ReactNode } from "react";

export type TemplateCopyTranslator = (text: string) => string;
type CopySettings = { translate: TemplateCopyTranslator; render?: <T>(node: T) => T };
const CopyContext = createContext<CopySettings | null>(null);
const MenuContext = createContext<ReactNode>(null);

/** Optional application language control shared by template account menus. */
export function TemplateMenuProvider({ languageSelector, children }: { languageSelector?: ReactNode; children: ReactNode }) {
  return <MenuContext.Provider value={languageSelector ?? null}>{children}</MenuContext.Provider>;
}

export function useTemplateLanguageSelector() {
  return useContext(MenuContext);
}

/** Optional application copy for templates. Without a provider, source copy is unchanged. */
export function TemplateCopyProvider({ translate, render, children }: CopySettings & { children: ReactNode }) {
  const settings = useMemo(() => ({ translate, render }), [translate, render]);
  return <CopyContext.Provider value={settings}>{children}</CopyContext.Provider>;
}

// Only display copy is translated. IDs, form values, data keys, URLs, styles,
// event handlers and application state retain their original values.
const textProps = new Set([
  "children", "title", "subtitle", "description", "label", "textValue", "placeholder", "alt",
  "aria-label", "aria-description", "metricLabel", "emptyMessage", "caption", "heading", "text", "content", "renderValue",
]);
const dataProps = new Set(["items", "options", "tabs", "columns", "series", "ranges", "stats", "data", "nodes", "bar", "line"]);
const dataText = new Set(["label", "title", "description", "subtitle", "header", "role", "joined"]);
const renderProps = new Set(["children", "cell", "header", "formatter", "tickFormatter", "labelFormatter", "renderItem", "node", "link", "tick", "label", "content", "renderValue"]);

/** Translate rendered copy while preserving React nodes, collection IDs and callbacks. */
export function translateTemplateCopy<T>(value: T, translate: TemplateCopyTranslator): T {
  function visit(value: unknown, data = false): unknown {
    if (typeof value === "string") return data ? value : translate(value);
    if (Array.isArray(value)) {
      // Static JSX children are an unkeyed array; remapping them without keys
      // triggers React's "unique key prop" warning (e.g. breadcrumb catalog card).
      let changed = false;
      const result = value.map((item, index) => {
        const visited = visit(item, data);
        if (visited !== item) changed = true;
        if (isValidElement(visited) && visited.key == null) {
          changed = true;
          return cloneElement(visited, { key: `.$tc-${index}` });
        }
        return visited;
      });
      return changed ? result : value;
    }
    if (isValidElement<Record<string, unknown>>(value)) {
      if (typeof value.type === "string" && ["pre", "code", "kbd", "script", "style"].includes(value.type)) return value;
      const updates: Record<string, unknown> = {};
      for (const [key, original] of Object.entries(value.props)) {
        if (textProps.has(key)) updates[key] = renderProps.has(key) && typeof original === "function"
          ? (...args: unknown[]) => visit(original(...args)) : visit(original);
        else if (dataProps.has(key)) updates[key] = visit(original, true);
        else if (renderProps.has(key) && typeof original === "function") updates[key] = (...args: unknown[]) => visit(original(...args));
      }
      return Object.entries(updates).some(([key, result]) => result !== value.props[key]) ? cloneElement(value, updates) : value;
    }
    if (data && value && typeof value === "object" && Object.getPrototypeOf(value) === Object.prototype) {
      const result: Record<string, unknown> = { ...value };
      for (const [key, original] of Object.entries(result)) {
        if (renderProps.has(key) && typeof original === "function") result[key] = (...args: unknown[]) => visit(original(...args));
        else if (dataText.has(key)) result[key] = visit(original);
        else if (original && typeof original === "object") result[key] = visit(original, true);
      }
      return Object.entries(result).some(([key, item]) => item !== (value as Record<string, unknown>)[key]) ? result : value;
    }
    return value;
  }
  return visit(value) as T;
}

/** Apply to a template component's returned JSX; copy updates through React, including portals. */
export function useTemplateCopy() {
  const settings = useContext(CopyContext);
  return useMemo(() => <T,>(node: T): T => settings?.render ? settings.render(node) : settings ? translateTemplateCopy(node, settings.translate) : node, [settings]);
}

import type { AnchorHTMLAttributes, ReactNode, Ref } from "react";
import { cx, sortCx } from "@/lib/utils";

/**
 * Inline text link with brand colour and underline-on-hover.
 * Prefer this over bare `<a className="text-text-brand-primary">`.
 */

export type TextLinkSize = "sm" | "md";

export interface TextLinkProps extends AnchorHTMLAttributes<HTMLAnchorElement> {
  size?: TextLinkSize;
  children?: ReactNode;
  /** Soften the link (secondary text colour, brand on hover). */
  muted?: boolean;
  ref?: Ref<HTMLAnchorElement>;
}

const styles = sortCx({
  base: "inline underline-offset-2 transition-colors hover:underline focus-visible:outline-none focus-visible:ring-2 focus-visible:ring-border-focus-ring rounded-sm",
  size: {
    sm: "text-body-2-regular",
    md: "text-body-regular",
  },
  tone: {
    default: "text-text-brand-primary",
    muted: "text-text-secondary hover:text-text-brand-primary",
  },
});

export function TextLink({
  size = "md",
  muted = false,
  className,
  ref,
  children,
  ...props
}: TextLinkProps) {
  return (
    <a
      ref={ref}
      className={cx(
        styles.base,
        styles.size[size],
        muted ? styles.tone.muted : styles.tone.default,
        className,
      )}
      {...props}
    >
      {children}
    </a>
  );
}

import type { CSSProperties, HTMLAttributes, ReactNode, Ref } from "react";
import { cx } from "@/lib/utils";

/**
 * Sweeping highlight across text — Bencho / Watermelon loading copy and
 * AI “thinking” labels without a spinner.
 *
 *   <TextShimmer>Generating reply…</TextShimmer>
 *
 * Note: agent-log also exports a private-style `ShimmerText` helper; prefer
 * this base `TextShimmer` for product UI.
 */

export interface TextShimmerProps extends HTMLAttributes<HTMLSpanElement> {
  children?: ReactNode;
  /** Full sweep duration in seconds. */
  duration?: number;
  ref?: Ref<HTMLSpanElement>;
}

export function TextShimmer({
  children,
  className,
  duration = 2.4,
  style,
  ref,
  ...props
}: TextShimmerProps) {
  return (
    <span
      ref={ref}
      className={cx("bui-shimmer-text inline-block text-body-medium text-text-secondary", className)}
      style={
        {
          "--bui-shimmer-duration": `${duration}s`,
          ...style,
        } as CSSProperties
      }
      {...props}
    >
      {children}
    </span>
  );
}

"use client";

import {
  useContext,
  useLayoutEffect,
  useRef,
  useState,
  type ReactNode,
  type Ref,
} from "react";
import { Group as AriaGroup, TextArea as AriaTextArea } from "react-aria-components";
import type { TextAreaProps as AriaTextAreaProps } from "react-aria-components";
import { HintText } from "../input/hint-text";
import { Label } from "../input/label";
import {
  TextField,
  TextFieldContext,
  type InputSize,
  type TextFieldProps,
} from "../input/input";
import { cx, sortCx } from "@/lib/utils";

/**
 * Multiline sibling of `Input` — same React Aria plumbing, same field shell,
 * same tokens. It reuses `Input`'s `TextField`, `Label` and `HintText`, so a
 * textarea sitting next to an input in a form lines up to the pixel.
 *
 * Architecture (mirrors input.tsx):
 *
 *   TextareaBase — the styled shell. Renders <AriaGroup> + <AriaTextArea>.
 *                  State (hover / focus / disabled / invalid) arrives as
 *                  render-prop booleans from Aria.
 *   Textarea     — opinionated composition: TextField → Label → TextareaBase
 *                  → HintText (+ optional character counter). The component
 *                  most consumers use.
 *
 * What a textarea adds over the single-line field:
 *   - `rows` sets the resting height (3 lines by default)
 *   - `autoResize` grows the field a line at a time up to `maxRows`, then
 *     scrolls — the pattern the composer prompt uses
 *   - `resize` exposes the native grab handle, off when `autoResize` is on
 *   - `showCount` pairs with `maxLength` for the counter settings pages want
 */

type TextareaSize = InputSize;

export type TextareaResize = "none" | "vertical";

/* -------------------------------------------------------------------------- */
/*  TextareaBase                                                               */
/* -------------------------------------------------------------------------- */

export interface TextareaBaseProps
  extends Omit<AriaTextAreaProps, "size" | "className" | "rows"> {
  size?: TextareaSize;
  className?: string;
  /** Resting height, in lines. Also the floor when `autoResize` is on. */
  rows?: number;
  /** Grow with the content instead of scrolling at `rows`. */
  autoResize?: boolean;
  /** Ceiling for `autoResize`, in lines. Past it the field scrolls. */
  maxRows?: number;
  /** Native resize handle. Ignored (forced `none`) while `autoResize` is on. */
  resize?: TextareaResize;
  /** Class for the field shell. */
  fieldClassName?: string;
  /** Ref to the <textarea> element. */
  ref?: Ref<HTMLTextAreaElement>;
  /** Ref to the field shell wrapper. */
  groupRef?: Ref<HTMLDivElement>;
}

const textareaStyles = sortCx({
  field: [
    "relative flex w-full flex-col",
    "rounded-2lg",
    "bg-background-tertiary-default text-foreground-icon-tertiary",
    // Same idle ring as Input well so stacked fields share one grey.
    "ring-2 ring-inset ring-border-secondary-default",
    "transition-[background-color,box-shadow,color] duration-[var(--input-transition-ms)] ease",
  ].join(" "),

  // Matches Input's insets, so a stacked input and textarea share one edge:
  // 8px shell + 4px on the control = 12px to the text (10px at `small`).
  fieldSize: {
    medium: "p-2",
    small: "px-1.5 py-2",
  },

  textarea: [
    "block w-full min-w-0 bg-transparent border-0 outline-none m-0 p-0 px-1",
    "font-sans text-body-regular text-text-primary",
    "placeholder:text-text-tertiary",
    "focus:placeholder:text-text-primary",
    "disabled:text-input-disabled-text disabled:placeholder:text-input-disabled-text",
    "disabled:cursor-not-allowed",
    "aria-invalid:placeholder:text-text-error-placeholder",
  ].join(" "),

  resize: {
    none: "resize-none",
    vertical: "resize-y",
  },

  footer: "flex w-full items-start justify-between gap-3",
  count: "ms-auto shrink-0 pt-px text-caption-1-medium text-text-tertiary tabular-nums",
});

/** Fallback line box for `text-body-regular` (14/20) before styles resolve. */
const FALLBACK_LINE_HEIGHT = 20;

export function TextareaBase({
  size: sizeProp,
  rows = 3,
  autoResize = false,
  maxRows,
  resize = "vertical",
  fieldClassName,
  className,
  ref,
  groupRef,
  onInput,
  ...textareaProps
}: TextareaBaseProps) {
  const ctx = useContext(TextFieldContext);
  const size: TextareaSize = sizeProp ?? ctx.size ?? "medium";
  const innerRef = useRef<HTMLTextAreaElement | null>(null);

  const attachRef = (node: HTMLTextAreaElement | null) => {
    innerRef.current = node;
    if (typeof ref === "function") ref(node);
    else if (ref) (ref as { current: HTMLTextAreaElement | null }).current = node;
  };

  // Measure from zero so the field shrinks back as well as grows. Reading the
  // computed line box keeps the floor and ceiling honest when a consumer
  // overrides the type scale through `className`.
  const fit = () => {
    const field = innerRef.current;
    if (!field) return;
    if (!autoResize) {
      field.style.height = "";
      field.style.maxHeight = "";
      field.style.overflowY = "";
      return;
    }
    const line =
      parseFloat(window.getComputedStyle(field).lineHeight) || FALLBACK_LINE_HEIGHT;
    const ceiling = maxRows ? maxRows * line : Infinity;
    field.style.height = "0px";
    const next = Math.max(field.scrollHeight, rows * line);
    field.style.height = `${Math.min(next, ceiling)}px`;
    field.style.maxHeight = maxRows ? `${ceiling}px` : "";
    field.style.overflowY = next > ceiling ? "auto" : "hidden";
  };

  // No dependency list: typing on an uncontrolled field re-renders nothing,
  // so `onInput` handles keystrokes and this catches every other reason the
  // value moved (a controlled parent, a form reset, an autofill).
  useLayoutEffect(fit);

  return (
    <AriaGroup
      ref={groupRef}
      className={({ isFocusWithin, isHovered, isDisabled, isInvalid }) =>
        cx(
          textareaStyles.field,
          textareaStyles.fieldSize[size],
          // Hover: idle, no focus, no disabled, no invalid
          isHovered &&
            !isFocusWithin &&
            !isDisabled &&
            !isInvalid &&
            "ring-border-button-hover",
          // Focus wins over hover
          isFocusWithin &&
            !isDisabled &&
            !isInvalid &&
            "ring-border-button-active",
          // Disabled
          isDisabled &&
            "bg-input-disabled-background text-input-disabled-foreground",
          // Invalid
          isInvalid && "bg-background-tertiary-error text-foreground-icon-error",
          ctx.fieldClassName,
          fieldClassName,
        )
      }
    >
      <AriaTextArea
        ref={attachRef}
        rows={rows}
        {...textareaProps}
        onInput={(event) => {
          fit();
          onInput?.(event);
        }}
        className={cx(
          textareaStyles.textarea,
          textareaStyles.resize[autoResize ? "none" : resize],
          ctx.inputClassName,
          className,
        )}
      />
    </AriaGroup>
  );
}

TextareaBase.displayName = "TextareaBase";

/* -------------------------------------------------------------------------- */
/*  Textarea (composed)                                                        */
/* -------------------------------------------------------------------------- */

export interface TextareaProps
  extends Omit<TextFieldProps, "children">,
    Pick<
      TextareaBaseProps,
      | "rows"
      | "autoResize"
      | "maxRows"
      | "resize"
      | "fieldClassName"
      | "groupRef"
      | "ref"
    > {
  label?: ReactNode;
  hint?: ReactNode;
  /** Show an info icon next to the label. Replace with tooltip when Tooltip lands. */
  tooltip?: boolean | string;
  placeholder?: string;
  /** Hard character limit, enforced by the browser. */
  maxLength?: number;
  /** Show the character counter under the field (`12/280` with `maxLength`). */
  showCount?: boolean;
}

export function Textarea({
  label,
  hint,
  tooltip,
  placeholder,
  rows,
  autoResize,
  maxRows,
  resize,
  maxLength,
  showCount = false,
  fieldClassName,
  ref,
  groupRef,
  className,
  value,
  defaultValue,
  onChange,
  ...textFieldProps
}: TextareaProps) {
  // The counter needs the value, and React Aria's render props don't carry it.
  // Controlled fields read straight from the prop; uncontrolled ones keep the
  // length here so a keystroke re-renders the counter and nothing else.
  const [typedLength, setTypedLength] = useState(() => (defaultValue ?? "").length);
  const count = value !== undefined ? value.length : typedLength;

  return (
    <TextField
      {...textFieldProps}
      value={value}
      defaultValue={defaultValue}
      onChange={(next) => {
        if (showCount && value === undefined) setTypedLength(next.length);
        onChange?.(next);
      }}
      className={className}
      // Don't clobber an explicit aria-label; fall back to the placeholder
      // only for unlabelled fields that don't provide one.
      aria-label={
        textFieldProps["aria-label"] ??
        (!label && typeof placeholder === "string" ? placeholder : undefined)
      }
    >
      {({ isRequired, isInvalid }) => (
        <>
          {label && (
            <Label
              isRequired={isRequired}
              isInvalid={isInvalid}
              tooltip={tooltip}
            >
              {label}
            </Label>
          )}
          <TextareaBase
            ref={ref}
            groupRef={groupRef}
            placeholder={placeholder}
            rows={rows}
            autoResize={autoResize}
            maxRows={maxRows}
            resize={resize}
            maxLength={maxLength}
            fieldClassName={fieldClassName}
          />
          {(hint || showCount) && (
            <div className={textareaStyles.footer}>
              {hint && <HintText isInvalid={isInvalid}>{hint}</HintText>}
              {showCount && (
                <span
                  className={cx(
                    textareaStyles.count,
                    isInvalid && "text-text-error-primary",
                  )}
                >
                  {maxLength ? `${count}/${maxLength}` : count}
                </span>
              )}
            </div>
          )}
        </>
      )}
    </TextField>
  );
}

Textarea.displayName = "Textarea";

"use client";

import { useTemplateCopy } from "../../foundations/template-copy/template-copy";

import { useEffect, useRef, useSyncExternalStore } from "react";
import { flushSync } from "react-dom";
import { RiMoonLine, RiSunLine } from "@remixicon/react";
import { Switch as AriaSwitch } from "react-aria-components";
import { SwitchTrack } from "../../base/switch/switch";
import { cx } from "@/lib/utils";

export type ThemeMode = "light" | "dark";

export const THEME_STORAGE_KEY = "JoyUI:theme";
export const THEME_CHANGE_EVENT = "JoyUI:theme-change";

const THEME_TRANSITION_DURATION = 820;
const THEME_TRANSITION_EASING = "cubic-bezier(0.16, 1, 0.3, 1)";
const THEME_TRANSITION_STYLE_ID = "JoyUI-theme-transition-style";

type ThemeTransitionOrigin = { x: number; y: number };

type ViewTransition = {
  ready: Promise<void>;
  finished: Promise<void>;
};

type ViewTransitionDocument = Document & {
  startViewTransition?: (update: () => void) => ViewTransition;
};

let themeTransitionRunning = false;

function createBlurCircleMask() {
  const svg = [
    '<svg xmlns="http://www.w3.org/2000/svg" viewBox="0 0 100 100">',
    '<defs><filter id="blur" x="-50%" y="-50%" width="200%" height="200%">',
    '<feGaussianBlur stdDeviation="2" /></filter></defs>',
    '<circle cx="50" cy="50" r="42" fill="white" filter="url(#blur)" />',
    "</svg>",
  ].join("");

  return `url("data:image/svg+xml,${encodeURIComponent(svg)}")`;
}

function installThemeTransitionStyle(
  { x, y }: ThemeTransitionOrigin,
  radius: number,
  duration: number,
) {
  document.getElementById(THEME_TRANSITION_STYLE_ID)?.remove();

  const mask = createBlurCircleMask();
  const finalMaskSize = radius * 2.5;
  const finalMaskX = x - finalMaskSize / 2;
  const finalMaskY = y - finalMaskSize / 2;
  const style = document.createElement("style");
  style.id = THEME_TRANSITION_STYLE_ID;
  style.textContent = `
    ::view-transition-new(root) {
      -webkit-mask-image: ${mask};
      mask-image: ${mask};
      -webkit-mask-repeat: no-repeat;
      mask-repeat: no-repeat;
      animation: JoyUI-theme-mask-reveal ${duration}ms ${THEME_TRANSITION_EASING} both;
      transform-origin: ${x}px ${y}px;
      will-change: -webkit-mask-size, -webkit-mask-position, mask-size, mask-position;
    }

    @keyframes JoyUI-theme-mask-reveal {
      from {
        -webkit-mask-position: ${x}px ${y}px;
        mask-position: ${x}px ${y}px;
        -webkit-mask-size: 0px 0px;
        mask-size: 0px 0px;
      }
      to {
        -webkit-mask-position: ${finalMaskX}px ${finalMaskY}px;
        mask-position: ${finalMaskX}px ${finalMaskY}px;
        -webkit-mask-size: ${finalMaskSize}px ${finalMaskSize}px;
        mask-size: ${finalMaskSize}px ${finalMaskSize}px;
      }
    }
  `;
  document.head.appendChild(style);
  return style;
}

function storedTheme(): ThemeMode {
  if (typeof window === "undefined") return "light";
  try {
    return window.localStorage.getItem(THEME_STORAGE_KEY) === "dark" ? "dark" : "light";
  } catch {
    return "light";
  }
}

export function applyTheme(theme: ThemeMode, { persist = true }: { persist?: boolean } = {}) {
  if (typeof document === "undefined") return;
  document.documentElement.classList.toggle("dark", theme === "dark");
  if (persist) {
    try {
      window.localStorage.setItem(THEME_STORAGE_KEY, theme);
    } catch {
      // The control remains usable when storage is blocked or unavailable.
    }
  }
  window.dispatchEvent(new CustomEvent(THEME_CHANGE_EVENT, { detail: theme }));
}

function elementCenter(element: HTMLElement | null): ThemeTransitionOrigin {
  if (!element) {
    return { x: window.innerWidth / 2, y: window.innerHeight / 2 };
  }
  const rect = element.getBoundingClientRect();
  return { x: rect.left + rect.width / 2, y: rect.top + rect.height / 2 };
}

function normalizedOrigin(
  origin: ThemeTransitionOrigin | null,
  element: HTMLElement | null,
): ThemeTransitionOrigin {
  const fallback = elementCenter(element);
  const x = origin?.x ?? fallback.x;
  const y = origin?.y ?? fallback.y;
  return {
    x: Math.min(Math.max(x, 0), window.innerWidth),
    y: Math.min(Math.max(y, 0), window.innerHeight),
  };
}

/**
 * Reveals the next theme from the interaction point using the View Transition
 * API. Keyboard activation starts at the control's center. Unsupported
 * browsers and reduced-motion users receive the same immediate theme change.
 */
export async function applyThemeWithTransition(
  theme: ThemeMode,
  {
    origin = null,
    element = null,
    duration = THEME_TRANSITION_DURATION,
  }: {
    origin?: ThemeTransitionOrigin | null;
    element?: HTMLElement | null;
    duration?: number;
  } = {},
) {
  if (typeof document === "undefined" || currentTheme() === theme) return;

  const transitionDocument = document as ViewTransitionDocument;
  const reduceMotion = window.matchMedia("(prefers-reduced-motion: reduce)").matches;
  if (!transitionDocument.startViewTransition || reduceMotion) {
    applyTheme(theme);
    return;
  }
  if (themeTransitionRunning) return;

  const { x, y } = normalizedOrigin(origin, element);
  const radius = Math.hypot(
    Math.max(x, window.innerWidth - x),
    Math.max(y, window.innerHeight - y),
  );

  themeTransitionRunning = true;
  document.documentElement.classList.add("theme-transitioning");
  const transitionStyle = installThemeTransitionStyle({ x, y }, radius, duration);
  try {
    const transition = transitionDocument.startViewTransition(() => {
      flushSync(() => applyTheme(theme));
    });

    await transition.ready;
    await transition.finished;
  } catch {
    // If the browser aborts a transition mid-flight, the theme still changes.
    if (currentTheme() !== theme) applyTheme(theme);
  } finally {
    transitionStyle.remove();
    document.documentElement.classList.remove("theme-transitioning");
    themeTransitionRunning = false;
  }
}

function currentTheme(): ThemeMode {
  if (typeof document === "undefined") return "light";
  return document.documentElement.classList.contains("dark") ? "dark" : "light";
}

function subscribe(onStoreChange: () => void) {
  const onThemeChange = () => onStoreChange();
  const onStorage = (event: StorageEvent) => {
    if (event.key !== THEME_STORAGE_KEY) return;
    applyTheme(event.newValue === "dark" ? "dark" : "light", { persist: false });
  };
  window.addEventListener(THEME_CHANGE_EVENT, onThemeChange);
  window.addEventListener("storage", onStorage);
  return () => {
    window.removeEventListener(THEME_CHANGE_EVENT, onThemeChange);
    window.removeEventListener("storage", onStorage);
  };
}

export function useThemeMode(): ThemeMode {
  return useSyncExternalStore(subscribe, currentTheme, () => "light");
}

export interface ThemeToggleProps {
  /** Compact icon-only treatment for a collapsed sidebar rail. */
  collapsed?: boolean;
  /**
   * Visual treatment for the control. `glass-segmented` is the landing nav's
   * skin: literal black/white rather than theme tokens, because it sits on the
   * hero shader's near-white band in both themes and a token that follows the
   * page would invert out of sight in dark mode.
   */
  appearance?: "sidebar" | "segmented" | "sidebar-segmented" | "glass-segmented";
  className?: string;
  /** Size of segmented controls; small fits inside dropdown rows. */
  size?: "small" | "medium";
  /** Circular reveal duration in milliseconds. */
  transitionDuration?: number;
}

/** Manual light/dark control. It never reads the operating-system theme. */
export function ThemeToggle({
  collapsed = false,
  appearance = "sidebar",
  className,
  size = "medium",
  transitionDuration = THEME_TRANSITION_DURATION,
}: ThemeToggleProps) {
  const localize = useTemplateCopy();
  const theme = useThemeMode();
  const dark = theme === "dark";
  const switchRef = useRef<HTMLLabelElement | null>(null);
  const pointerOriginRef = useRef<ThemeTransitionOrigin | null>(null);

  // Makes the component self-contained in customer projects. JoyUI itself
  // also runs the same lookup before hydration to avoid a first-paint flash.
  useEffect(() => {
    applyTheme(storedTheme(), { persist: false });
  }, []);

  if (
    appearance === "segmented" ||
    appearance === "sidebar-segmented" ||
    appearance === "glass-segmented"
  ) {
    const glass = appearance === "glass-segmented";
    const small = size === "small" && !glass;
    const sidebarSurface = appearance === "sidebar-segmented";
    const options = [
      { mode: "light" as const, label: "Use light mode", Icon: RiSunLine },
      { mode: "dark" as const, label: "Use dark mode", Icon: RiMoonLine },
    ];

    return localize((
      <div
        role="group"
        aria-label="Theme"
        className={cx(
          "relative inline-flex w-fit items-center gap-1 rounded-full p-1",
          // Mobile: 2px padding + 28px segments = 32px tall, matching the
          // small icon buttons beside it. Desktop keeps the roomier 40px.
          glass && "p-0.5 sm:p-1",
          small && "gap-0.5 p-0.5",
          glass
            ? // No track of its own: the host supplies the surface. A fill
              // here would paint over it. Kept registry-safe — this component
              // never imports the landing page's glass.
              "z-10 bg-transparent"
            : sidebarSurface
              ? "bg-theme-toggle-sidebar-background"
              : "bg-background-secondary-default",
          className,
        )}
      >
        <span
          aria-hidden
          className={cx(
            "pointer-events-none absolute top-1 start-1 size-8 rounded-full",
            "shadow-xs transition-transform duration-200 ease",
            glass && "top-0.5 start-0.5 size-7 sm:top-1 sm:start-1 sm:size-8",
            small && "top-0.5 start-0.5 size-6",
            glass
              ? "bg-white dark:bg-[#2e2e33]"
              : sidebarSurface
                ? "bg-theme-toggle-sidebar-selected-background"
                : "bg-background-primary-default",
            // Segment width + the 4px gap: 28+4 on mobile, 32+4 above it.
            dark && (small ? "translate-x-6.5 rtl:-translate-x-6.5" : glass ? "translate-x-8 rtl:-translate-x-8 sm:translate-x-9 sm:rtl:-translate-x-9" : "translate-x-9 rtl:-translate-x-9"),
          )}
        />
        {options.map(({ mode, label, Icon }) => {
          const selected = theme === mode;
          return (
            <button
              key={mode}
              type="button"
              aria-label={label}
              aria-pressed={selected}
              title={mode === "light" ? "Light mode" : "Dark mode"}
              onClick={(event) => {
                if (selected) return;
                const pointerOrigin =
                  event.clientX === 0 && event.clientY === 0
                    ? null
                    : { x: event.clientX, y: event.clientY };
                void applyThemeWithTransition(mode, {
                  origin: pointerOrigin,
                  element: event.currentTarget,
                  duration: transitionDuration,
                });
              }}
              className={cx(
                "relative z-10 grid size-8 cursor-pointer place-items-center rounded-full outline-none",
                glass && "size-7 sm:size-8",
                small && "size-6",
                "transition-colors duration-150 ease",
                "focus-visible:ring-2 focus-visible:ring-border-focus-ring",
                glass
                  ? selected
                    ? // Reads against the selected pill, which is white in
                      // light and dark grey in dark — so it flips with it.
                      "text-black dark:text-white"
                    : "text-black/45 hover:text-black/70 dark:text-white/45 dark:hover:text-white/70"
                  : selected
                    ? "text-foreground-icon-primary"
                    : "text-foreground-icon-secondary hover:text-foreground-icon-primary",
              )}
            >
              <Icon className={small ? "size-3.5" : "size-4"} aria-hidden />
            </button>
          );
        })}
      </div>
    ));
  }

  if (collapsed) {
    const Icon = dark ? RiSunLine : RiMoonLine;
    return localize((
      <button
        type="button"
        aria-label={dark ? "Use light mode" : "Use dark mode"}
        aria-pressed={dark}
        title={dark ? "Light mode" : "Dark mode"}
        onClick={(event) => {
          const pointerOrigin =
            event.clientX === 0 && event.clientY === 0
              ? null
              : { x: event.clientX, y: event.clientY };
          void applyThemeWithTransition(dark ? "light" : "dark", {
            origin: pointerOrigin,
            element: event.currentTarget,
            duration: transitionDuration,
          });
        }}
        className={cx(
          "flex size-9 cursor-pointer items-center justify-center rounded-2lg",
          "text-foreground-icon-secondary transition-colors duration-150 ease",
          "hover:bg-background-secondary-hover hover:text-foreground-icon-primary",
          "outline-none focus-visible:ring-2 focus-visible:ring-border-focus-ring",
          className,
        )}
      >
        <Icon className="size-5" aria-hidden />
      </button>
    ));
  }

  return localize((
    <AriaSwitch
      ref={switchRef}
      isSelected={dark}
      onPointerDown={(event) => {
        pointerOriginRef.current = { x: event.clientX, y: event.clientY };
      }}
      onChange={(selected) => {
        const origin = pointerOriginRef.current;
        pointerOriginRef.current = null;
        void applyThemeWithTransition(selected ? "dark" : "light", {
          origin,
          element: switchRef.current,
          duration: transitionDuration,
        });
      }}
      aria-label="Dark mode"
      className={({ isFocusVisible }) =>
        cx(
          "flex w-full cursor-pointer items-center justify-between rounded-2lg p-2",
          "transition-colors duration-150 ease hover:bg-background-secondary-hover",
          isFocusVisible && "ring-2 ring-inset ring-border-focus-ring",
          className,
        )
      }
    >
      {(state) => (
        <>
          <span className="flex min-w-0 items-center gap-2">
            <RiMoonLine className="size-5 shrink-0 text-foreground-icon-secondary" aria-hidden />
            <span className="text-body-medium text-text-secondary">Dark mode</span>
          </span>
          <SwitchTrack state={state} size="sm" shape="pill" />
        </>
      )}
    </AriaSwitch>
  ));
}

