 * pipeline, approval chain). Pair with TimelineHorizontalItem.
 *
 *   <TimelineHorizontal aria-label="转存进度">
 *     <TimelineHorizontalItem title="创建" tone="success" />
 *     <TimelineHorizontalItem title="转存中" tone="info" />
 *     <TimelineHorizontalItem title="完成" />
 *   </TimelineHorizontal>
 */

export type TimelineHorizontalItemTone =
  | "neutral"
  | "success"
  | "warning"
  | "error"
  | "info";

export type TimelineHorizontalItemStatus = "complete" | "current" | "upcoming";

export interface TimelineHorizontalItemProps
  extends Omit<HTMLAttributes<HTMLLIElement>, "title"> {
  title: ReactNode;
  description?: ReactNode;
  tone?: TimelineHorizontalItemTone;
  /** Visual weight: completed, active, or upcoming. Default inferred from tone. */
  status?: TimelineHorizontalItemStatus;
  /** Leading glyph; defaults to a filled / ringed dot. */
  indicator?: ReactNode;
  ref?: Ref<HTMLLIElement>;
}

export interface TimelineHorizontalProps extends HTMLAttributes<HTMLOListElement> {
  children?: ReactNode;
  ref?: Ref<HTMLOListElement>;
}

const tones = sortCx({
  neutral: "bg-foreground-icon-quaternary",
  success: "bg-status-lime-text",
  warning: "bg-status-yellow-text",
  error: "bg-status-rose-text",
  info: "bg-status-blue-text",
});

const ringByStatus = sortCx({
  complete: "ring-4 ring-background-primary-default",
  current: "ring-4 ring-status-blue-background",
  upcoming: "ring-4 ring-background-primary-default",
});

function resolveStatus(
  status: TimelineHorizontalItemStatus | undefined,
  tone: TimelineHorizontalItemTone,
): TimelineHorizontalItemStatus {
  if (status) return status;
  if (tone === "success") return "complete";
  if (tone === "info" || tone === "warning" || tone === "error") return "current";
  return "upcoming";
}

export function TimelineHorizontal({
  className,
  ref,
  children,
  ...props
}: TimelineHorizontalProps) {
  return (
    <ol
      ref={ref}
      className={cx("flex w-full list-none items-start gap-0 p-0", className)}
      {...props}
    >
      {children}
    </ol>
  );
}

export function TimelineHorizontalItem({
  title,
  description,
  tone = "neutral",
  status,
  indicator,
  className,
  ref,
  ...props
}: TimelineHorizontalItemProps) {
  const resolved = resolveStatus(status, tone);
  const upcoming = resolved === "upcoming";

  return (
    <li
      ref={ref}
      className={cx(
        "relative flex min-w-0 flex-1 flex-col items-center text-center",
        "last:[&>[data-timeline-rail]]:hidden",
        className,
      )}
      data-status={resolved}
      {...props}
    >
      {/* Real rail — `after:bg-border-secondary-*` is transparent in docs theme. */}
      <span
        data-timeline-rail
        aria-hidden
        className="pointer-events-none absolute start-[calc(50%+10px)] end-[calc(-50%+10px)] top-[11px] h-px bg-separator-border"
      />
      <div className="relative z-10 flex h-6 w-6 shrink-0 items-center justify-center">
        {indicator ?? (
          <span
            aria-hidden
            className={cx(
              "size-2.5 rounded-full",
              ringByStatus[resolved],
              upcoming ? "bg-background-tertiary-default" : tones[tone],
            )}
          />
        )}
      </div>
      <div className="mt-2 min-w-0 px-1">
        <div
          className={cx(
            "text-body-medium",
            upcoming ? "text-text-tertiary" : "text-text-primary",
          )}
        >
          {title}
        </div>
        {description ? (
          <div className="mt-0.5 text-caption-1-regular text-text-tertiary">{description}</div>
        ) : null}
      </div>
    </li>
  );
}

"use client";

import { useEffect, useId, useState, useSyncExternalStore } from "react";
import type { ComponentType, ReactNode } from "react";
import {
  Notification,
  NotificationViewport,
  type NotificationAction,
  type NotificationAvatar,
  type NotificationPosition,
  type NotificationStatus,
} from "../notification/notification";
import { cx } from "@/lib/utils";

/**
 * Toast — fire-and-forget notifications from anywhere in the app:
 *
 *   toast.success("Changes saved");
 *   toast.error("Upload failed", { description: "The file is over 20MB." });
 *   const id = toast("Exporting…", { duration: Infinity });
 *   toast.update(id, { title: "Export ready", status: "success", duration: 4000 });
 *   toast.dismiss(id);
 *
 * Render one <Toaster /> near the root of the app. It draws each toast as a
 * Notification card inside a NotificationViewport, so toasts share the
 * card, status icons, countdown bar, enter and exit motion, and the spring
 * that closes the stack's gaps. Extra Toasters render nothing, so a second
 * one in a nested layout never doubles every toast.
 *
 * The region is a polite live region (errors are announced as alerts). Every
 * countdown pauses while the pointer or keyboard focus is inside the stack,
 * so nobody loses a toast while reading it or reaching for its action.
 */

type IconComponent = ComponentType<{ className?: string; "aria-hidden"?: boolean | "true" | "false" }>;

export type ToastId = string | number;

export interface ToastOptions {
  /** Reuse an id to replace a toast that is still showing. */
  id?: ToastId;
  description?: ReactNode;
  status?: NotificationStatus;
  /** Custom leading icon; defaults to the status icon. */
  icon?: IconComponent;
  avatar?: NotificationAvatar;
  /** Small buttons under the message. Pressing one also dismisses the toast. */
  actions?: NotificationAction[];
  /** Milliseconds before it dismisses itself; `Infinity` keeps it until closed. Default from the Toaster (5000). */
  duration?: number;
  /** Show the close button. Default true. */
  dismissible?: boolean;
  /** Called once the toast has left the screen. */
  onDismiss?: () => void;
}

interface ToastRecord extends ToastOptions {
  id: ToastId;
  title: ReactNode;
  dismissed: boolean;
}

/* -------------------------------------------------------------------- store */

let toasts: ToastRecord[] = [];
let nextId = 1;
const listeners = new Set<() => void>();

function emit() {
  for (const listener of listeners) listener();
}

function subscribe(listener: () => void) {
  listeners.add(listener);
  return () => {
    listeners.delete(listener);
  };
}

function show(title: ReactNode, options: ToastOptions = {}): ToastId {
  const id = options.id ?? nextId++;
  const record: ToastRecord = { ...options, id, title, dismissed: false };
  const existing = toasts.findIndex((item) => item.id === id);
  toasts = existing >= 0 ? toasts.map((item, index) => (index === existing ? record : item)) : [...toasts, record];
  emit();
  return id;
}

function remove(id: ToastId) {
  const record = toasts.find((item) => item.id === id);
  toasts = toasts.filter((item) => item.id !== id);
  emit();
  record?.onDismiss?.();
}

/** Show a toast. Returns its id, for `toast.update` and `toast.dismiss`. */
export function toast(title: ReactNode, options?: ToastOptions): ToastId {
  return show(title, options);
}

toast.success = (title: ReactNode, options?: Omit<ToastOptions, "status">) => show(title, { ...options, status: "success" });
toast.error = (title: ReactNode, options?: Omit<ToastOptions, "status">) => show(title, { ...options, status: "error" });
toast.info = (title: ReactNode, options?: Omit<ToastOptions, "status">) => show(title, { ...options, status: "information" });

/** Change a toast that is showing. A new `duration` restarts its countdown. */
toast.update = (id: ToastId, options: ToastOptions & { title?: ReactNode }) => {
  const current = toasts.find((item) => item.id === id && !item.dismissed);
  if (!current) return;
  const { title = current.title, ...rest } = options;
  show(title, { ...current, ...rest, id });
};

/** Dismiss one toast, or every toast when called without an id. */
toast.dismiss = (id?: ToastId) => {
  toasts = toasts.map((item) => (id === undefined || item.id === id ? { ...item, dismissed: true } : item));
  emit();
};

/* ------------------------------------------------------------------ toaster */

// Only the first mounted Toaster draws the stack; the rest stand by and take
// over if it unmounts.
let owners: string[] = [];
const ownerListeners = new Set<() => void>();

function subscribeOwners(listener: () => void) {
  ownerListeners.add(listener);
  return () => {
    ownerListeners.delete(listener);
  };
}

export interface ToasterProps {
  /** Edge or corner the stack is anchored to. Default `bottom-end`. */
  position?: NotificationPosition;
  /** How many toasts show at once; older ones leave as new ones arrive. Default 3. */
  limit?: number;
  /** Default countdown in milliseconds. Default 5000. */
  duration?: number;
  /** Accessible name of the region. */
  "aria-label"?: string;
  /** Accessible name of each toast's close button. */
  closeLabel?: string;
  className?: string;
}

export function Toaster({
  position = "bottom-end",
  limit = 3,
  duration = 5000,
  "aria-label": ariaLabel = "Notifications",
  closeLabel,
  className,
}: ToasterProps) {
  const ownerId = useId();
  const items = useSyncExternalStore(subscribe, () => toasts, () => toasts);
  const isOwner = useSyncExternalStore(subscribeOwners, () => owners[0] === ownerId, () => false);
  const [hovered, setHovered] = useState(false);
  const [focused, setFocused] = useState(false);

  useEffect(() => {
    owners = [...owners, ownerId];
    ownerListeners.forEach((listener) => listener());
    return () => {
      owners = owners.filter((owner) => owner !== ownerId);
      ownerListeners.forEach((listener) => listener());
    };
  }, [ownerId]);

  // Past the limit, the oldest toasts play their exit and make room.
  useEffect(() => {
    if (!isOwner) return;
    const active = items.filter((item) => !item.dismissed);
    if (active.length > limit) {
      const overflow = new Set(active.slice(0, active.length - limit).map((item) => item.id));
      toasts = toasts.map((item) => (overflow.has(item.id) ? { ...item, dismissed: true } : item));
      emit();
    }
  }, [items, limit, isOwner]);

  // A toast removed from under the pointer or focus fires no leave or blur,
  // so an emptied stack resets both, or the next toast would start paused.
  const empty = items.length === 0;
  const [wasEmpty, setWasEmpty] = useState(empty);
  if (empty !== wasEmpty) {
    setWasEmpty(empty);
    if (empty) {
      setHovered(false);
      setFocused(false);
    }
  }

  if (!isOwner) return null;

  return (
    <NotificationViewport
      position={position}
      aria-label={ariaLabel}
      role="region"
      aria-live="polite"
      aria-relevant="additions text"
      className={cx("z-130", className)}
      onPointerEnter={() => setHovered(true)}
      onPointerLeave={() => setHovered(false)}
      onFocus={() => setFocused(true)}
      onBlur={(event) => {
        if (!event.currentTarget.contains(event.relatedTarget as Node | null)) setFocused(false);
      }}
    >
      {items.map((item) => {
        const timeout = item.duration ?? duration;
        return (
          <Notification
            // A toast replaced under the same id remounts, so its countdown restarts.
            key={`${item.id}:${timeout}`}
            title={item.title}
            description={item.description}
            status={item.status}
            icon={item.icon}
            avatar={item.avatar}
            dismissible={item.dismissible ?? true}
            closeLabel={closeLabel}
            actions={item.actions?.map((action) => ({
              ...action,
              onClick: () => {
                action.onClick?.();
                toast.dismiss(item.id);
              },
            }))}
            autoDismissDuration={Number.isFinite(timeout) && timeout > 0 ? timeout : undefined}
            paused={hovered || focused}
            dismissed={item.dismissed}
            introDelay={0}
            onDismiss={() => remove(item.id)}
          />
        );
      })}
    </NotificationViewport>
  );
}

"use client";

import {
  Children,
  useCallback,
  useEffect,
  useId,
  useMemo,
  useRef,
  useState,
  type ReactNode,
  type RefObject,
} from "react";
import {
  OverlayArrow as AriaOverlayArrow,
  Tooltip as AriaTooltip,
  TooltipContext,
  TooltipTriggerStateContext,
} from "react-aria-components";
import type { TooltipProps as AriaTooltipProps } from "react-aria-components";
import { cx, sortCx } from "@/lib/utils";
import { useDirection } from "../../foundations/direction/direction";

/**
 * Light-surface tooltip, styled to match the card / dropdown family:
 *   surface  bg background/primary/default (white), 1px border/button/default,
 *            radius/lg (8px), shadow/dropdown, text/primary.
 *   sizes    sm → px 10 py 6, Caption 1/Medium (12px)
 *            md → px 12 py 8, Body 1/Medium   (14px)
 *   arrow    filled caret (background/primary/default); a distinct path per
 *            side (not one path rotated with CSS) faces the trigger via
 *            OverlayArrow's `placement` render prop — see `TOOLTIP_CARETS` below.
 *
 * Surface / positioning still come from react-aria's Tooltip. Open / close is
 * owned here with plain mouseenter / mouseleave / focus / blur — RAC's
 * TooltipTrigger only opens hover when `getInteractionModality() === "pointer"`,
 * which silently no-ops for JoyUI's plain `<button>` path in the docs preview.
 *
 *   <TooltipTrigger delay={0}>
 *     <Button>Hover me</Button>
 *     <Tooltip size="md">Helpful copy</Tooltip>
 *   </TooltipTrigger>
 *
 * The tooltip surface itself is non-interactive, so moving off the trigger
 * never keeps it open and tooltip copy cannot be selected accidentally.
 */

export type TooltipSize = "sm" | "md";

const sizes = sortCx({
  sm: "px-2.5 py-1.5 text-caption-1-medium",
  md: "px-3 py-2 text-body-medium rounded-2lg",
});

/**
 * One hand-drawn caret per placement instead of a single path rotated with
 * CSS `transform`. Rotating a non-square (12×7) SVG changes its *visual*
 * footprint (7×12 at 90°) but not its *layout* box — `transform` never
 * affects layout — so `OverlayArrow` (which sizes/positions the arrow using
 * its unrotated 12×7 box) leaves a real ~2.5px gap between the rotated
 * triangle and the tooltip body for `left`/`right`. Each entry below instead
 * has `width`/`height` matching its own true rendered footprint, so the
 * layout box is always exactly right — no transform, no gap.
 *
 * Each path is left open on the edge touching the tooltip body (no "Z", so
 * only the two other edges get a stroke), and `shadow` points further along
 * the direction the tip already points — past the tip, never back toward the
 * body — matching the one spot that already looked right by default.
 */
export const TOOLTIP_CARETS = sortCx({
  top: { width: 12, height: 7, path: "M0 0 L6 6 L12 0", shadow: "0 1.5px 1px" },
  bottom: { width: 12, height: 7, path: "M0 7 L6 1 L12 7", shadow: "0 -1.5px 1px" },
  // left/right carets stick out sideways from the body; their shadow should
  // still fall *downward* (light-from-top, matching the body's shadow-dropdown)
  // rather than horizontally, which read as floating.
  left: { width: 7, height: 12, path: "M0 0 L6 6 L0 12", shadow: "0 1.5px 1px" },
  right: { width: 7, height: 12, path: "M7 0 L1 6 L7 12", shadow: "0 1.5px 1px" },
});

export interface TooltipProps extends Omit<AriaTooltipProps, "children"> {
  children?: ReactNode;
  /** Surface size. `sm` → 12px Caption 1, `md` → 14px Body 1. Default `sm`. */
  size?: TooltipSize;
  /** Show the little caret pointing at the trigger. Default `true`. */
  showArrow?: boolean;
}

export function Tooltip({ children, className, size = "sm", showArrow = true, offset = 10, ...props }: TooltipProps) {
  const direction = useDirection();
  return (
    <AriaTooltip
      dir={direction}
      offset={offset}
      {...props}
      className={(state) =>
        cx(
          "pointer-events-none z-120 max-w-[240px] select-none rounded-lg border border-border-button-default bg-background-primary-default text-text-primary shadow-dropdown",
          sizes[size],
          // Blur + scale in/out. react-aria stamps `data-entering` on mount then
          // removes it (transition to base), and holds the element mounted while
          // `data-exiting` is set so the same transition plays in reverse. The
          // `transition` utility covers scale, filter (blur) and opacity.
          "transition duration-200 ease-out",
          "data-[entering]:scale-90 data-[entering]:opacity-0 data-[entering]:blur-[4px]",
          "data-[exiting]:scale-90 data-[exiting]:opacity-0 data-[exiting]:blur-[4px]",
          typeof className === "function" ? className(state) : className,
        )
      }
    >
      {showArrow && (
        <AriaOverlayArrow>
          {({ placement }) => {
            // `placement` includes react-aria's `"center"` (for other overlay
            // types); this tooltip only ever resolves to one of our 4 sides.
            const caret = TOOLTIP_CARETS[placement as keyof typeof TOOLTIP_CARETS] ?? TOOLTIP_CARETS.top;
            return (
              <svg
                width={caret.width}
                height={caret.height}
                viewBox={`0 0 ${caret.width} ${caret.height}`}
                className="block overflow-visible fill-background-primary-default stroke-border-button-default"
                style={{ filter: `drop-shadow(${caret.shadow} rgb(0 0 0 / 0.05))` }}
              >
                <path d={caret.path} />
              </svg>
            );
          }}
        </AriaOverlayArrow>
      )}
      {children}
    </AriaTooltip>
  );
}

export interface TooltipTriggerProps {
  children: ReactNode;
  /** Open delay in ms. Default `0`. */
  delay?: number;
  /** Close delay in ms. Default `0`. */
  closeDelay?: number;
  isDisabled?: boolean;
  isOpen?: boolean;
  defaultOpen?: boolean;
  onOpenChange?: (isOpen: boolean) => void;
  /** When `"focus"`, only keyboard / focus opens the tooltip. */
  trigger?: "focus";
}

export function TooltipTrigger({
  delay = 0,
  closeDelay = 0,
  children,
  isDisabled = false,
  isOpen: controlledOpen,
  defaultOpen = false,
  onOpenChange,
  trigger,
}: TooltipTriggerProps) {
  const childArray = Children.toArray(children);
  const triggerChild = childArray[0];
  const rest = childArray.slice(1);

  const triggerRef = useRef<HTMLSpanElement | null>(null);
  const tooltipId = useId();
  const openTimer = useRef<number | null>(null);
  const closeTimer = useRef<number | null>(null);
  const [uncontrolledOpen, setUncontrolledOpen] = useState(defaultOpen);
  const isControlled = controlledOpen != null;
  const isOpen = isControlled ? Boolean(controlledOpen) : uncontrolledOpen;

  const setOpen = useCallback(
    (next: boolean) => {
      if (!isControlled) setUncontrolledOpen(next);
      onOpenChange?.(next);
    },
    [isControlled, onOpenChange],
  );

  const clearTimers = useCallback(() => {
    if (openTimer.current != null) {
      window.clearTimeout(openTimer.current);
      openTimer.current = null;
    }
    if (closeTimer.current != null) {
      window.clearTimeout(closeTimer.current);
      closeTimer.current = null;
    }
  }, []);

  const open = useCallback(
    (immediate = false) => {
      if (isDisabled) return;
      clearTimers();
      if (immediate || delay <= 0) setOpen(true);
      else openTimer.current = window.setTimeout(() => setOpen(true), delay);
    },
    [clearTimers, delay, isDisabled, setOpen],
  );

  const close = useCallback(
    (immediate = false) => {
      clearTimers();
      if (immediate || closeDelay <= 0) setOpen(false);
      else closeTimer.current = window.setTimeout(() => setOpen(false), closeDelay);
    },
    [clearTimers, closeDelay, setOpen],
  );

  useEffect(() => () => clearTimers(), [clearTimers]);

  useEffect(() => {
    if (!isOpen) return;
    const onKeyDown = (event: KeyboardEvent) => {
      if (event.key === "Escape") {
        event.stopPropagation();
        close(true);
      }
    };
    document.addEventListener("keydown", onKeyDown, true);
    return () => document.removeEventListener("keydown", onKeyDown, true);
  }, [close, isOpen]);

  // Shape expected by RAC `Tooltip` (open/close/isOpen/shouldSkipAnimation).
  const state = useMemo(
    () => ({
      isOpen,
      open: (immediate?: boolean) => open(Boolean(immediate)),
      close: (immediate?: boolean) => close(Boolean(immediate)),
      shouldSkipAnimation: false,
    }),
    [close, isOpen, open],
  );

  return (
    <TooltipTriggerStateContext.Provider value={state as never}>
      <TooltipContext.Provider
        value={
          {
            id: isOpen ? tooltipId : undefined,
            triggerRef: triggerRef as RefObject<Element | null>,
          } as never
        }
      >
        <span
          ref={triggerRef}
          className="inline-flex max-w-full"
          aria-describedby={isOpen ? tooltipId : undefined}
          onMouseEnter={() => {
            if (trigger === "focus") return;
            open(false);
          }}
          onMouseLeave={() => {
            if (trigger === "focus") return;
            close(false);
          }}
          onFocus={() => open(false)}
          onBlur={() => close(true)}
          onPointerDown={() => close(true)}
        >
          {triggerChild}
        </span>
        {rest}
      </TooltipContext.Provider>
    </TooltipTriggerStateContext.Provider>
  );
}

"use client";

import { useContext, useState } from "react";
import type { ComponentProps, ComponentType, ContextType, KeyboardEventHandler, ReactNode, Ref } from "react";
import { AnimatePresence, motion, useIsPresent, useReducedMotion } from "motion/react";
import { RiArrowRightSLine, RiFileLine, RiFolder3Line, RiFolderOpenLine } from "@remixicon/react";
import {
  Button as AriaButton,
  CollectionRendererContext,
  DefaultCollectionRenderer,
  Tree as AriaTree,
  TreeItem as AriaTreeItem,
  TreeItemContent,
  TreeStateContext,
} from "react-aria-components";
import type {
  Key,
  TreeProps as AriaTreeProps,
  TreeItemProps as AriaTreeItemProps,
} from "react-aria-components";
import { useDirection } from "../../foundations/direction/direction";
import { MENU_ITEM_ACTIVE } from "../dropdown/menu-styles";
import { cx } from "@/lib/utils";

type IconComponent = ComponentType<{
  className?: string;
  "aria-hidden"?: boolean | "true" | "false";
}>;

export interface TreeViewProps<T extends object> extends AriaTreeProps<T> {
  /** Medium rows are 36px tall; small rows are 32px. */
  size?: "sm" | "md";
  /** Show connected trunks and curved branches beside nested rows. */
  showGuides?: boolean;
  onKeyDownCapture?: KeyboardEventHandler<HTMLDivElement>;
  ref?: Ref<HTMLDivElement>;
}

/**
 * A source-owned tree for nested folders and structured content. React Aria
 * manages expansion, selection, typeahead, and locale-aware keyboard navigation.
 * Supply an aria-label or aria-labelledby and stable, unique item ids.
 * The tree grows with its content, leaving scrolling to the enclosing page.
 */
export function TreeView<T extends object>({
  size = "md",
  showGuides = true,
  selectionMode = "single",
  renderEmptyState = () => "No items.",
  className,
  onKeyDownCapture,
  ref,
  ...props
}: TreeViewProps<T>) {
  const direction = useDirection();
  const parentRenderer = useContext(CollectionRendererContext);
  const renderer = parentRenderer === DefaultCollectionRenderer && !props.dragAndDropHooks
    ? TREE_VIEW_RENDERER
    : parentRenderer;

  return (
    <div
      className="contents"
      onKeyDownCapture={(event) => {
        onKeyDownCapture?.(event);
        if (event.defaultPrevented || event.altKey || event.ctrlKey || event.metaKey || event.shiftKey) return;
        if (event.key !== (direction === "rtl" ? "ArrowLeft" : "ArrowRight")) return;
        const row = event.target;
        if (!(row instanceof HTMLElement) || row.getAttribute("role") !== "row" || row.getAttribute("aria-expanded") !== "true") return;

        // React Aria expands closed branches and handles parent navigation.
        // Complete forward navigation for an already-expanded branch, skipping
        // disabled rows. Focusing the child also updates React Aria's focus state.
        const level = Number(row.getAttribute("aria-level"));
        const tree = row.closest('[role="treegrid"]');
        const rows = Array.from(tree?.querySelectorAll<HTMLElement>('[role="row"][data-key]') ?? [])
          .filter((item) => item.closest('[role="treegrid"]') === tree && !item.closest('[data-tree-view-exiting]'));
        for (let index = rows.indexOf(row) + 1; index < rows.length; index++) {
          const child = rows[index];
          if (Number(child.getAttribute("aria-level")) <= level) break;
          if (child.getAttribute("aria-disabled") !== "true") {
            event.preventDefault();
            event.stopPropagation();
            child.focus();
            return;
          }
        }
      }}
    >
      <CollectionRendererContext.Provider value={renderer}>
        <AriaTree
          {...props}
          ref={ref}
          selectionMode={selectionMode}
          data-size={size}
          data-show-guides={showGuides}
          renderEmptyState={renderEmptyState}
          className={(state) => cx(
            "group/tree-view flex w-full min-w-0 flex-col rounded-3xl border border-border-button-default bg-background-primary-default p-2 outline-none",
            renderer === TREE_VIEW_RENDERER ? "gap-0" : "gap-0.5",
            "data-[empty]:px-4 data-[empty]:py-8 data-[empty]:text-center data-[empty]:text-body-regular data-[empty]:text-text-tertiary",
            "data-[focus-visible]:ring-2 data-[focus-visible]:ring-border-focus-ring",
            typeof className === "function" ? className(state) : className,
          )}
        />
      </CollectionRendererContext.Provider>
    </div>
  );
}

export interface TreeViewItemProps<T extends object = object>
  extends Omit<AriaTreeItemProps<T>, "textValue" | "children"> {
  /** Visible label, also used for accessible naming and typeahead by default. */
  label: string;
  textValue?: string;
  /** Defaults to a folder for branches and a file for leaves. null hides it. */
  icon?: IconComponent | null;
  /** Optional replacement icon while a branch is open. */
  expandedIcon?: IconComponent;
  iconClassName?: string;
  /** Optional metadata or a badge at the end of the row. */
  trailingContent?: ReactNode;
  /** Nested TreeViewItem elements or a TreeViewCollection. */
  children?: ReactNode;
  ref?: Ref<HTMLDivElement>;
}

export function TreeViewItem<T extends object = object>({
  label,
  textValue = label,
  icon,
  expandedIcon,
  iconClassName,
  trailingContent,
  children,
  className,
  style,
  ref,
  ...props
}: TreeViewItemProps<T>) {
  const direction = useDirection();

  return (
    <AriaTreeItem
      {...props}
      ref={ref}
      textValue={textValue}
      style={(state) => ({
        paddingInlineStart: `calc(0.5rem + ${(state.level - 1)} * 1.25rem)`,
        ...(typeof style === "function" ? style(state) : style),
      })}
      className={(state) => cx(
        "relative flex min-h-9 min-w-0 cursor-pointer items-center gap-2 rounded-xl pe-2 text-body-regular text-text-primary outline-none",
        "transition-[background-color,color,box-shadow] duration-150 motion-reduce:transition-none",
        "group-data-[size=sm]/tree-view:min-h-8 group-data-[size=sm]/tree-view:text-body-2-regular",
        (state.isHovered || state.isPressed || state.isFocusVisible) && !state.isDisabled && MENU_ITEM_ACTIVE,
        state.isSelected && MENU_ITEM_ACTIVE,
        state.isFocusVisible && "ring-2 ring-inset ring-border-focus-ring",
        state.isDisabled && "cursor-default text-text-placeholder",
        typeof className === "function" ? className(state) : className,
      )}
    >
      <TreeItemContent>
        {({ hasChildItems, isExpanded, isDisabled, level, state, id }) => {
          const Icon = icon === null ? null : (
            isExpanded && expandedIcon
              ? expandedIcon
              : icon ?? (hasChildItems ? (isExpanded ? RiFolderOpenLine : RiFolder3Line) : RiFileLine)
          );

          return (
            <>
              <TreeGuides state={state} id={id} level={level} expanded={hasChildItems && isExpanded} branchWidth={hasChildItems ? 12 : 16} direction={direction} />
              <span className="flex shrink-0 items-center gap-1">
                {hasChildItems ? (
                  <AriaButton
                    slot="chevron"
                    isDisabled={isDisabled}
                    className="flex size-5 shrink-0 cursor-pointer items-center justify-center rounded-md text-foreground-icon-tertiary outline-none transition-colors hover:text-foreground-icon-primary data-[focus-visible]:ring-2 data-[focus-visible]:ring-border-focus-ring"
                  >
                    <RiArrowRightSLine
                      aria-hidden
                      className={cx(
                        "size-4 opacity-50 transition-transform duration-150 motion-reduce:transition-none",
                        isExpanded ? "rotate-90" : direction === "rtl" && "rotate-180",
                      )}
                    />
                  </AriaButton>
                ) : (
                  // Leaves need less disclosure space. Keep root icons aligned,
                  // and pull nested leaves in so their branch stays compact.
                  <span aria-hidden className={cx("h-5 shrink-0", level > 1 ? "w-2" : "w-5")} />
                )}
                {Icon && <Icon aria-hidden className={cx(
                  "size-4 shrink-0 opacity-50",
                  hasChildItems ? "text-foreground-icon-primary" : "text-foreground-icon-secondary",
                  iconClassName,
                )} />}
              </span>
              <span className="min-w-0 flex-1 truncate text-start"><bdi>{label}</bdi></span>
              {trailingContent != null && (
                <span className="ms-auto shrink-0 text-caption-1-regular text-text-tertiary">{trailingContent}</span>
              )}
            </>
          );
        }}
      </TreeItemContent>
      {children}
    </AriaTreeItem>
  );
}

/** Use Collection for recursive rendering of data-driven trees. */
export { Collection as TreeViewCollection } from "react-aria-components";

const TREE_VIEW_RENDERER = {
  ...DefaultCollectionRenderer,
  CollectionRoot: AnimatedTreeCollection,
};

function AnimatedTreeCollection({ collection, ...props }: ComponentProps<typeof DefaultCollectionRenderer.CollectionRoot>) {
  const state = useContext(TreeStateContext);
  if (!state) return <DefaultCollectionRenderer.CollectionRoot collection={collection} {...props} />;

  return (
    <AnimatePresence initial={false}>
      {Array.from(collection).filter((node) => node.type !== "content").map((node) => (
        <AnimatedTreeRow key={node.key} state={state}>
          {node.render?.(node)}
        </AnimatedTreeRow>
      ))}
    </AnimatePresence>
  );
}

type TreeState = NonNullable<ContextType<typeof TreeStateContext>>;

function TreeGuides({ state, id, level, expanded, branchWidth, direction }: {
  state: TreeState;
  id: Key;
  level: number;
  expanded: boolean;
  branchWidth: number;
  direction: "ltr" | "rtl";
}) {
  const node = state.collection.getItem(id);
  if (!node) return null;

  // A descendant carries an outer trunk only when its ancestor has a sibling
  // still to come. This keeps the line connected through an expanded subtree,
  // while the final child's elbow closes that level of the tree.
  const continuingLevels: number[] = [];
  let ancestor = node.parentKey != null ? state.collection.getItem(node.parentKey) : null;
  let ancestorLevel = level - 1;
  while (ancestor) {
    if (ancestor.type === "item") {
      if (ancestorLevel > 1 && ancestor.nextKey != null) continuingLevels.push(ancestorLevel - 2);
      ancestorLevel--;
    }
    ancestor = ancestor.parentKey != null ? state.collection.getItem(ancestor.parentKey) : null;
  }

  const axis = (depth: number) => `calc(1.125rem + ${depth} * 1.25rem)`;

  return (
    <span aria-hidden data-tree-view-guides className="pointer-events-none absolute inset-0 text-foreground-icon-quaternary group-data-[show-guides=false]/tree-view:hidden">
      {continuingLevels.map((depth) => (
        <span key={depth} data-tree-view-trunk className="absolute -inset-y-px w-px bg-current" style={{ insetInlineStart: axis(depth) }} />
      ))}
      {level > 1 && (
        <span data-tree-view-branch className="absolute -inset-y-px" style={{ insetInlineStart: axis(level - 2), width: branchWidth }}>
          <span className="absolute start-0 top-0 w-px bg-current" style={{ bottom: "calc(50% + 6px)" }} />
          <svg
            width={branchWidth}
            height="7"
            viewBox={`0 0 ${branchWidth} 7`}
            fill="none"
            className={cx("absolute start-0", direction === "rtl" && "-scale-x-100")}
            style={{ top: "calc(50% - 6px)" }}
          >
            <path d={`M0.5 0 Q0.5 6 6.5 6 H${branchWidth - 0.5}`} stroke="currentColor" strokeWidth="1" />
          </svg>
          {node.nextKey != null && (
            <span data-tree-view-tail className="absolute start-0 bottom-0 w-px bg-current" style={{ top: "calc(50% - 6px)" }} />
          )}
        </span>
      )}
      {expanded && (
        <span data-tree-view-bridge className="absolute -bottom-px w-px bg-current" style={{ insetInlineStart: axis(level - 1), top: "calc(50% + 8px)" }} />
      )}
    </span>
  );
}

function AnimatedTreeRow({ state, children }: { state: TreeState; children: ReactNode }) {
  const isPresent = useIsPresent();
  const reduceMotion = useReducedMotion();
  const [lastPresentState, setLastPresentState] = useState(state);
  if (isPresent && lastPresentState !== state) setLastPresentState(state);

  // Preserve the row's last collection while it fades out. The live tree has
  // already removed it from keyboard navigation; the retained visual is inert.
  return (
    <motion.div
      role="presentation"
      className="relative min-w-0 shrink-0 overflow-hidden"
      data-tree-view-exiting={!isPresent || undefined}
      aria-hidden={!isPresent || undefined}
      inert={!isPresent}
      initial={reduceMotion ? false : { height: 0, paddingTop: 0, paddingBottom: 0, opacity: 0, y: -4, filter: "blur(4px)" }}
      animate={{ height: "auto", paddingTop: 1, paddingBottom: 1, opacity: 1, y: 0, filter: "blur(0px)" }}
      exit={{ height: 0, paddingTop: 0, paddingBottom: 0, opacity: 0, y: reduceMotion ? 0 : -4, filter: reduceMotion ? "blur(0px)" : "blur(4px)" }}
      transition={{ duration: reduceMotion ? 0 : 0.28, ease: [0.22, 1, 0.36, 1] }}
    >
      <TreeStateContext.Provider value={isPresent ? state : lastPresentState}>
        {children}
      </TreeStateContext.Provider>
    </motion.div>
  );
}

"use client";

import type { ComponentProps, ReactNode, Ref } from "react";
import {
