function WebSearchRun({
  steps,
  className,
  onReplay,
}: {
  steps: WebSearchStep[];
  className?: string;
  onReplay: () => void;
}) {
  const reduce = useLogMotion();
  const [sourcesOpen, setSourcesOpen] = useState(false);
  const [elapsed, setElapsed] = useState(0);
  const [done, setDone] = useState(false);

  const total = steps.length;
  const revealed = useRevealTicker({
    total,
    run: !done,
    startDelay: 280,
    stepInterval: 900,
    onComplete: () => setDone(true),
  });

  useEffect(() => {
    if (done) return;
    const started = performance.now();
    const id = window.setInterval(() => {
      setElapsed((performance.now() - started) / 1000);
    }, 100);
    return () => window.clearInterval(id);
  }, [done]);

  const visible = useMemo(() => steps.slice(0, revealed), [steps, revealed]);
  const searchCount = Math.min(
    3,
    Math.max(1, visible.filter((s) => s.kind !== "read").length || 1),
  );

  return (
    <div
      className={cx(
        "w-full max-w-xl text-body-regular text-text-secondary",
        className,
      )}
      role="status"
      aria-live="polite"
    >
      <div className="mb-1 flex items-center gap-2 text-text-secondary">
        <RiSearchLine
          aria-hidden
          className="size-4 text-foreground-icon-tertiary"
        />
        {revealed > 0 ? (
          <span>跑了 {searchCount} 次搜索</span>
        ) : (
          <ShimmerText>正在搜索…</ShimmerText>
        )}
      </div>

      <ul className="flex flex-col">
        {visible.map((step, index) => {
          const first = index === 0;
          const last = index === visible.length - 1 && done;
          return (
            <LogRow
              key={step.id}
              first={first}
              last={last}
              reduce={reduce}
              className="py-1.5"
            >
              <div className="flex items-start gap-2 pe-1">
                <StepIcon kind={step.kind} />
                <div className="min-w-0 flex-1">
                  <div className="flex items-start justify-between gap-3">
                    <p className="text-body-medium text-text-secondary">
                      {step.label}
                    </p>
                    {step.resultLabel ? (
                      <span className="shrink-0 text-caption-1-medium text-text-tertiary">
                        {step.resultLabel}
                      </span>
                    ) : null}
                  </div>
                  {step.sources ? (
                    <SourceStack
                      sources={step.sources}
                      open={sourcesOpen}
                      onToggle={() => setSourcesOpen((v) => !v)}
                    />
                  ) : null}
                </div>
              </div>
            </LogRow>
          );
        })}
      </ul>

      {!done ? (
        <WorkingRow
          reduce={reduce}
          label={`工作 ${elapsed.toFixed(1)}s`}
          className="mt-1"
        />
      ) : (
        <motion.div
          initial={reduce ? false : { opacity: 0, y: 4 }}
          animate={{ opacity: 1, y: 0 }}
          transition={{ duration: 0.3 }}
          className="mt-3"
        >
          <Button
            variant="secondary"
            size="small"
            leadingIcon={RiRefreshLine}
            onClick={onReplay}
          >
            再次运行
          </Button>
        </motion.div>
      )}
    </div>
  );
}

export function WebSearch({
  steps = DEFAULT_STEPS,
  className,
}: {
  steps?: WebSearchStep[];
  className?: string;
  autoPlay?: boolean;
}) {
  const [runKey, setRunKey] = useState(0);
  const replay = useCallback(() => setRunKey((k) => k + 1), []);

  return (
    <WebSearchRun
      key={runKey}
      steps={steps}
      className={className}
      onReplay={replay}
    />
  );
}
